+  patch: "@@ -1 +1 @@\n-export const value = 1;\n+export const value = 2;",
+});
+const fixture = FixturePullRequest.make({
+  metadata: PullRequestMetadata.make({
+    repository: "acme/widgets",
+    number: 42,
+    title: "Correct the exported value",
+    body: "",
+    baseRef: "main",
+    baseSha: "b".repeat(40),
+    headRef: "fix/value",
+    headSha: HEAD_SHA,
+    totalChangedFiles: 1,
+  }),
+  files: [
