/**
 * Shared eviction-harness machinery (plan §3): fresh stubs per call (an aborted incarnation
 * may leave a stale stub disconnected), alarm-only convergence drains, raw-storage state
 * probes through `runInDurableObject`, and the convergence property asserted after every
 * abort — the DC twin of the Node crash harness's helpers.
 */

export type TestNamespace =
  | "CONVERSATIONS"
  | "LIMITED"
  | "TINYDB"
  | "DENIED"
  | "SUBAGENTS"
  | "DYNAMIC_BINDINGS"
  | "ARRAY_BINDINGS"
  | "EFFECT_BINDINGS"
  | "TELEMETRY";

/** A FRESH stub for the named Conversation (never cache stubs across aborts). */
export const stubFor = (conversation: string, namespace: TestNamespace = "CONVERSATIONS") => {
  const binding = env[namespace];
  return binding.get(binding.idFromName(conversation));
};

/** Run one client Effect against a namespace binding through the real Worker-side client. */
export const runClient = <A, E>(
  effect: Effect.Effect<A, E, CloudflareConversationClient>,
  namespace: TestNamespace = "CONVERSATIONS",
): Promise<A> =>
  Effect.runPromise(
    effect.pipe(
      Effect.provide(
        CloudflareConversationClient.layer.pipe(
          Layer.provide(
            ConversationObjectNamespace.layer(
              env[namespace] as unknown as DurableObjectNamespace<ConversationObjectRpc>,
            ),
          ),
        ),
      ),
    ),
  );

/** Exit-capturing variant for rows whose client call is EXPECTED to die mid-eviction. */
export const runClientExit = <A, E>(
  effect: Effect.Effect<A, E, CloudflareConversationClient>,
  namespace: TestNamespace = "CONVERSATIONS",
): Promise<{ readonly ok: boolean; readonly value?: A; readonly error?: unknown }> =>
  runClient(effect.pipe(Effect.exit), namespace).then(
    (exit) =>
      exit._tag === "Success" ? { ok: true, value: exit.value } : { ok: false, error: exit.cause },
    (defect: unknown) => ({ ok: false, error: defect }),
  );

export interface LaneRow {
  readonly submission_id: string;
  readonly state: string;
  readonly queue_sequence: number;
}

const sleep = (millis: number) => new Promise((resolve) => setTimeout(resolve, millis));

/**
 * A probe issued right after `ctx.abort()` can land on the dying incarnation and reject with
 * the abort reason (production behavior: the next event reaches a fresh instance). Retry a
 * few times with fresh stubs — this mirrors what any real caller does after an eviction.
 */
const withAbortedInstanceRetry = async <A>(probe: () => Promise<A>): Promise<A> => {
  let lastError: unknown;
  for (let attempt = 0; attempt < 20; attempt++) {
    try {
      return await probe();
    } catch (error) {
      lastError = error;
      await sleep(10);
    }
  }
  throw lastError;
};

/** Raw ledger rows straight from the Object's own storage (never through an entry point). */
export const laneRows = (
  conversation: string,
  namespace: TestNamespace = "CONVERSATIONS",
): Promise<ReadonlyArray<LaneRow>> =>
  withAbortedInstanceRetry(() =>
    runInDurableObject(stubFor(conversation, namespace), (_instance, state) =>
      Effect.runPromise(
        Effect.gen(function* () {
          const sql = yield* SqlClientService.SqlClient;
          return yield* sql<LaneRow>`
            SELECT submission_id, state, queue_sequence
            FROM effect_agent_submissions
            ORDER BY queue_sequence
          `;
        }).pipe(Effect.provide(SqliteClient.layer({ storage: state.storage }))),
      ),
    ),
  );

/** The persisted alarm deadline (epoch millis) or null. */
export const scheduledAlarm = (
  conversation: string,
  namespace: TestNamespace = "CONVERSATIONS",
): Promise<number | null> =>
  withAbortedInstanceRetry(() =>
    runInDurableObject(stubFor(conversation, namespace), (_instance, state) =>
      state.storage.getAlarm(),
    ),
  );

/**
 * Alarm-only convergence: fire the persisted alarm (at-least-once; an armed eviction or a
 * typed pass failure rejects the delivery and the dirty generation keeps the slot committed)
 * until the predicate holds. NO client entry point is ever called — this is the exit gate's
 * "recovers without an incoming request" in its deterministic form: `runDurableObjectAlarm`
 * is accelerated delivery of the alarm that would fire on its own.
 *
 * Built-in invariant audit: locally actionable states observed WITHOUT a scheduled alarm
 * repeatedly are broken. Stable external waits (`suspended`, `unknown`, `joined`, and an
 * admitted child awaiting parent establishment) are intentionally allowed to quiesce.
 */
export const drainAlarmsUntil = async (
  conversation: string,
  predicate: () => Promise<boolean>,
  options?: { readonly namespace?: TestNamespace; readonly rounds?: number },
): Promise<void> => {
  const namespace = options?.namespace ?? "CONVERSATIONS";
  const rounds = options?.rounds ?? 600;
  let consecutiveIdleWithWork = 0;
  for (let round = 0; round < rounds; round++) {
    if (await predicate()) return;
    let fired = false;
    try {
      fired = await runDurableObjectAlarm(stubFor(conversation, namespace));
    } catch {
      // The pass aborted the Object (armed eviction) or failed typed (workerd would retry);
      // either way the pre-armed alarm survives in storage for the next round.
      fired = true;
    }
    if (!fired) {
      const rows = await laneRows(conversation, namespace);
      const actionable = rows.some((row) =>
        ["ready", "input-applied", "running", "joining", "terminalizing"].includes(row.state),
      );
      if (actionable) {
        consecutiveIdleWithWork += 1;
        // Actionable committed work implies a committed alarm. Allow a few rounds for a
        // concurrently-running pass to re-arm before declaring it broken.
        if (consecutiveIdleWithWork >= 20) {
          throw new Error(
            `Alarm invariant broken for ${conversation}: actionable work with no scheduled alarm`,
          );
        }
      } else {
        consecutiveIdleWithWork = 0;
      }
    } else {
      consecutiveIdleWithWork = 0;
    }
    await sleep(10);
  }
  const rows = await laneRows(conversation, namespace);
  throw new Error(
    `Alarm drain did not converge for ${conversation}; lane: ${JSON.stringify(rows)}`,
  );
};

/** Predicate: every Submission on the lane is settled (and at least one exists). */
export const allSettled =
  (conversation: string, namespace: TestNamespace = "CONVERSATIONS") =>
  async (): Promise<boolean> => {
    const rows = await laneRows(conversation, namespace);
    return rows.length > 0 && rows.every((row) => row.state === "settled");
  };

/** Predicate: some Submission on the lane is durably in `state`. */
export const anyInState =
  (conversation: string, state: string, namespace: TestNamespace = "CONVERSATIONS") =>
  async (): Promise<boolean> => {
    const rows = await laneRows(conversation, namespace);
    return rows.some((row) => row.state === state);
  };

const decodeSubmissionId = Schema.decodeSync(SubmissionId);

/** Every canonical record of the lane, through the real paged observation entry point. */
export const readCanonical = (
  conversation: string,
  namespace: TestNamespace = "CONVERSATIONS",
): Promise<ReadonlyArray<CanonicalRecordEnvelope>> =>
  runClient(
    Effect.gen(function* () {
      const client = yield* CloudflareConversationClient;
      return yield* client.readAll(decodeConversationId(conversation));
    }),
    namespace,
  );

/** The supplier-store honesty claims of one eviction row (durability §10). */
export interface SupplierExpectation {
  readonly ref: string;
  /** EXACT per-operation invocation counts; `{}` claims no external call ever happened. */
  readonly counts: Record<string, number>;
}

/**
 * The convergence property asserted after every abort (the Node crash harness's
 * `assertConvergence`, verbatim claims): every accepted Submission still exists and settled;
 * each has EXACTLY one canonical terminal record; no canonical record identity was ever
 * double-appended (stale epochs fenced, DUR-006/DUR-007); canonical inputs and settlements
 * follow the admitted FIFO order (DUR-004); and, when the row touches the external supplier,
 * no recorded result was fabricated and the invocation counts match the claim exactly.
 */
export const assertConvergence = async (
  conversation: string,
  options?: {
    readonly namespace?: TestNamespace;
    readonly supplier?: SupplierExpectation;
  },
): Promise<void> => {
  const namespace = options?.namespace ?? "CONVERSATIONS";
  const rows = await laneRows(conversation, namespace);
  expect(rows.length).toBeGreaterThan(0);
  for (const row of rows) {
    expect(row.state, `submission ${row.submission_id}`).toBe("settled");
  }
  const records = await readCanonical(conversation, namespace);
  const recordIds = records.map((envelope) => envelope.record.recordId);
  expect(new Set(recordIds).size).toBe(recordIds.length);
  const ordered = [...rows].sort((left, right) => left.queue_sequence - right.queue_sequence);
  for (const row of ordered) {
    const settled = records.filter(
      (envelope) =>
        envelope.record.recordId ===
        submissionSettlementRecordId(decodeSubmissionId(row.submission_id)),
    );
    expect(settled, `settlement record for ${row.submission_id}`).toHaveLength(1);
    expect(settled[0]?.record.payload._tag).toBe("SubmissionSettled");
  }
  const expectedInputs = ordered.map((row) =>
    submissionInputRecordId(decodeSubmissionId(row.submission_id)),
  );
  const inputOrder = recordIds.filter((recordId) =>
    expectedInputs.some((expected) => expected === recordId),
  );
  expect(inputOrder).toEqual(expectedInputs.filter((expected) => inputOrder.includes(expected)));
  // P7 §7(c) exemption: an ABORTED settlement for never-run work (no canonical `input:{sid}`
  // record) settles immediately by design — without waiting for the head — so it is excluded
  // from the FIFO settlement comparison. DUR-004 bounds EXECUTION order, which never-run work
  // has none of (mirrors `verifyConversationInvariants`).
  const abortedNeverRan = (submissionId: string): boolean =>
    !recordIds.includes(submissionInputRecordId(decodeSubmissionId(submissionId))) &&
    records.some(
      (envelope) =>
        envelope.record.recordId ===
          submissionSettlementRecordId(decodeSubmissionId(submissionId)) &&
        envelope.record.payload._tag === "SubmissionSettled" &&
        envelope.record.payload.outcome === "aborted",
    );
  const expectedSettlements = ordered
    .filter((row) => !abortedNeverRan(row.submission_id))
    .map((row) => submissionSettlementRecordId(decodeSubmissionId(row.submission_id)));
  const settlementOrder = recordIds.filter((recordId) =>
    expectedSettlements.some((expected) => expected === recordId),
  );
  expect(settlementOrder).toEqual(expectedSettlements);

  if (options?.supplier !== undefined) {
    const produced = supplierValuesFor(options.supplier.ref);
    for (const envelope of records) {
      const payload = envelope.record.payload;
      if (payload._tag === "ToolCallSettled" && payload.isFailure === false) {
        const result: unknown = payload.result;
        if (
          typeof result === "object" &&
          result !== null &&
          "confirmation" in result &&
          typeof result.confirmation === "string"
        ) {
          expect(
            produced.has(result.confirmation),
            `book result "${result.confirmation}" is absent from the supplier store — fabricated`,
          ).toBe(true);
        }
        if (
          typeof result === "object" &&
          result !== null &&
          "state" in result &&
          typeof result.state === "string" &&
          result.state.includes("+")
        ) {
          for (const part of result.state.split("+")) {
            expect(
              produced.has(part),
              `itinerary step result "${part}" is absent from the supplier store — fabricated`,
            ).toBe(true);
          }
        }
      }
      if (payload._tag === "ToolStepSettled") {
        const output: unknown = payload.output;
        if (typeof output === "string") {
          expect(
            produced.has(output),
            `step output "${output}" is absent from the supplier store — fabricated`,
          ).toBe(true);
        }
      }
    }
    expect(supplierCountsFor(options.supplier.ref)).toEqual(options.supplier.counts);
  }
};

import { Effect, Layer } from "effect";
import { OtlpExporter } from "effect/unstable/observability";

import { DurableObjectContext } from "../src/index.ts";

const flushes = new Map<string, number>();
const failingFlushes = new Set<string>();

export const flushCount = (conversationId: string): number => flushes.get(conversationId) ?? 0;

export const failNextFlush = (conversationId: string): void => {
  failingFlushes.add(conversationId);
};

/** One event-scoped OTLP flusher proving the effect-cf native RPC integration. */
export const observabilityProbeLayer = Layer.effectDiscard(
  Effect.gen(function* () {
    const { ctx } = yield* DurableObjectContext;
    const flusher = yield* OtlpExporter.Flusher;
    const conversationId = ctx.id.name ?? ctx.id.toString();
    yield* flusher.register(
      Effect.sync(() => {
        flushes.set(conversationId, flushCount(conversationId) + 1);
        if (failingFlushes.delete(conversationId)) {
          throw new Error("fixture exporter defect");
        }
      }),
    );
  }),
).pipe(Layer.provideMerge(OtlpExporter.layerFlusher));

import { ApprovalDecisionCommand, CanonicalSequence, type Receipt } from "@effect-agent/session";
import { runDurableObjectAlarm, runInDurableObject } from "cloudflare:test";
import { Cause, Effect, Option, Schema } from "effect";
import { describe, expect, it } from "vite-plus/test";

import { CloudflareConversationClient, ProgressWaitRegistry } from "../src/index.ts";
import {
  decodeConversationId,
  BOOK_TOOL_CALL_ID,
  approvalDefinition,
  plannerDefinition,
  submitOptions,
} from "./fixtures.ts";
import {
  allSettled,
  anyInState,
  drainAlarmsUntil,
  readCanonical,
  runClient,
  stubFor,
} from "./harness.ts";
import type { TestConversationObject } from "./worker.ts";

const ZERO_SEQUENCE = Schema.decodeSync(CanonicalSequence)(0);
let laneCounter = 0;
const lane = (label: string): string => `cf-progress-${label}-${laneCounter++}`;

const sleep = (millis: number) => new Promise((resolve) => setTimeout(resolve, millis));

const progressStub = (conversation: string) =>
  stubFor(conversation) as DurableObjectStub<TestConversationObject>;

const withDeadline = async <A>(promise: Promise<A>, millis = 5_000): Promise<A> =>
  Promise.race([
    promise,
    sleep(millis).then(() => {
      throw new Error(`#94 progress wait exceeded ${millis}ms`);
    }),
  ]);

const waitUntil = async (predicate: () => Promise<boolean>, millis = 5_000): Promise<void> => {
  const deadline = Date.now() + millis;
  let lastError: unknown;
  while (Date.now() < deadline) {
    try {
      if (await predicate()) return;
    } catch (error) {
      lastError = error;
    }
    await sleep(5);
  }
  throw lastError ?? new Error(`#94 condition was not reached within ${millis}ms`);
};

const submitPlanner = (conversation: string) =>
  runClient(
    Effect.gen(function* () {
      const client = yield* CloudflareConversationClient;
      return yield* client.submit(
        { definition: plannerDefinition },
        { question: "observe durable progress", ref: conversation },
        submitOptions(conversation, `${conversation}-key`),
      );
    }),
  );

const submitApproval = (conversation: string) =>
  runClient(
    Effect.gen(function* () {
      const client = yield* CloudflareConversationClient;
      return yield* client.submit(
        { definition: approvalDefinition },
        { question: "hold for approval", ref: conversation },
        submitOptions(conversation, `${conversation}-key`),
      );
    }),
  );

const prepareApproval = async (
  conversation: string,
): Promise<{ readonly receipt: Receipt; readonly cursor: CanonicalSequence }> => {
  const receipt = await submitApproval(conversation);
  await drainAlarmsUntil(conversation, anyInState(conversation, "suspended"));
  const cursor = (await readCanonical(conversation)).at(-1)?.sequence;
  if (cursor === undefined) throw new Error("approval lane did not materialize canonical history");
  return { receipt, cursor };
};

const approve = (conversation: string, receipt: Receipt) =>
  runClient(
    Effect.gen(function* () {
      const client = yield* CloudflareConversationClient;
      return yield* client.resolveApproval(
        decodeConversationId(conversation),
        ApprovalDecisionCommand.make({
          submissionId: receipt.submissionId,
          toolCallId: BOOK_TOOL_CALL_ID,
          decision: "approved",
          resolver: "#94-test-approver",
          reason: "release the durable progress test",
        }),
      );
    }),
  );

const awaitProgress = (conversation: string, afterSequence: CanonicalSequence) =>
  runClient(
    Effect.gen(function* () {
      const client = yield* CloudflareConversationClient;
      yield* client.awaitProgress(decodeConversationId(conversation), afterSequence);
    }),
  );

const awaitCanonicalTag = (conversation: string, afterSequence: CanonicalSequence, tag: string) =>
  runClient(
    Effect.gen(function* () {
      const client = yield* CloudflareConversationClient;
      const conversationId = decodeConversationId(conversation);
      let cursor = afterSequence;
      for (;;) {
        const records = yield* client.readPage(conversationId, {
          afterSequence: cursor,
          limit: 1_024,
        });
        if (records.some((record) => record.record.payload._tag === tag)) return;
        const last = records.at(-1);
        if (last !== undefined) {
          cursor = last.sequence;
          continue;
        }
        yield* client.awaitProgress(conversationId, cursor);
      }
    }),
  );

describe("#94 Cloudflare durable progress wait", () => {
  it("broadcasts cancellation across duplicate and late transport attempts", async () => {
    const completed = await withDeadline(
      Effect.runPromise(
        Effect.scoped(
          Effect.gen(function* () {
            const registry = yield* ProgressWaitRegistry;
            const first = yield* registry.subscribe("duplicate-attempt");
            const second = yield* registry.subscribe("duplicate-attempt");
            yield* registry.cancel("duplicate-attempt");
            yield* Effect.all([first, second], { concurrency: "unbounded" });

            yield* registry.cancel("late-attempt");
            const lateFirst = yield* registry.subscribe("late-attempt");
            const lateSecond = yield* registry.subscribe("late-attempt");
            yield* Effect.all([lateFirst, lateSecond], { concurrency: "unbounded" });
            return true;
          }),
        ).pipe(Effect.provide(ProgressWaitRegistry.layer)),
      ),
    );
    expect(completed).toBe(true);
  });

  it("returns for committed history and wakes promptly after a canonical append", async () => {
    const conversation = lane("append");
    await submitPlanner(conversation);

    await withDeadline(awaitProgress(conversation, ZERO_SEQUENCE));
    const before = await readCanonical(conversation);
    const cursor = before.at(-1)?.sequence;
    expect(cursor).toBeDefined();
    if (cursor === undefined) return;

    const waiting = awaitProgress(conversation, cursor);
    await waitUntil(async () => (await progressStub(conversation).progressWaiterCount()) === 1);
    const alarm = runDurableObjectAlarm(stubFor(conversation));
    await withDeadline(waiting);
    await withDeadline(alarm);

    const after = await readCanonical(conversation);
    expect(after.some((record) => record.sequence > cursor)).toBe(true);
  });

  it("broadcasts to every waiter, isolates lanes, and cleans up a timed-out caller", async () => {
    const conversation = lane("many");
    const unrelated = lane("unrelated");
    const main = await prepareApproval(conversation);
    const other = await prepareApproval(unrelated);
    const cursor = main.cursor;
    const unrelatedCursor = other.cursor;

    const first = awaitCanonicalTag(conversation, cursor, "ToolApprovalDecided");
    const second = awaitCanonicalTag(conversation, cursor, "ToolApprovalDecided");
    const timedUnrelated = runClient(
      Effect.gen(function* () {
        const client = yield* CloudflareConversationClient;
        return yield* client
          .awaitProgress(decodeConversationId(unrelated), unrelatedCursor)
          .pipe(Effect.timeoutOption("1 second"));
      }),
    );
    await waitUntil(async () => (await progressStub(conversation).progressWaiterCount()) === 2);
    await waitUntil(async () => (await progressStub(unrelated).progressWaiterCount()) === 1);

    await approve(conversation, main.receipt);
    await withDeadline(Promise.all([first, second]));
    expect(await progressStub(unrelated).progressWaiterCount()).toBe(1);

    expect(Option.isNone(await withDeadline(timedUnrelated))).toBe(true);
    await waitUntil(async () => (await progressStub(unrelated).progressWaiterCount()) === 0);
    await approve(unrelated, other.receipt);
    await drainAlarmsUntil(conversation, allSettled(conversation));
    await drainAlarmsUntil(unrelated, allSettled(unrelated));
  }, 20_000);

  it("reconnects after eviction, reconstructs the wait, and rechecks durable authority", async () => {
    const conversation = lane("eviction");
    const approval = await prepareApproval(conversation);
    const cursor = approval.cursor;

    const waiting = awaitProgress(conversation, cursor);
    await waitUntil(async () => (await progressStub(conversation).progressWaiterCount()) === 1);
    const priorIncarnation = await progressStub(conversation).progressIncarnation();
    await runInDurableObject(stubFor(conversation), (_instance, state) => {
      state.abort("#94 forced wait eviction");
    }).catch(() => undefined);

    await waitUntil(async () => {
      const stub = progressStub(conversation);
      return (
        (await stub.progressIncarnation()) !== priorIncarnation &&
        (await stub.progressWaiterCount()) === 1
      );
    });

    await approve(conversation, approval.receipt);
    await withDeadline(waiting);
    await drainAlarmsUntil(conversation, allSettled(conversation));
    const after = await readCanonical(conversation);
    expect(after.some((record) => record.sequence > cursor)).toBe(true);
  }, 20_000);

  it("delivers the remote wake seam used by child, parent, and host settlement", async () => {
    const conversation = lane("remote");
    const approval = await prepareApproval(conversation);
    const waiting = awaitProgress(conversation, approval.cursor);
    await waitUntil(async () => (await progressStub(conversation).progressWaiterCount()) === 1);

    await stubFor(conversation).wake();
    await withDeadline(waiting);
    expect(await progressStub(conversation).progressWaiterCount()).toBe(0);
    await approve(conversation, approval.receipt);
    await drainAlarmsUntil(conversation, allSettled(conversation));
  });

  it("preserves the typed non-materialized failure across the RPC client boundary", async () => {
    const conversation = lane("missing");
    const tag = await runClient(
      Effect.gen(function* () {
        const client = yield* CloudflareConversationClient;
        const exit = yield* Effect.exit(
          client.awaitProgress(decodeConversationId(conversation), ZERO_SEQUENCE),
        );
        if (exit._tag === "Success") return "success";
        const error = Cause.findErrorOption(exit.cause);
        if (Option.isNone(error)) return "defect";
        const value: unknown = error.value;
        return typeof value === "object" && value !== null && "_tag" in value
          ? String(value._tag)
          : "unknown";
      }),
    );
    expect(tag).toBe("ConversationNotMaterialized");
  });

  it("preserves a typed authorization denial across the RPC client boundary", async () => {
    const conversation = lane("denied");
    const tag = await runClient(
      Effect.gen(function* () {
        const client = yield* CloudflareConversationClient;
        const exit = yield* Effect.exit(
          client.awaitProgress(decodeConversationId(conversation), ZERO_SEQUENCE),
        );
        if (exit._tag === "Success") return "success";
        const error = Cause.findErrorOption(exit.cause);
        if (Option.isNone(error)) return "defect";
        const value: unknown = error.value;
        return typeof value === "object" && value !== null && "_tag" in value
          ? String(value._tag)
          : "unknown";
      }),
      "DENIED",
    );
    expect(tag).toBe("OperationDenied");
  });
});

