import { ConversationId, SubmissionId, ToolCallId } from "@effect-agent/core";
import { DateTime, Schema } from "effect";

import {
  AbortIntent,
  AbortCommand,
  ApprovalDecisionIntent,
  ChildAttachmentSnapshot,
  JoinSnapshot,
  ParentLinkage,
  QueueSequence,
  SubmissionState,
  SuspensionSnapshot,
  UnknownResolutionIntent,
  type RecoverySnapshot,
} from "./ledger.ts";
import { CanonicalSequence, SettlementOutcome, ToolCallUnknown } from "./records.ts";
import {
  OpenDelegationCallEvidence,
  OpenToolCallEvidence,
  PendingApprovalEvidence,
  RecoveryDecision,
} from "./recovery.ts";

/**
 * Pure report logic for the P7 administrative operations (plan §3): the Schema classes carried
 * by `DurableAgentRuntime.explain`/`verify`/`scanObligations`, the operator meaning table for
 * every recovery decision tag, and the text renderer. Everything here is pure — no port access,
 * no clocks, no writes — so hosts, CLIs, and wire envelopes share one report vocabulary.
 */

const BoundedDetail = Schema.String.check(Schema.isMaxLength(4_096));

/** Non-negative whole seconds derived from Clock time; deterministic under TestClock. */
const AgeSeconds = Schema.Int.check(Schema.isGreaterThanOrEqualTo(0));

// ---------------------------------------------------------------------------
// explain — RecoveryExplanation
// ---------------------------------------------------------------------------

/**
 * The disposition family of `RecoveryReport`, reused verbatim so an explanation predicts exactly
 * what `runRecovery`/`retry` would report for the same decision.
 */
export const RecoveryDisposition = Schema.Literals(["repaired", "deferred", "none", "unknown"]);
export type RecoveryDisposition = typeof RecoveryDisposition.Type;

/** Submission identity, lane position, and Clock-derived ages (DUR-017 obligation visibility). */
export class ExplainedSubmission extends Schema.Class<ExplainedSubmission>(
  "@effect-agent/session/ExplainedSubmission",
)({
  submissionId: SubmissionId,
  conversationId: ConversationId,
  state: SubmissionState,
  queueSequence: QueueSequence,
  createdAt: Schema.DateTimeUtcFromString,
  readyAt: Schema.optionalKey(Schema.DateTimeUtcFromString),
  /** Whole seconds since admission (`createdAt`). */
  ageSeconds: AgeSeconds,
  /** Whole seconds since readiness, present exactly when `readyAt` is recorded. */
  readyAgeSeconds: Schema.optionalKey(AgeSeconds),
  parentLinkage: Schema.optionalKey(ParentLinkage),
}) {}

/** One durable Unknown Outcome and whether a covering resolution intent exists (DUR-017). */
export class ExplainedUnknownCall extends Schema.Class<ExplainedUnknownCall>(
  "@effect-agent/session/ExplainedUnknownCall",
)({
  toolCallId: ToolCallId,
  toolName: ToolCallUnknown.fields.toolName,
  reason: ToolCallUnknown.fields.reason,
  recordedAt: Schema.DateTimeUtcFromString,
  /** A durable `resolveUnknown` intent covers this call. */
  resolved: Schema.Boolean,
}) {}

/**
 * The evidence summary of one explanation: the classifier's canonical-history inputs plus the
 * durable intents and subagent attachments the ledger snapshot carries. Everything is read-only
 * observation — assembling this value performs zero writes.
 */
export class ExplainedEvidence extends Schema.Class<ExplainedEvidence>(
  "@effect-agent/session/ExplainedEvidence",
)({
  conversationMaterialized: Schema.Boolean,
  inputRecorded: Schema.Boolean,
  abortRecorded: Schema.Boolean,
  recordedSettlementOutcome: Schema.optionalKey(SettlementOutcome),
  /** Prepared ordinary Tool Calls without a canonical outcome (DUR-009). */
  openToolCalls: Schema.Array(OpenToolCallEvidence),
  /** Delegation Tool Calls with an open parent-side obligation (spec/subagents.md §13). */
  openDelegationCalls: Schema.Array(OpenDelegationCallEvidence),
  /** Canonically requested approvals without a canonical decision. */
  approvalsPending: Schema.Array(PendingApprovalEvidence),
  /** Durable Unknown Outcomes with their resolution coverage (DUR-017). */
  unknownCalls: Schema.Array(ExplainedUnknownCall),
  /** Durable approval decisions recorded against this Submission. */
  approvalDecisions: Schema.Array(ApprovalDecisionIntent),
  /** Durable unknown-outcome resolutions recorded against this Submission. */
  unknownResolutions: Schema.Array(UnknownResolutionIntent),
  /** Parent-side child attachments (spec/subagents.md §12). */
  childAttachments: Schema.Array(ChildAttachmentSnapshot),
  /** Host-side joined/joining members of this Submission's Run (DUR-016). */
  joins: Schema.Array(JoinSnapshot),
  /** Joined-side host identity, when this Submission is joined to a host Run. */
  hostSubmissionId: Schema.optionalKey(SubmissionId),
  suspension: Schema.optionalKey(SuspensionSnapshot),
  abortIntent: Schema.optionalKey(AbortIntent),
}) {}

/**
 * The read-only recovery explanation of one Submission (P7 exit gate "operators can explain
 * recovery state without editing storage"): the submission summary, the evidence the pure
 * classifier consumed, the exact `RecoveryDecision` it selected, that decision's operator
 * meaning, and the disposition the recovery pass would report for it.
 */
export class RecoveryExplanation extends Schema.Class<RecoveryExplanation>(
  "@effect-agent/session/RecoveryExplanation",
)({
  submission: ExplainedSubmission,
  evidence: ExplainedEvidence,
  decision: RecoveryDecision,
  /** Static operator meaning of `decision._tag` (see `RECOVERY_DECISION_MEANINGS`). */
  decisionMeaning: BoundedDetail,
  /**
   * The disposition `runRecovery` would report when this decision executes without claim
   * contention (see `predictRecoveryDisposition`): `repaired` = the recovery pass itself fixes
   * it; `deferred` = a claiming worker must finish it; `unknown` = durably blocked on the
   * authorized DUR-017 resolution path; `none` = settled, nothing owed.
   */
  disposition: RecoveryDisposition,
  explainedAt: Schema.DateTimeUtcFromString,
}) {}

/**
 * Operator meaning of every recovery decision tag, matching the classifier docstrings in
 * `recovery.ts` (the classifier remains the semantic authority; this table is its operator
 * rendering). Exhaustive over `RecoveryDecision` — adding a decision without a meaning is a
 * compile error here.
 */
export const RECOVERY_DECISION_MEANINGS: Readonly<Record<RecoveryDecision["_tag"], string>> = {
  CompleteMaterialization:
    "Ledger admission committed but the Conversation is not durable: recovery finishes materialization, appends ConversationCreated, and marks readiness.",
  RepairReadiness:
    "The Conversation is durable but the readiness marker is missing: recovery replays the idempotent markReady.",
  ApplyInput:
    "No canonical input record exists yet: recovery appends the deterministic UserInputRecorded record and marks it applied.",
  RepairInputMarker:
    "The canonical input record exists but the ledger marker was lost: recovery repairs the marker from history, never the reverse (DUR-015).",
  ResumeFromTurnBoundary:
    "Input is applied and no terminal work is reserved: a claiming worker resumes the Run from the last committed Turn boundary; the model may be re-invoked and any duplicate cost is observable (durability §9).",
  AppendReservedSettlement:
    "A settlement is reserved but not canonical: recovery appends the EXACT reserved record, then finalizes (DUR-011).",
  FinalizeLedgerFromHistory:
    "The canonical settlement record exists: recovery rebuilds/finalizes the ledger from history and never rewrites history from the cached ledger status (DUR-011, DUR-015).",
  SettleAborted:
    "A durable abort intent exists with no reserved outcome and no open attached-child obligation: recovery settles aborted, first recording ToolCallUnknown audits for open ordinary calls — abort never asserts external rollback (durability §13).",
  MarkUnknown:
    "Prepared ordinary Tool Calls have no canonical outcome: recovery reconciles each open call and marks the remainder Unknown — never an automatic replay (DUR-009/DUR-017).",
  ResumePendingToolBatch:
    "A committed tool-declaring response has zero prepared and zero settled records: a claiming worker resumes the declared batch without model re-invocation and without Unknown (durability §15).",
  AwaitApprovalDecision:
    "Canonically requested approvals lack decisions: the lane waits durably for the authorized resolveApproval path (recovery repairs a lost suspend transition from history).",
  ResumeSuspended:
    "Every pending approval has a durable decision: a claiming worker resumes the declared batch, appending the canonical ToolApprovalDecided records first.",
  AwaitUnknownResolution:
    "Unknown Outcomes lack covering resolutions: the lane stays blocked awaiting the authorized DUR-017 resolveUnknown path; the obligation stays visible, nothing replays.",
  ApplyUnknownResolutions:
    "Durable resolution intents cover every open call: recovery applies them canonically and reopens the lane.",
  RevertJoining:
    "The Submission is joining without a canonical input record: recovery reverts it to ready — the input was never consumed and will be delivered exactly once later (DUR-016).",
  RepairJoinMarker:
    "The canonical joined input exists but the joined marker was lost: recovery repairs the marker only; the input reattaches, never duplicates (DUR-015/DUR-016).",
  SettleJoinedWithHost:
    "The host Run settled canonically: recovery settles this joined Submission with the host outcome — each joined Submission is owed its own settlement (DUR-002).",
  AwaitHostSettlement:
    "The Submission is joined and its host Run is still live: nothing to repair — the input reattaches through the host's resume and the Submission settles with the host.",
  CompleteChildAdmission:
    "A canonical SubagentRequested exists and the authoritative lookup proved not-admitted: recovery idempotently admits the intended child from the canonical request payload alone (spec/subagents.md §13, SUB-016/SUB-031).",
  AwaitChildAdmissionResolution:
    "The authoritative child-admission lookup answered indeterminate (or was not performed): recovery waits and retries the authoritative owner; a second admission never occurs (SUB-031).",
  RepairSubagentStartLink:
    "The child is admitted but the parent's SubagentStarted link (or reservation attachment) is missing: recovery resolves the SAME child by its deterministic key and appends the exact link (SUB-016/SUB-017).",
  EnsureWaitingForChild:
    "Children are established and at least one is nonterminal while the parent lane is not durably suspended: recovery restores the waitingForChild suspension; it reattaches the one existing child and never spawns a replacement (SUB-018/SUB-030).",
  AwaitChildSettlement:
    "The parent is durably suspended waitingForChild and a listed child is not yet provably settled: the lane stays dormant, consumes no worker permit, and the child's Settlement wakes it durably (SUB-021/SUB-030).",
  ResumeWaitingParent:
    "Every relevant child is provably settled but the parent has not joined: recovery replays the idempotent wake so a claiming worker resumes the declared batch and joins each child's canonical Settlement (spec/subagents.md §13).",
  ApplyJoinAccounting:
    "The canonical SubagentJoined record exists but the reservation release is incomplete: recovery replays the accounting decision FROM the canonical record — budget stays unavailable until repair, never available twice (DUR-015).",
  PropagateChildAbort:
    "Parent abort is canonical while attached children are nonterminal: recovery idempotently issues each child's durable abort command and keeps the parent waiting for the joins — request-abort-and-join is the only close behavior (spec/subagents.md §13.1, SUB-022, DUR-012).",
  ReleaseOrphanChildReservation:
    "A child budget reservation can no longer bind a child: recovery freezes the deterministic zero-consumed accounting decision and releases the unused allocation exactly once (spec/subagents.md §13/§14).",
  AwaitParentEstablishment:
    "The Submission is a parent-linked child whose Conversation lacks the canonical lineage record: the child lane defers its own readiness repair — the parent's idempotent establishment completes it, so a child never runs a Turn before its lineage is canonical (P7 §7(a), SUB-016).",
  NoAction: "The Submission is settled; nothing is owed.",
};

/** The operator meaning of one recovery decision tag. */
export const recoveryDecisionMeaning = (tag: RecoveryDecision["_tag"]): string =>
  RECOVERY_DECISION_MEANINGS[tag];

/**
 * The disposition the recovery executor reports for a decision when its repair executes without
 * claim contention (pure prediction; `executeRecoveryDecision` in the coordinator remains the
 * execution authority — a lane concurrently claimed by a worker can always defer instead).
 * `AwaitApprovalDecision` depends on the snapshot: an already-suspended lane waits (`deferred`),
 * while a claimable lane with a lost suspend transition is repaired.
 */
export const predictRecoveryDisposition = (
  decision: RecoveryDecision,
  snapshot: RecoverySnapshot,
): RecoveryDisposition => {
  switch (decision._tag) {
    case "NoAction":
      return "none";
    case "AwaitUnknownResolution":
    case "MarkUnknown":
      return "unknown";
    case "ResumeFromTurnBoundary":
    case "ResumePendingToolBatch":
    case "ResumeSuspended":
    case "AwaitHostSettlement":
    case "AwaitChildAdmissionResolution":
    case "AwaitChildSettlement":
    case "AwaitParentEstablishment":
      return "deferred";
    case "AwaitApprovalDecision":
      return snapshot.submission.state === "suspended" ? "deferred" : "repaired";
    default:
      return "repaired";
  }
};

const formatUtc = (value: DateTime.Utc): string => DateTime.formatIso(value);

/** Pure operator text for one explanation (the CLI's `explain` output body). */
export const renderRecoveryExplanation = (explanation: RecoveryExplanation): string => {
  const submission = explanation.submission;
  const evidence = explanation.evidence;
  const lines: Array<string> = [
    `Submission ${submission.submissionId} (conversation ${submission.conversationId})`,
    `  state: ${submission.state}  queue: ${submission.queueSequence}  age: ${submission.ageSeconds}s`,
    `  admitted: ${formatUtc(submission.createdAt)}${
      submission.readyAt === undefined ? "" : `  ready: ${formatUtc(submission.readyAt)}`
    }`,
  ];
  if (submission.parentLinkage !== undefined) {
    lines.push(
      `  attached child of ${submission.parentLinkage.parentSubmissionId} (tool call ${submission.parentLinkage.parentToolCallId})`,
    );
  }
  lines.push(
    `  evidence: input=${evidence.inputRecorded ? "recorded" : "missing"}` +
      ` settlement=${evidence.recordedSettlementOutcome ?? "none"}` +
      ` abort=${evidence.abortRecorded ? "recorded" : "none"}` +
      ` materialized=${evidence.conversationMaterialized ? "yes" : "no"}`,
  );
  if (evidence.openToolCalls.length > 0) {
    lines.push(
      `  open ordinary tool calls: ${evidence.openToolCalls
        .map((call) => `${call.toolName}#${call.toolCallId}`)
        .join(", ")}`,
    );
  }
  if (evidence.openDelegationCalls.length > 0) {
    lines.push(
      `  open delegation calls: ${evidence.openDelegationCalls
        .map(
          (call) =>
            `${call.toolName}#${call.toolCallId}(requested=${call.requested} started=${call.started} joined=${call.joined})`,
        )
        .join(", ")}`,
    );
  }
  if (evidence.approvalsPending.length > 0) {
    lines.push(
      `  approvals pending: ${evidence.approvalsPending
        .map((pending) => pending.toolCallId)
        .join(", ")}`,
    );
  }
  for (const unknown of evidence.unknownCalls) {
    lines.push(
      `  unknown outcome: ${unknown.toolName}#${unknown.toolCallId} recorded ${formatUtc(unknown.recordedAt)} ${
        unknown.resolved ? "(resolution intent recorded)" : "(awaiting resolveUnknown)"
      }`,
    );
  }
  if (evidence.childAttachments.length > 0) {
    lines.push(
      `  attached children: ${evidence.childAttachments
        .map((child) => `${child.childSubmissionId}(${child.childState})`)
        .join(", ")}`,
    );
  }
  if (evidence.joins.length > 0) {
    lines.push(
      `  joined members: ${evidence.joins
        .map((join) => `${join.submissionId}(${join.state})`)
        .join(", ")}`,
    );
  }
  if (evidence.hostSubmissionId !== undefined) {
    lines.push(`  joined to host: ${evidence.hostSubmissionId}`);
  }
  if (evidence.suspension !== undefined) {
    lines.push(
      `  suspended (${evidence.suspension.reason._tag}) since ${formatUtc(evidence.suspension.suspendedAt)}`,
    );
  }
  if (evidence.abortIntent !== undefined) {
    lines.push(
      `  abort intent by ${evidence.abortIntent.author} at ${formatUtc(evidence.abortIntent.requestedAt)}`,
    );
  }
  lines.push(
    `  decision: ${explanation.decision._tag} → disposition ${explanation.disposition}`,
    `  meaning: ${explanation.decisionMeaning}`,
  );
  return lines.join("\n");
};

// ---------------------------------------------------------------------------
// verify — IntegrityReport
// ---------------------------------------------------------------------------

/** The named integrity checks `verifyConversationInvariants` performs. */
export const IntegrityCheckName = Schema.Literals([
  /** Every exported envelope round-trips its canonical Schema. */
  "schema-round-trip",
  /** No canonical record identity appears twice (DUR-007). */
  "record-identity",
  /** Canonical sequences are gap-free from 1 through the exported tail. */
  "sequence-contiguity",
  /** The tail digest chain recomputes from EMPTY_TAIL_DIGEST over every batch (DUR-006/DUR-007). */
  "digest-chain",
  /** Canonical `input:{sid}` records follow the admitted FIFO order (DUR-004). */
  "fifo-input-order",
  /** Canonical settlement records follow the admitted FIFO order (DUR-004); aborted
   * settlements of never-run work are exempt by design (P7 §7(c)). */
  "fifo-settlement-order",
  /** At most one canonical terminal record per Submission; exactly one per settled row (DUR-002). */
  "terminal-uniqueness",
  /** Ledger terminal state agrees with the canonical settlement record (DUR-015). */
  "ledger-canonical-agreement",
  /** The stored checkpoint binds to the recomputed digest chain at its sequence. */
  "checkpoint-binding",
  /** Convergence mode only: every known Submission is settled. */
  "all-settled",
]);
export type IntegrityCheckName = typeof IntegrityCheckName.Type;

export const IntegrityCheckStatus = Schema.Literals(["passed", "failed", "skipped"]);
export type IntegrityCheckStatus = typeof IntegrityCheckStatus.Type;

/** One typed check result; `detail` explains a failure or the honest reason for a skip. */
export class IntegrityCheck extends Schema.Class<IntegrityCheck>(
  "@effect-agent/session/IntegrityCheck",
)({
  name: IntegrityCheckName,
  status: IntegrityCheckStatus,
  detail: Schema.optionalKey(BoundedDetail),
}) {}

/**
 * The read-only integrity verdict for one Conversation (plan §3 `verify`): typed per-check
 * results, never a repair. `ok` is true exactly when no check failed — skipped checks are
 * honest scope statements, not silent passes.
 */
export class IntegrityReport extends Schema.Class<IntegrityReport>(
  "@effect-agent/session/IntegrityReport",
)({
  conversationId: ConversationId,
  tailSequence: CanonicalSequence,
  recordCount: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
  submissionCount: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
  checks: Schema.Array(IntegrityCheck),
  ok: Schema.Boolean,
}) {}

// ---------------------------------------------------------------------------
// scanObligations — ObligationReport
// ---------------------------------------------------------------------------

/**
 * What one nonterminal Submission is visibly blocked on (DUR-017 operator surface; OPS-001).
 * `ready-aged`/`running-aged` are not blocks — they are accepted work whose settlement age is
 * measurable and alertable.
 */
export const ObligationBlockedOn = Schema.Literals([
  "unknown",
  "approval",
  "waitingForChild",
  "ready-aged",
  "running-aged",
]);
export type ObligationBlockedOn = typeof ObligationBlockedOn.Type;

export const ObligationSeverity = Schema.Literals(["ok", "aging", "overdue"]);
export type ObligationSeverity = typeof ObligationSeverity.Type;

/** Host-supplied age thresholds; the framework deliberately does not own the alert loop. */
export class ObligationThresholds extends Schema.Class<ObligationThresholds>(
  "@effect-agent/session/ObligationThresholds",
)({
  /** Age (whole seconds) at which an obligation is reported `aging`. */
  agingSeconds: AgeSeconds,
  /** Age (whole seconds) at which an obligation is reported `overdue`. */
  overdueSeconds: AgeSeconds,
}) {}

/** One nonterminal accepted-work obligation with its age and severity. */
export class ObligationEntry extends Schema.Class<ObligationEntry>(
  "@effect-agent/session/ObligationEntry",
)({
  submissionId: SubmissionId,
  conversationId: ConversationId,
  state: SubmissionState,
  blockedOn: ObligationBlockedOn,
  ageSeconds: AgeSeconds,
  severity: ObligationSeverity,
}) {}

/**
 * The scan-based DUR-017/OPS-001 operator surface (plan §3): a fold of the ledger's nonterminal
 * scan into aged, severity-classified rows. Scan-based, never a daemon — hosts run it
 * periodically and export logs/metrics; ages need no storage-version bump because every source
 * timestamp already exists (`createdAt`/`readyAt`, `suspendedAt`, the canonical
 * `ToolCallUnknown` record's `createdAt`).
 */
export class ObligationReport extends Schema.Class<ObligationReport>(
  "@effect-agent/session/ObligationReport",
)({
  thresholds: ObligationThresholds,
  entries: Schema.Array(ObligationEntry),
  generatedAt: Schema.DateTimeUtcFromString,
}) {}

/** Severity of one obligation age under the supplied thresholds. */
export const obligationSeverityOf = (
  ageSeconds: number,
  thresholds: ObligationThresholds,
): ObligationSeverity =>
  ageSeconds >= thresholds.overdueSeconds
    ? "overdue"
    : ageSeconds >= thresholds.agingSeconds
      ? "aging"
      : "ok";

// ---------------------------------------------------------------------------
// retry — typed command and refusals
// ---------------------------------------------------------------------------

/**
 * The mandatory-audit retry command (SEC-011): `author`/`reason` carry the same bounds as the
 * canonical abort command so every mutating administrative operation stays attributable. The
 * executed repair itself appends the deterministic `RepairAnnotated` audit record (DUR-013) —
 * retry adds no new canonical record type.
 */
export class RetryCommand extends Schema.Class<RetryCommand>("@effect-agent/session/RetryCommand")({
  submissionId: SubmissionId,
  author: AbortCommand.fields.author,
  reason: AbortCommand.fields.reason,
}) {}

/** Why a retry was refused without executing anything. */
export const RetryRefusalReason = Schema.Literals([
  /** The Submission is settled; terminal outcomes are never revisited (DUR-002). */
  "settled",
  /** The lane is durably blocked on Unknown Outcomes; use `resolveUnknown` (DUR-017). */
  "await-unknown-resolution",
  /** The lane is durably waiting for approval decisions; use `resolveApproval`. */
  "await-approval-decision",
]);
export type RetryRefusalReason = typeof RetryRefusalReason.Type;

/**
 * Typed refusal of `retry` (plan §3): lanes blocked on `AwaitUnknownResolution` or
 * `AwaitApprovalDecision` have their own authorized operations, and settled work is never
 * re-driven. The refusal names the classifier decision so the operator sees WHY.
 */
export class RetryRefused extends Schema.TaggedError<RetryRefused>()("RetryRefused", {
  submissionId: SubmissionId,
  refusal: RetryRefusalReason,
  decisionTag: Schema.String.check(Schema.isMaxLength(256)),
  message: Schema.String.check(Schema.isMaxLength(4_096)),
}) {}

import { AgentId, ConversationId } from "@effect-agent/core";
import type { RuntimeBinding } from "@effect-agent/engine";
import { Context, Effect, Layer, Option, Schema } from "effect";
import type { Tool } from "effect/unstable/ai";

import type { DurableWorkerFailure, DurableWorkerRequirements } from "./durable-runtime.ts";
import type { Claim, LedgerError, Settlement } from "./ledger.ts";
import { DefinitionDigests } from "./records.ts";

/**
 * No Agent Binding is registered for the requested stable identity. Recovery
 * fails closed: it never substitutes the latest Binding or runs different
 * code (spec/subagents.md §11, SUB-023/SUB-032).
 */
export class BindingUnavailable extends Schema.TaggedError<BindingUnavailable>()(
  "BindingUnavailable",
  {
    agentId: AgentId,
    message: Schema.String,
  },
) {}

/**
 * A Binding is registered for the identity but its exact stored
 * definition/model/tool digests do not match the claimed head's stored
 * digests byte-for-byte. Fail closed (SUB-023): missing or different code is
 * a typed compatibility failure, never a silent substitution.
 */
export class BindingDigestMismatch extends Schema.TaggedError<BindingDigestMismatch>()(
  "BindingDigestMismatch",
  {
    agentId: AgentId,
    message: Schema.String,
  },
) {}

/** The typed refusal family of durable Binding resolution (spec §11, SUB-032). */
export type DurableBindingFailure = BindingUnavailable | BindingDigestMismatch;

/**
 * Instruction failure/requirement derivation mirroring the engine's `RuntimeBinding` defaults:
 * declaring them as generic DEFAULTS (instead of independent inference sites) keeps a plain
 * string-returning instruction function from widening both parameters to `unknown`.
 */
type InstructionResultOf<Instructions, Input> = Instructions extends (input: Input) => infer Result
  ? Result
  : Instructions;

type InstructionErrorOf<Instructions, Input> =
  InstructionResultOf<Instructions, Input> extends Effect.Effect<
    infer _Success,
    infer Error,
    infer _Requirements
  >
    ? Error
    : never;

type InstructionRequirementsOf<Instructions, Input> =
  InstructionResultOf<Instructions, Input> extends Effect.Effect<
    infer _Success,
    infer _Error,
    infer Requirements
  >
    ? Requirements
    : never;

/** Byte-for-byte equality of two stored definition digest triples (SUB-023). */
export const definitionDigestsEqual = (
  left: DefinitionDigests,
  right: DefinitionDigests,
): boolean =>
  left.agent === right.agent && left.model === right.model && left.tools === right.tools;

/**
 * INTERNAL coordinator entry point a `ResolvedBinding` drives: one fenced
 * Attempt over the resolved binding and an already-granted claim. The
 * coordinator's `runAttempt` satisfies this shape; the polymorphic signature
 * keeps the existential capture fully typed (no generics escape as `any`).
 */
export type ResolvedAttemptDriver = <
  InputSchema extends Schema.Top,
  OutputSchema extends Schema.Top,
  Instructions,
  Tools extends Record<string, Tool.Any>,
  Provider,
  ModelProvides,
  ModelRequires,
  InstructionError,
  InstructionRequirements,
>(
  agent: RuntimeBinding<
    InputSchema,
    OutputSchema,
    Instructions,
    Tools,
    Provider,
    ModelProvides,
    ModelRequires,
    InstructionError,
    InstructionRequirements
  >,
  conversationId: ConversationId,
  claim: Claim,
) => Effect.Effect<
  Option.Option<Settlement>,
  DurableWorkerFailure,
  DurableWorkerRequirements<
    RuntimeBinding<
      InputSchema,
      OutputSchema,
      Instructions,
      Tools,
      Provider,
      ModelProvides,
      ModelRequires,
      InstructionError,
      InstructionRequirements
    >,
    InstructionRequirements
  >
>;

/**
 * One resolvable Agent Binding as an existential value: the stable identity,
 * the exact registered definition digests, and an `attempt` closure that runs
 * a coordinator Attempt over the captured binding with its worker
 * requirements Context already provided (the S1 `Effect.context` capture
 * precedent from `SubagentRuntime.layer`). `digests` is `undefined` only for
 * the digest-transparent singleton registration used by the legacy
 * single-binding `runWorker` — identity-exact but accepting whatever digests
 * the claimed head stored; exact-digest enforcement requires
 * `DurableWorkerBinding.make` plus `runResolvedWorker`.
 */
export interface ResolvedBinding {
  readonly agentId: AgentId;
  readonly digests: DefinitionDigests | undefined;
  readonly attempt: (
    driver: ResolvedAttemptDriver,
    conversationId: ConversationId,
    claim: Claim,
  ) => Effect.Effect<Option.Option<Settlement>, DurableWorkerFailure>;
}

const capture = <
  InputSchema extends Schema.Top,
  OutputSchema extends Schema.Top,
  Instructions,
  Tools extends Record<string, Tool.Any>,
  Provider,
  ModelProvides,
  ModelRequires,
  InstructionError = InstructionErrorOf<Instructions, InputSchema["Type"]>,
  InstructionRequirements = InstructionRequirementsOf<Instructions, InputSchema["Type"]>,
>(
  agent: RuntimeBinding<
    InputSchema,
    OutputSchema,
    Instructions,
    Tools,
    Provider,
    ModelProvides,
    ModelRequires,
    InstructionError,
    InstructionRequirements
  >,
  digests: DefinitionDigests | undefined,
): Effect.Effect<
  ResolvedBinding,
  never,
  DurableWorkerRequirements<typeof agent, InstructionRequirements>
> =>
  Effect.map(
    Effect.context<DurableWorkerRequirements<typeof agent, InstructionRequirements>>(),
    (context): ResolvedBinding => ({
      agentId: agent.definition.id,
      digests,
      attempt: (driver, conversationId, claim) =>
        // `Exclude<R, R>` does not reduce to `never` while `R` stays
        // parametric, so this one documented assertion closes the provision
        // TypeScript cannot see: the captured Context is exactly the driver's
        // requirement set for this binding instantiation.
        driver(agent, conversationId, claim).pipe(Effect.provide(context)) as Effect.Effect<
          Option.Option<Settlement>,
          DurableWorkerFailure
        >,
    }),
  );

/**
 * Build resolvable worker bindings (spec/subagents.md §11: the definition
 * resolver is an explicit host-supplied Effect service; it resolves an Agent
 * Binding by stable identity and exact stored digest).
 *
 * - `make(agent, digests)` captures the binding plus its worker-requirement
 *   Context at Layer/effect construction time and registers the EXACT digest
 *   triple the host stores for it. Hosts MUST register the same digest
 *   strings the application submits with (`DurableSubmitOptions.definitions`)
 *   and declares on durable delegation Layers
 *   (`SubagentRuntimeOptions.durable.targetDigests`).
 * - `makeDigestTransparent(agent)` registers identity-only resolution for the
 *   legacy single-binding `runWorker`: a claimed head with a different
 *   `agentId` still fails closed, but the head's own stored digests are
 *   accepted as-is because this registration carries no digest authority.
 */
export const DurableWorkerBinding = {
  make: <
    InputSchema extends Schema.Top,
    OutputSchema extends Schema.Top,
    Instructions,
    Tools extends Record<string, Tool.Any>,
    Provider,
    ModelProvides,
    ModelRequires,
    InstructionError = InstructionErrorOf<Instructions, InputSchema["Type"]>,
    InstructionRequirements = InstructionRequirementsOf<Instructions, InputSchema["Type"]>,
  >(
    agent: RuntimeBinding<
      InputSchema,
      OutputSchema,
      Instructions,
      Tools,
      Provider,
      ModelProvides,
      ModelRequires,
      InstructionError,
      InstructionRequirements
    >,
    digests: DefinitionDigests,
  ): Effect.Effect<
    ResolvedBinding,
    never,
    DurableWorkerRequirements<typeof agent, InstructionRequirements>
  > => capture(agent, digests),
  makeDigestTransparent: <
    InputSchema extends Schema.Top,
    OutputSchema extends Schema.Top,
    Instructions,
    Tools extends Record<string, Tool.Any>,
    Provider,
    ModelProvides,
    ModelRequires,
    InstructionError = InstructionErrorOf<Instructions, InputSchema["Type"]>,
    InstructionRequirements = InstructionRequirementsOf<Instructions, InputSchema["Type"]>,
  >(
    agent: RuntimeBinding<
      InputSchema,
      OutputSchema,
      Instructions,
      Tools,
      Provider,
      ModelProvides,
      ModelRequires,
      InstructionError,
      InstructionRequirements
    >,
  ): Effect.Effect<
    ResolvedBinding,
    never,
    DurableWorkerRequirements<typeof agent, InstructionRequirements>
  > => capture(agent, undefined),
} as const;

/**
 * Host-supplied definition/binding resolver used at durable claim time
 * (spec/subagents.md §11, D7): stable identity plus exact stored digests
 * resolve to one executable `ResolvedBinding`. Missing or different code is a
 * typed, fail-closed refusal — recovery never substitutes the latest Binding
 * (SUB-023); the coordinator turns a refusal into the framework
 * `ChildCompatibilityFailure` Settlement for a parent-linked child and a
 * typed report for a root Submission (SUB-032).
 */
export class AgentBindingResolver extends Context.Service<
  AgentBindingResolver,
  {
    readonly resolve: (
      agentId: AgentId,
      digests: DefinitionDigests,
    ) => Effect.Effect<ResolvedBinding, DurableBindingFailure | LedgerError>;
  }
>()("@effect-agent/session/AgentBindingResolver") {
  /** Resolver over a fixed registration list: identity first, then exact digests. */
  static fromBindings(
    bindings: ReadonlyArray<ResolvedBinding>,
  ): (typeof AgentBindingResolver)["Service"] {
    return {
      resolve: (agentId, digests) => {
        const registered = bindings.filter((binding) => binding.agentId === agentId);
        if (registered.length === 0) {
          return Effect.fail(
            BindingUnavailable.make({
              agentId,
              message: `No Agent Binding is registered for ${agentId}; recovery never substitutes different code (SUB-023)`,
            }),
          );
        }
        const exact = registered.find(
          (binding) =>
            binding.digests === undefined || definitionDigestsEqual(binding.digests, digests),
        );
        if (exact === undefined) {
          return Effect.fail(
            BindingDigestMismatch.make({
              agentId,
              message: `The registered Binding for ${agentId} does not match the stored definition digests exactly; missing or different code fails closed (SUB-023)`,
            }),
          );
        }
        return Effect.succeed(exact);
      },
    };
  }

  static layer(bindings: ReadonlyArray<ResolvedBinding>): Layer.Layer<AgentBindingResolver> {
    return Layer.succeed(AgentBindingResolver)(AgentBindingResolver.fromBindings(bindings));
  }
}

import { Cause, Crypto, Effect, Exit, Option, Schema } from "effect";

import { IntegrityCheck, IntegrityReport, type IntegrityCheckName } from "./admin.ts";
import { conversationStoreConformanceCases } from "./conformance.ts";
import { digestCanonicalBatch, EMPTY_TAIL_DIGEST } from "./digest.ts";
import { DurableRuntimeFailpointLocation } from "./durable-failpoint.ts";
import { submissionLedgerConformanceCases } from "./ledger-conformance.ts";
import {
  LedgerCapabilities,
  SubmissionLedger,
  submissionInputRecordId,
  submissionSettlementRecordId,
  type SubmissionSnapshot,
} from "./ledger.ts";
import {
  CanonicalBatch,
  CanonicalRecordEnvelope,
  type BatchId,
  type ProducerId,
  type RecordEnvelope,
} from "./records.ts";
import {
  ConversationStore,
  type ConversationCheckpoint,
  type ConversationExport,
} from "./store.ts";

/**
 * P7 certification module (plan §1): the shared invariant checker
 * `verifyConversationInvariants` — hoisted from the DC eviction harness's `assertConvergence`
 * so the admin `verify` operation, the adapter certification tiers (WP2), and the chaos/soak
 * properties (WP4) all assert ONE set of claims — plus the certification report vocabulary
 * (`CertificationReport` and friends) and the Tier-1 port-contract runner `certifyPorts`.
 * The Tier-2/Tier-3 coordinator runner (`certifyDurableAdapters`) lives in
 * `@effect-agent/testing` because it drives the full coordinator with a scripted model.
 */

/**
 * Input of one invariant verification, assembled entirely from port reads (or from a captured
 * copy under test):
 *
 * - `export` — the Conversation's canonical export (`ConversationStore.export`).
 * - `submissions` — every known Submission row of the lane (ledger scan + lookups). Order is
 *   irrelevant; the checker sorts by `queueSequence`.
 * - `batchProducers` — OPTIONAL per-batch producer identity directory. The digest chain hashes
 *   each batch's Schema-encoded `CanonicalBatch` — including its `producerId`, which the
 *   `ConversationStore` port deliberately does not export — so full chain recomputation needs
 *   this directory (capture it at append time, or from adapter-private storage). Without it the
 *   `digest-chain` and `checkpoint-binding` checks report `skipped` with the honest reason;
 *   adapter-level `verifyOnOpen` remains the storage-side full audit.
 * - `checkpoint` — the stored checkpoint to bind against the recomputed chain, when one exists.
 * - `requireAllSettled` — convergence mode (certification Tier 2, chaos, soak): additionally
 *   require every known Submission to be settled.
 */
export interface ConversationInvariantInput {
  readonly export: ConversationExport;
  readonly submissions: ReadonlyArray<SubmissionSnapshot>;
  readonly batchProducers?: ReadonlyMap<BatchId, ProducerId> | undefined;
  readonly checkpoint?: ConversationCheckpoint | undefined;
  readonly requireAllSettled?: boolean | undefined;
}

const encodeEnvelope = Schema.encodeEffect(CanonicalRecordEnvelope);
const decodeEnvelope = Schema.decodeUnknownEffect(CanonicalRecordEnvelope);

const check = (
  name: IntegrityCheckName,
  status: "passed" | "failed" | "skipped",
  detail?: string,
): IntegrityCheck =>
  IntegrityCheck.make({
    name,
    status,
    ...(detail === undefined ? {} : { detail: detail.slice(0, 4_096) }),
  });

interface BatchRun {
  readonly batchId: BatchId;
  readonly records: Array<RecordEnvelope>;
  readonly lastSequence: number;
}

/** Group the export's records into their atomic append runs (batches append contiguously). */
const batchRunsOf = (records: ReadonlyArray<CanonicalRecordEnvelope>): Array<BatchRun> => {
  const runs: Array<BatchRun> = [];
  for (const envelope of records) {
    const current = runs.at(-1);
    if (current !== undefined && current.batchId === envelope.batchId) {
      current.records.push(envelope.record);
      runs[runs.length - 1] = { ...current, lastSequence: envelope.sequence };
      continue;
    }
    runs.push({
      batchId: envelope.batchId,
      records: [envelope.record],
      lastSequence: envelope.sequence,
    });
  }
  return runs;
};

/**
 * The shared conversation invariant checker (plan §1/§3): the DC harness `assertConvergence`
 * claims, verbatim, as typed per-check results over a canonical export plus the lane's ledger
 * rows — read-only, never a repair:
 *
 * 1. `schema-round-trip` — every envelope re-encodes and re-decodes through its canonical
 *    Schema (a corrupted copy fails typed instead of decoding incorrectly).
 * 2. `record-identity` — no canonical record identity appears twice (DUR-007 dedupe held).
 * 3. `sequence-contiguity` — gap-free sequences from 1 through the exported tail.
 * 4. `digest-chain` — the tail digest recomputes from `EMPTY_TAIL_DIGEST` through every batch
 *    (requires the per-batch producer directory; skipped honestly otherwise).
 * 5. `fifo-input-order` / `fifo-settlement-order` — canonical input and settlement records
 *    follow the admitted queue order (DUR-004). Aborted settlements of never-run work (no
 *    canonical `input:{sid}` record) are exempt from the settlement comparison: P7 §7(c)
 *    settles them immediately without waiting for the head, and DUR-004 bounds execution
 *    order, which never-run work has none of.
 * 6. `terminal-uniqueness` — at most one canonical terminal record per Submission, exactly one
 *    for every settled ledger row (DUR-002).
 * 7. `ledger-canonical-agreement` — a settled ledger row has a canonical settlement record and
 *    the outcomes agree; canonical history remains the authority (DUR-015).
 * 8. `checkpoint-binding` — a stored checkpoint's digest matches the recomputed chain at its
 *    sequence (needs the chain; bounds are checked regardless).
 * 9. `all-settled` — convergence mode only: every known Submission settled.
 *
 * Requires only `Crypto.Crypto` (digest recomputation); it performs no port access, so the
 * admin operation, certification runners, and chaos properties feed it whatever copies they
 * hold.
 */
export const verifyConversationInvariants = Effect.fn("Session.verifyConversationInvariants")(
  function* (
    input: ConversationInvariantInput,
  ): Effect.fn.Return<IntegrityReport, never, Crypto.Crypto> {
    const exported = input.export;
    const records = exported.records;
    const checks: Array<IntegrityCheck> = [];

    // 1. schema-round-trip
    {
      let failure: string | undefined;
      for (const envelope of records) {
        const roundTrip = yield* encodeEnvelope(envelope).pipe(
          Effect.flatMap(decodeEnvelope),
          Effect.exit,
        );
        if (roundTrip._tag === "Failure") {
          failure = `record ${envelope.record.recordId} does not round-trip its Schema`;
          break;
        }
      }
      checks.push(
        failure === undefined
          ? check("schema-round-trip", "passed")
          : check("schema-round-trip", "failed", failure),
      );
    }

    // 2. record-identity
    {
      const seen = new Set<string>();
      const duplicates = new Set<string>();
      for (const envelope of records) {
        if (seen.has(envelope.record.recordId)) duplicates.add(envelope.record.recordId);
        seen.add(envelope.record.recordId);
      }
      checks.push(
        duplicates.size === 0
          ? check("record-identity", "passed")
          : check(
              "record-identity",
              "failed",
              `duplicated canonical record identities: ${[...duplicates].join(", ")}`,
            ),
      );
    }

    // 3. sequence-contiguity
    {
      let contiguityFailure: string | undefined;
      for (const [index, envelope] of records.entries()) {
        if (envelope.sequence !== index + 1) {
          contiguityFailure = `sequence ${envelope.sequence} at position ${index} (expected ${index + 1})`;
          break;
        }
      }
      if (contiguityFailure === undefined && records.length !== exported.tailSequence) {
        contiguityFailure = `exported tail sequence ${exported.tailSequence} disagrees with ${records.length} records`;
      }
      checks.push(
        contiguityFailure === undefined
          ? check("sequence-contiguity", "passed")
          : check("sequence-contiguity", "failed", contiguityFailure),
      );
    }

    // 4. digest-chain (+ collect per-sequence chain digests for checkpoint binding)
    const chainDigestAtSequence = new Map<number, string>();
    if (input.batchProducers === undefined) {
      checks.push(
        check(
          "digest-chain",
          "skipped",
          "the ConversationStore port does not export per-batch producer identity; supply batchProducers (captured at append time) to recompute the chain — adapter-level verifyOnOpen performs the storage-side audit",
        ),
      );
    } else {
      let chain = EMPTY_TAIL_DIGEST;
      let chainFailure: string | undefined;
      for (const run of batchRunsOf(records)) {
        const producerId = input.batchProducers.get(run.batchId);
        if (producerId === undefined) {
          chainFailure = `no producer identity supplied for batch ${run.batchId}`;
          break;
        }
        const [first, ...rest] = run.records;
        if (first === undefined) {
          chainFailure = `batch ${run.batchId} grouped zero records`;
          break;
        }
        const digest = yield* digestCanonicalBatch(
          chain,
          CanonicalBatch.make({ batchId: run.batchId, producerId, records: [first, ...rest] }),
        ).pipe(Effect.exit);
        if (digest._tag === "Failure") {
          chainFailure = `batch ${run.batchId} could not be re-digested`;
          break;
        }
        chain = digest.value;
        chainDigestAtSequence.set(run.lastSequence, chain);
      }
      if (chainFailure === undefined && chain !== exported.tailDigest) {
        chainFailure = `recomputed tail digest ${chain} disagrees with exported tail digest ${exported.tailDigest}`;
      }
      checks.push(
        chainFailure === undefined
          ? check("digest-chain", "passed")
          : check("digest-chain", "failed", chainFailure),
      );
    }

    // Shared FIFO/terminal machinery
    const ordered = [...input.submissions].sort(
      (left, right) => left.queueSequence - right.queueSequence,
    );
    const recordIds = records.map((envelope) => envelope.record.recordId);

    // 5a. fifo-input-order
    {
      const expectedInputs = ordered.map((row) => submissionInputRecordId(row.submissionId));
      const expectedSet = new Set<string>(expectedInputs);
      const inputOrder = recordIds.filter((recordId) => expectedSet.has(recordId));
      const expectedPresent = expectedInputs.filter((expected) => inputOrder.includes(expected));
      const matches =
        inputOrder.length === expectedPresent.length &&
        inputOrder.every((recordId, index) => recordId === expectedPresent[index]);
      checks.push(
        matches
          ? check("fifo-input-order", "passed")
          : check(
              "fifo-input-order",
              "failed",
              `canonical input order [${inputOrder.join(", ")}] violates queue order`,
            ),
      );
    }

    // 5b. fifo-settlement-order — P7 §7(c) exemption: an ABORTED settlement for never-run work
    // (no canonical `input:{sid}` record) settles immediately by design, without waiting to
    // head the lane, so it is excluded from the FIFO comparison. DUR-004 bounds EXECUTION
    // order; the exempted rows provably never executed.
    {
      const recordIdSet = new Set<string>(recordIds);
      const abortedNeverRun = new Set<string>();
      for (const envelope of records) {
        const payload = envelope.record.payload;
        if (
          payload._tag === "SubmissionSettled" &&
          payload.outcome === "aborted" &&
          !recordIdSet.has(submissionInputRecordId(payload.submissionId))
        ) {
          abortedNeverRun.add(payload.submissionId);
        }
      }
      const expectedSettlements = ordered
        .filter((row) => !abortedNeverRun.has(row.submissionId))
        .map((row) => submissionSettlementRecordId(row.submissionId));
      const expectedSet = new Set<string>(expectedSettlements);
      const settlementOrder = recordIds.filter((recordId) => expectedSet.has(recordId));
      const expectedPresent = expectedSettlements.filter((expected) =>
        settlementOrder.includes(expected),
      );
      const matches =
        settlementOrder.length === expectedPresent.length &&
        settlementOrder.every((recordId, index) => recordId === expectedPresent[index]);
      checks.push(
        matches
          ? check("fifo-settlement-order", "passed")
          : check(
              "fifo-settlement-order",
              "failed",
              `canonical settlement order [${settlementOrder.join(", ")}] violates queue order`,
            ),
      );
    }

    // 6 + 7. terminal-uniqueness and ledger-canonical-agreement
    {
      const settlementsBySubmission = new Map<string, Array<CanonicalRecordEnvelope>>();
      for (const envelope of records) {
        if (envelope.record.payload._tag !== "SubmissionSettled") continue;
        const submissionId = envelope.record.payload.submissionId;
        const existing = settlementsBySubmission.get(submissionId) ?? [];
        existing.push(envelope);
        settlementsBySubmission.set(submissionId, existing);
      }
      let uniquenessFailure: string | undefined;
      let agreementFailure: string | undefined;
      for (const [submissionId, settlements] of settlementsBySubmission) {
        if (settlements.length > 1) {
          uniquenessFailure = `submission ${submissionId} has ${settlements.length} canonical terminal records`;
        }
      }
      for (const row of ordered) {
        const settlements = settlementsBySubmission.get(row.submissionId) ?? [];
        const canonical = settlements[0]?.record.payload;
        if (row.state === "settled") {
          if (settlements.length !== 1) {
            uniquenessFailure ??= `settled submission ${row.submissionId} has ${settlements.length} canonical terminal records (expected exactly 1)`;
          }
          if (
            canonical !== undefined &&
            canonical._tag === "SubmissionSettled" &&
            row.settledOutcome !== undefined &&
            canonical.outcome !== row.settledOutcome
          ) {
            agreementFailure = `submission ${row.submissionId}: ledger outcome ${row.settledOutcome} disagrees with canonical outcome ${canonical.outcome}`;
          }
          if (settlements.length === 0) {
            agreementFailure ??= `settled submission ${row.submissionId} has no canonical settlement record (DUR-015: history is the authority)`;
          }
        }
      }
      checks.push(
        uniquenessFailure === undefined
          ? check("terminal-uniqueness", "passed")
          : check("terminal-uniqueness", "failed", uniquenessFailure),
      );
      checks.push(
        agreementFailure === undefined
          ? check("ledger-canonical-agreement", "passed")
          : check("ledger-canonical-agreement", "failed", agreementFailure),
      );
    }

    // 8. checkpoint-binding
    if (input.checkpoint === undefined) {
      checks.push(check("checkpoint-binding", "passed", "no stored checkpoint"));
    } else if (input.checkpoint.throughSequence > exported.tailSequence) {
      checks.push(
        check(
          "checkpoint-binding",
          "failed",
          `checkpoint through-sequence ${input.checkpoint.throughSequence} is ahead of the tail ${exported.tailSequence}`,
        ),
      );
    } else if (input.batchProducers === undefined) {
      checks.push(
        check(
          "checkpoint-binding",
          "skipped",
          "digest binding needs the recomputed chain; supply batchProducers (the adapter rejects mismatched checkpoints on save/load regardless)",
        ),
      );
    } else {
      const bound = chainDigestAtSequence.get(input.checkpoint.throughSequence);
      checks.push(
        bound === input.checkpoint.tailDigest
          ? check("checkpoint-binding", "passed")
          : check(
              "checkpoint-binding",
              "failed",
              `checkpoint digest ${input.checkpoint.tailDigest} does not match the recomputed chain at sequence ${input.checkpoint.throughSequence}`,
            ),
      );
    }

    // 9. all-settled (convergence mode)
    if (input.requireAllSettled === true) {
      const nonterminal = ordered.filter((row) => row.state !== "settled");
      checks.push(
        nonterminal.length === 0 && ordered.length > 0
          ? check("all-settled", "passed")
          : check(
              "all-settled",
              "failed",
              ordered.length === 0
                ? "no Submissions are known to the lane"
                : `nonterminal submissions: ${nonterminal
                    .map((row) => `${row.submissionId}(${row.state})`)
                    .join(", ")}`,
            ),
      );
    }

    return IntegrityReport.make({
      conversationId: exported.conversationId,
      tailSequence: exported.tailSequence,
      recordCount: records.length,
      submissionCount: ordered.length,
      checks,
      ok: checks.every((result) => result.status !== "failed"),
    });
  },
);

// ---------------------------------------------------------------------------
// Certification report vocabulary (WP2, plan §1)
// ---------------------------------------------------------------------------

const BoundedCertificationDetail = Schema.String.check(Schema.isMaxLength(4_096));

/**
 * Adapter self-description carried by a certificate. `durability` is read from the candidate
 * ledger's `capabilities` — the adapter's honest claim (persistence.md), never inferred by the
 * certification runner.
 */
export class CertifiedAdapterIdentity extends Schema.Class<CertifiedAdapterIdentity>(
  "@effect-agent/session/CertifiedAdapterIdentity",
)({
  /** Workspace/package name of the adapter pair under certification. */
  name: Schema.NonEmptyString.check(Schema.isMaxLength(256)),
  version: Schema.optionalKey(Schema.String.check(Schema.isMaxLength(256))),
  durability: LedgerCapabilities.fields.durability,
}) {}

/** Which shared suite one Tier-1 (or lever-driven Tier-3) case belongs to. */
export const CertificationSuite = Schema.Literals([
  "submission-ledger",
  "conversation-store",
  "real-loss",
]);
export type CertificationSuite = typeof CertificationSuite.Type;

/** One executed certification case: a conformance contract case or a Tier-3 lever row. */
export class CertificationCaseResult extends Schema.Class<CertificationCaseResult>(
  "@effect-agent/session/CertificationCaseResult",
)({
  suite: CertificationSuite,
  name: Schema.NonEmptyString.check(Schema.isMaxLength(512)),
  status: Schema.Literals(["passed", "failed"]),
  detail: Schema.optionalKey(BoundedCertificationDetail),
}) {}

/**
 * The six Tier-2 scenario shapes (plan §1): every `DurableRuntimeFailpointLocation` is armed
 * once per shape, so each coordinator fault boundary is exercised in every protocol family it
 * can appear in.
 */
export const CertificationScenario = Schema.Literals([
  "plain",
  "uncertain-tool",
  "durable-steps",
  "approval",
  "join",
  "delegation",
]);
export type CertificationScenario = typeof CertificationScenario.Type;

/**
 * Outcome of one Tier-2 sweep cell:
 *
 * - `converged` — the armed fault fired once, recovery classified the state, and the re-drive
 *   converged to verified invariants;
 * - `not-triggered` — the armed location is not on this scenario's coordinator path (recorded
 *   honestly, never claimed as fault coverage); the clean run still converged and verified;
 * - `failed` — anything else.
 */
export const CertificationSweepStatus = Schema.Literals(["converged", "not-triggered", "failed"]);
export type CertificationSweepStatus = typeof CertificationSweepStatus.Type;

/** One Tier-2 cell: one scenario shape with one armed coordinator failpoint location. */
export class CertificationSweepResult extends Schema.Class<CertificationSweepResult>(
  "@effect-agent/session/CertificationSweepResult",
)({
  scenario: CertificationScenario,
  location: DurableRuntimeFailpointLocation,
  /** The armed fault actually fired (one-shot) somewhere in the cell's drive or re-drive. */
  failpointFired: Schema.Boolean,
  status: CertificationSweepStatus,
  /**
   * Every lane's digest chain recomputed from `EMPTY_TAIL_DIGEST` and matched the exported
   * tail — fully discharged here because the runner captures per-batch producer identity at
   * append time (the port-only admin `verify` reports this check `skipped` instead).
   */
  digestChainVerified: Schema.Boolean,
  detail: Schema.optionalKey(BoundedCertificationDetail),
}) {}

/**
 * How the real-loss tier was discharged. Tier 3 is never silently claimed: an adapter either
 * exercised a real loss lever in this run (`exercised`), cites committed real-loss evidence
 * (`recorded-evidence`), honestly records that nothing exercised it (`not-exercised`), or is a
 * non-durable reference adapter with no real loss to exercise (`not-applicable`).
 */
export const CertificationTierThreeStatus = Schema.Literals([
  "exercised",
  "recorded-evidence",
  "not-exercised",
  "not-applicable",
]);
export type CertificationTierThreeStatus = typeof CertificationTierThreeStatus.Type;

/** The Tier-3 (real loss lever) section of a certificate. */
export class CertificationTierThreeReport extends Schema.Class<CertificationTierThreeReport>(
  "@effect-agent/session/CertificationTierThreeReport",
)({
  status: CertificationTierThreeStatus,
  /** Repository-relative citations of the real-loss suites that discharge this tier. */
  evidence: Schema.Array(BoundedCertificationDetail),
  /** Rows executed by a supplied crash lever in THIS run (`suite: "real-loss"`). */
  cases: Schema.Array(CertificationCaseResult),
  detail: Schema.optionalKey(BoundedCertificationDetail),
}) {}

/**
 * The Schema-encoded certification report (plan §1): Tier 1 = the two shared port contract
 * suites verbatim; Tier 2 = the coordinator failpoint convergence sweep; Tier 3 = the real
 * loss lever record. `ok` is true exactly when every EXECUTED check passed — honest scope
 * statements (`not-triggered`, `recorded-evidence`, `not-exercised`, `not-applicable`) never
 * count as failures and never count as silent coverage. The committed JSON is evidence; the
 * semantic assertions live in the runner tests (testing.md §12).
 */
export class CertificationReport extends Schema.Class<CertificationReport>(
  "@effect-agent/session/CertificationReport",
)({
  format: Schema.Literal("effect-agent/certification@1"),
  adapter: CertifiedAdapterIdentity,
  generatedAt: Schema.DateTimeUtcFromString,
  tier1: Schema.Array(CertificationCaseResult),
  tier2: Schema.Array(CertificationSweepResult),
  tier3: CertificationTierThreeReport,
  ok: Schema.Boolean,
}) {}

/** Bounded operator-readable rendering of one failure Cause for a certification detail. */
const causeDetail = (cause: Cause.Cause<unknown>): string => {
  const failure = Cause.findErrorOption(cause);
  if (Option.isSome(failure)) {
    const error: unknown = failure.value;
    if (typeof error === "object" && error !== null) {
      const tag = "_tag" in error ? String((error as { _tag: unknown })._tag) : "Error";
      const message =
        "message" in error && (error as { message?: unknown }).message !== undefined
          ? String((error as { message?: unknown }).message)
          : "";
      return `${tag}${message === "" ? "" : `: ${message}`}`.slice(0, 4_096);
    }
    return String(error).slice(0, 4_096);
  }
  return `defect: ${String(cause)}`.slice(0, 4_096);
};

const caseResult = <A, E>(
  suite: CertificationSuite,
  name: string,
  exit: Exit.Exit<A, E>,
): CertificationCaseResult =>
  Exit.isSuccess(exit)
    ? CertificationCaseResult.make({ suite, name, status: "passed" })
    : CertificationCaseResult.make({
        suite,
        name,
        status: "failed",
        detail: causeDetail(exit.cause),
      });

/**
 * Tier 1 — port contract (plan §1): run BOTH shared conformance case arrays verbatim against
 * the provided candidate adapters and fold every case into a typed result. Case failures are
 * captured per-case (never short-circuiting the sweep), so a certificate always reports the
 * complete contract surface. Requires the candidate `SubmissionLedger` and `ConversationStore`
 * plus `Crypto.Crypto`, and must run under a TestClock (the ledger cases drive lease expiry
 * through virtual time).
 */
export const certifyPorts = Effect.fn("Session.certifyPorts")(function* (): Effect.fn.Return<
  ReadonlyArray<CertificationCaseResult>,
  never,
  SubmissionLedger | ConversationStore | Crypto.Crypto
> {
  const results: Array<CertificationCaseResult> = [];
  for (const contractCase of submissionLedgerConformanceCases) {
    const exit = yield* Effect.exit(contractCase.run);
    results.push(caseResult("submission-ledger", contractCase.name, exit));
  }
  for (const contractCase of conversationStoreConformanceCases) {
    const exit = yield* Effect.exit(contractCase.run);
    results.push(caseResult("conversation-store", contractCase.name, exit));
  }
  return results;
});

import { ConversationId, RunId, SubmissionId } from "@effect-agent/core";
import { Effect, DateTime, Option, Schema, Stream } from "effect";

import { EMPTY_TAIL_DIGEST } from "./digest.ts";
import {
  BatchId,
  CanonicalBatch,
  CanonicalSequence,
  DeploymentId,
  Digest,
  ProducerEpoch,
  ProducerId,
  RecordEnvelope,
  RecordId,
  UserInputRecorded,
} from "./records.ts";
import {
  AppendConflict,
  AppendResult,
  CheckpointRejected,
  ConversationCheckpoint,
  ConversationExportRequest,
  ConversationMaterialization,
  ConversationNotMaterialized,
  ConversationObservation,
  ConversationRead,
  ConversationStore,
  ConversationTailRequest,
  FencedAppendRequest,
  FenceRejected,
  LoadCheckpointRequest,
  SaveCheckpointRequest,
  type ConversationStoreFailure,
} from "./store.ts";

/** A ConversationStore contract invariant that an adapter under test violated. */
export class ConversationStoreConformanceViolation extends Schema.TaggedError<ConversationStoreConformanceViolation>()(
  "ConversationStoreConformanceViolation",
  {
    caseName: Schema.String,
    message: Schema.String,
  },
) {}

export type ConversationStoreConformanceFailure =
  | ConversationStoreFailure
  | ConversationStoreConformanceViolation;

/**
 * One adapter-neutral ConversationStore contract case. Each case owns disjoint
 * Conversation identities, so a suite may run every case against one shared store
 * instance or against a fresh store per case.
 */
export interface ConversationStoreConformanceCase {
  readonly name: string;
  readonly run: Effect.Effect<void, ConversationStoreConformanceFailure, ConversationStore>;
}

const decodeConversationId = Schema.decodeSync(ConversationId);
const decodeRecordId = Schema.decodeSync(RecordId);
const decodeBatchId = Schema.decodeSync(BatchId);
const decodeSequence = Schema.decodeSync(CanonicalSequence);
const decodeEpoch = Schema.decodeSync(ProducerEpoch);

const CONFORMANCE_DEPLOYMENT = Schema.decodeSync(DeploymentId)("deployment-conformance");
const CONFORMANCE_PRODUCER = Schema.decodeSync(ProducerId)("producer-conformance");
const CONFORMANCE_SUBMISSION = Schema.decodeSync(SubmissionId)("submission-conformance");
const CONFORMANCE_RUN = Schema.decodeSync(RunId)("run-conformance");
const CONFORMANCE_CREATED_AT = DateTime.toUtc(DateTime.makeUnsafe(1));

const ZERO_SEQUENCE = decodeSequence(0);
const EPOCH_ONE = decodeEpoch(1);
const EPOCH_TWO = decodeEpoch(2);
const EMPTY_TAIL = { lastSequence: ZERO_SEQUENCE, tailDigest: EMPTY_TAIL_DIGEST } as const;

const record = (recordId: string, input: string): RecordEnvelope =>
  RecordEnvelope.make({
    recordId: decodeRecordId(recordId),
    family: "conversation",
    schemaVersion: 1,
    createdAt: CONFORMANCE_CREATED_AT,
    deploymentId: CONFORMANCE_DEPLOYMENT,
    payload: UserInputRecorded.make({
      submissionId: CONFORMANCE_SUBMISSION,
      kind: "user",
      runId: CONFORMANCE_RUN,
      input,
    }),
  });

const batch = (
  batchId: string,
  records: readonly [RecordEnvelope, ...Array<RecordEnvelope>],
): CanonicalBatch =>
  CanonicalBatch.make({
    batchId: decodeBatchId(batchId),
    producerId: CONFORMANCE_PRODUCER,
    records,
  });

const materialize = Effect.fn("ConversationStoreConformance.materialize")(function* (
  conversationId: ConversationId,
  producerEpoch: ProducerEpoch,
) {
  const store = yield* ConversationStore;
  yield* store.materialize(ConversationMaterialization.make({ conversationId, producerEpoch }));
});

const append = Effect.fn("ConversationStoreConformance.append")(function* (
  conversationId: ConversationId,
  canonicalBatch: CanonicalBatch,
  tail: Pick<AppendResult, "lastSequence" | "tailDigest"> = EMPTY_TAIL,
  producerEpoch: ProducerEpoch = EPOCH_ONE,
) {
  const store = yield* ConversationStore;
  return yield* store.append(
    FencedAppendRequest.make({
      conversationId,
      batch: canonicalBatch,
      expectedTailSequence: tail.lastSequence,
      expectedTailDigest: tail.tailDigest,
      producerEpoch,
    }),
  );
});

const readAll = Effect.fn("ConversationStoreConformance.readAll")(function* (
  conversationId: ConversationId,
) {
  const store = yield* ConversationStore;
  return yield* store
    .read(ConversationRead.make({ conversationId, limit: 1_024 }))
    .pipe(Stream.runCollect);
});

const checkpointAt = (
  conversationId: ConversationId,
  throughSequence: CanonicalSequence,
  tailDigest: Digest,
): ConversationCheckpoint =>
  ConversationCheckpoint.make({
    schemaVersion: 1,
    conversationId,
    throughSequence,
    tailDigest,
    engineVersion: "conformance",
    agentDefinitionDigest: tailDigest,
    modelDigest: tailDigest,
    toolDigest: tailDigest,
    state: { conformance: true },
    createdAt: CONFORMANCE_CREATED_AT,
  });

const conformanceCase = (
  name: string,
  build: (assert: {
    readonly ensure: (
      condition: boolean,
      message: string,
    ) => Effect.Effect<void, ConversationStoreConformanceViolation>;
    readonly expectFailure: <A, E, R>(
      description: string,
      effect: Effect.Effect<A, E, R>,
    ) => Effect.Effect<E, ConversationStoreConformanceViolation, R>;
  }) => Effect.Effect<void, ConversationStoreConformanceFailure, ConversationStore>,
): ConversationStoreConformanceCase => ({
  name,
  run: build({
    ensure: (condition, message) =>
      condition
        ? Effect.void
        : Effect.fail(ConversationStoreConformanceViolation.make({ caseName: name, message })),
    expectFailure: (description, effect) =>
      Effect.flip(effect).pipe(
        Effect.mapError(() =>
          ConversationStoreConformanceViolation.make({
            caseName: name,
            message: `Expected failure but the operation succeeded: ${description}`,
          }),
        ),
      ),
  }).pipe(Effect.withSpan(`ConversationStoreConformance.${name}`)),
});

const atomicBatchVisibility = conformanceCase(
  "commits batches atomically with no partial reader visibility",
  ({ ensure, expectFailure }) =>
    Effect.gen(function* () {
      const conversationId = decodeConversationId("conformance-atomic");
      const store = yield* ConversationStore;
      yield* materialize(conversationId, EPOCH_ONE);

      const committed = yield* append(
        conversationId,
        batch("atomic-batch-1", [
          record("atomic-record-1", "first"),
          record("atomic-record-2", "second"),
          record("atomic-record-3", "third"),
        ]),
      );
      yield* ensure(
        committed.firstSequence === 1 && committed.lastSequence === 3,
        "A three-record batch must commit sequences 1 through 3",
      );

      const read = yield* readAll(conversationId);
      yield* ensure(read.length === 3, "Readers must observe the full committed batch");
      yield* ensure(
        read.every((envelope, index) => envelope.sequence === index + 1),
        "Committed records must be gap-free in declaration order",
      );

      const observed = yield* store
        .observe(ConversationObservation.make({ conversationId }))
        .pipe(Stream.take(3), Stream.runCollect);
      yield* ensure(
        observed.map((envelope) => envelope.record.recordId).join(",") ===
          read.map((envelope) => envelope.record.recordId).join(","),
        "Observers must see exactly the committed batch records in order",
      );

      const duplicate = record("atomic-record-4", "duplicate");
      const intraBatch = yield* expectFailure(
        "a batch containing one record ID twice",
        append(conversationId, batch("atomic-batch-2", [duplicate, duplicate]), committed),
      );
      yield* ensure(
        intraBatch instanceof AppendConflict && intraBatch.reason === "record-identity",
        "A duplicated record ID inside one batch must conflict with reason record-identity",
      );

      const crossBatch = yield* expectFailure(
        "a batch reusing an already-committed record ID",
        append(
          conversationId,
          batch("atomic-batch-3", [record("atomic-record-1", "reused")]),
          committed,
        ),
      );
      yield* ensure(
        crossBatch instanceof AppendConflict && crossBatch.reason === "record-identity",
        "A record ID reused across batches must conflict with reason record-identity",
      );

      const exported = yield* store.export(ConversationExportRequest.make({ conversationId }));
      yield* ensure(
        exported.records.length === 3 &&
          exported.tailSequence === committed.lastSequence &&
          exported.tailDigest === committed.tailDigest,
        "A conflicting batch must leave no partial prefix behind",
      );
    }),
);

const idempotentReplay = conformanceCase(
  "replays an identical batch idempotently and rejects altered content",
  ({ ensure, expectFailure }) =>
    Effect.gen(function* () {
      const conversationId = decodeConversationId("conformance-replay");
      yield* materialize(conversationId, EPOCH_ONE);

      const original = batch("replay-batch-1", [
        record("replay-record-1", "Lisbon"),
        record("replay-record-2", "Porto"),
      ]);
      const first = yield* append(conversationId, original);
      yield* ensure(!first.replayed, "The first append of a batch must not report replayed");

      const replayed = yield* append(conversationId, original);
      yield* ensure(
        replayed.replayed &&
          replayed.firstSequence === first.firstSequence &&
          replayed.lastSequence === first.lastSequence &&
          replayed.tailDigest === first.tailDigest,
        "Replaying an identical batch must return the original result with replayed set",
      );

      const altered = yield* expectFailure(
        "replaying a batch ID with different canonical content",
        append(conversationId, batch("replay-batch-1", [record("replay-record-3", "Faro")])),
      );
      yield* ensure(
        altered instanceof AppendConflict && altered.reason === "batch-digest",
        "A batch ID replayed with different content must conflict with reason batch-digest",
      );

      const read = yield* readAll(conversationId);
      yield* ensure(read.length === 2, "Replay and conflict must not duplicate committed records");
    }),
);

const tailConflict = conformanceCase(
  "rejects stale expected tails and reports the actual tail",
  ({ ensure, expectFailure }) =>
    Effect.gen(function* () {
      const conversationId = decodeConversationId("conformance-tail");
      yield* materialize(conversationId, EPOCH_ONE);
      const first = yield* append(
        conversationId,
        batch("tail-batch-1", [record("tail-record-1", "first")]),
      );

      const staleSequence = yield* expectFailure(
        "an append declaring the pre-append tail sequence",
        append(conversationId, batch("tail-batch-2", [record("tail-record-2", "second")])),
      );
      yield* ensure(
        staleSequence instanceof AppendConflict && staleSequence.reason === "tail",
        "A stale expected tail sequence must conflict with reason tail",
      );
      yield* ensure(
        staleSequence instanceof AppendConflict &&
          staleSequence.actualTailSequence === first.lastSequence &&
          staleSequence.actualTailDigest === first.tailDigest,
        "A tail conflict must carry the actual committed tail as a resume hint",
      );

      const staleDigest = yield* expectFailure(
        "an append declaring the right sequence with the wrong digest",
        append(conversationId, batch("tail-batch-2", [record("tail-record-2", "second")]), {
          lastSequence: first.lastSequence,
          tailDigest: EMPTY_TAIL_DIGEST,
        }),
      );
      yield* ensure(
        staleDigest instanceof AppendConflict && staleDigest.reason === "tail",
        "A stale expected tail digest must conflict with reason tail",
      );

      const recovered = yield* append(
        conversationId,
        batch("tail-batch-2", [record("tail-record-2", "second")]),
        first,
      );
      yield* ensure(
        recovered.firstSequence === first.lastSequence + 1,
        "An append declaring the true tail must commit after a tail conflict",
      );
    }),
);

const producerFencing = conformanceCase(
  "fences stale producer epochs while allowing epoch takeover",
  ({ ensure, expectFailure }) =>
    Effect.gen(function* () {
      const conversationId = decodeConversationId("conformance-fencing");
      yield* materialize(conversationId, EPOCH_ONE);
      const first = yield* append(
        conversationId,
        batch("fence-batch-1", [record("fence-record-1", "first")]),
      );

      yield* materialize(conversationId, EPOCH_TWO);

      const staleAppend = yield* expectFailure(
        "an append using the pre-takeover producer epoch",
        append(
          conversationId,
          batch("fence-batch-2", [record("fence-record-2", "second")]),
          first,
          EPOCH_ONE,
        ),
      );
      yield* ensure(
        staleAppend instanceof FenceRejected &&
          staleAppend.actualEpoch === EPOCH_TWO &&
          staleAppend.attemptedEpoch === EPOCH_ONE,
        "A stale producer epoch must be fenced with both epochs reported",
      );

      const staleMaterialize = yield* expectFailure(
        "re-materializing with the pre-takeover producer epoch",
        materialize(conversationId, EPOCH_ONE),
      );
      yield* ensure(
        staleMaterialize instanceof FenceRejected,
        "A stale producer epoch must not re-register through materialization",
      );

      const takeover = yield* append(
        conversationId,
        batch("fence-batch-2", [record("fence-record-2", "second")]),
        first,
        EPOCH_TWO,
      );
      yield* ensure(
        !takeover.replayed && takeover.firstSequence === first.lastSequence + 1,
        "The takeover epoch must append after the committed tail",
      );
    }),
);

const offsetResumability = conformanceCase(
  "resumes observation from a saved offset with exactly the suffix",
  ({ ensure }) =>
    Effect.gen(function* () {
      const conversationId = decodeConversationId("conformance-offsets");
      const store = yield* ConversationStore;
      yield* materialize(conversationId, EPOCH_ONE);
      const first = yield* append(
        conversationId,
        batch("offset-batch-1", [
          record("offset-record-1", "first"),
          record("offset-record-2", "second"),
        ]),
      );
      const second = yield* append(
        conversationId,
        batch("offset-batch-2", [record("offset-record-3", "third")]),
        first,
      );
      yield* append(
        conversationId,
        batch("offset-batch-3", [record("offset-record-4", "fourth")]),
        second,
      );

      const committed = yield* readAll(conversationId);
      yield* ensure(committed.length === 4, "All committed records must be readable");
      const savedOffset = committed[1]?.offset;
      yield* ensure(savedOffset !== undefined, "Committed records must carry observation offsets");
      if (savedOffset === undefined) return;

      const resumed = yield* store
        .observe(ConversationObservation.make({ conversationId, afterOffset: savedOffset }))
        .pipe(Stream.take(2), Stream.runCollect);
      yield* ensure(
        resumed.map((envelope) => envelope.record.recordId).join(",") ===
          committed
            .slice(2)
            .map((envelope) => envelope.record.recordId)
            .join(","),
        "Observation from a saved offset must deliver exactly the suffix in order",
      );

      const fromStart = yield* store
        .observe(ConversationObservation.make({ conversationId }))
        .pipe(Stream.take(4), Stream.runCollect);
      yield* ensure(
        fromStart.map((envelope) => envelope.record.recordId).join(",") ===
          committed.map((envelope) => envelope.record.recordId).join(","),
        "Observation without an offset must deliver the full log in order",
      );
    }),
);

const checkpointBoundaries = conformanceCase(
  "enforces checkpoint save and load boundary rules",
  ({ ensure, expectFailure }) =>
    Effect.gen(function* () {
      const conversationId = decodeConversationId("conformance-checkpoints");
      const store = yield* ConversationStore;
      yield* materialize(conversationId, EPOCH_ONE);
      const first = yield* append(
        conversationId,
        batch("checkpoint-batch-1", [record("checkpoint-record-1", "Kyoto")]),
      );

      const aheadOfTail = yield* expectFailure(
        "a checkpoint claiming a sequence beyond the committed tail",
        store.saveCheckpoint(
          SaveCheckpointRequest.make({
            checkpoint: checkpointAt(
              conversationId,
              decodeSequence(first.lastSequence + 1),
              first.tailDigest,
            ),
          }),
        ),
      );
      yield* ensure(
        aheadOfTail instanceof CheckpointRejected && aheadOfTail.reason === "ahead-of-tail",
        "A checkpoint ahead of the tail must be rejected with reason ahead-of-tail",
      );

      const digestMismatch = yield* expectFailure(
        "a checkpoint whose digest does not match the canonical chain",
        store.saveCheckpoint(
          SaveCheckpointRequest.make({
            checkpoint: checkpointAt(conversationId, first.lastSequence, EMPTY_TAIL_DIGEST),
          }),
        ),
      );
      yield* ensure(
        digestMismatch instanceof CheckpointRejected && digestMismatch.reason === "digest-mismatch",
        "A checkpoint with a mismatched digest must be rejected with reason digest-mismatch",
      );
      yield* ensure(
        Option.isNone(yield* store.loadCheckpoint(LoadCheckpointRequest.make({ conversationId }))),
        "Rejected checkpoints must not become loadable",
      );

      const valid = checkpointAt(conversationId, first.lastSequence, first.tailDigest);
      yield* store.saveCheckpoint(SaveCheckpointRequest.make({ checkpoint: valid }));
      yield* store.saveCheckpoint(SaveCheckpointRequest.make({ checkpoint: valid }));

      const loaded = yield* store.loadCheckpoint(LoadCheckpointRequest.make({ conversationId }));
      yield* ensure(
        Option.isSome(loaded) &&
          loaded.value.throughSequence === first.lastSequence &&
          loaded.value.tailDigest === first.tailDigest,
        "A valid checkpoint must load bound to its canonical sequence and digest",
      );

      const beforeCheckpoint = yield* store.loadCheckpoint(
        LoadCheckpointRequest.make({ conversationId, atOrBeforeSequence: ZERO_SEQUENCE }),
      );
      yield* ensure(
        Option.isNone(beforeCheckpoint),
        "Checkpoint lookup must respect the atOrBeforeSequence bound",
      );

      yield* append(
        conversationId,
        batch("checkpoint-batch-2", [record("checkpoint-record-2", "Nara")]),
        first,
      );
      const afterAppend = yield* store.loadCheckpoint(
        LoadCheckpointRequest.make({ conversationId }),
      );
      yield* ensure(
        Option.isSome(afterAppend) && afterAppend.value.throughSequence === first.lastSequence,
        "An older checkpoint must remain loadable after later appends",
      );
    }),
);

const tailInspection = conformanceCase(
  "inspects the canonical tail so a resuming producer can compose its next append",
  ({ ensure, expectFailure }) =>
    Effect.gen(function* () {
      const conversationId = decodeConversationId("conformance-tail-inspection");
      const store = yield* ConversationStore;

      const missing = yield* expectFailure(
        "inspecting the tail of an unmaterialized Conversation",
        store.inspectTail(ConversationTailRequest.make({ conversationId })),
      );
      yield* ensure(
        missing instanceof ConversationNotMaterialized && missing.conversationId === conversationId,
        "Tail inspection of an unmaterialized Conversation must fail as not materialized",
      );

      yield* materialize(conversationId, EPOCH_ONE);
      const empty = yield* store.inspectTail(ConversationTailRequest.make({ conversationId }));
      yield* ensure(
        empty.tailSequence === ZERO_SEQUENCE &&
          empty.tailDigest === EMPTY_TAIL_DIGEST &&
          empty.producerEpoch === EPOCH_ONE,
        "An empty Conversation must report the zero tail and its registered epoch",
      );

      const first = yield* append(
        conversationId,
        batch("inspect-batch-1", [record("inspect-record-1", "first")]),
      );
      const afterAppend = yield* store.inspectTail(
        ConversationTailRequest.make({ conversationId }),
      );
      yield* ensure(
        afterAppend.tailSequence === first.lastSequence &&
          afterAppend.tailDigest === first.tailDigest,
        "Tail inspection must match the latest AppendResult",
      );

      const resumed = yield* append(
        conversationId,
        batch("inspect-batch-2", [record("inspect-record-2", "second")]),
        { lastSequence: afterAppend.tailSequence, tailDigest: afterAppend.tailDigest },
        afterAppend.producerEpoch,
      );
      yield* ensure(
        resumed.firstSequence === afterAppend.tailSequence + 1,
        "An append composed from the inspected tail must commit without exporting the log",
      );

      yield* materialize(conversationId, EPOCH_TWO);
      const afterTakeover = yield* store.inspectTail(
        ConversationTailRequest.make({ conversationId }),
      );
      yield* ensure(
        afterTakeover.producerEpoch === EPOCH_TWO &&
          afterTakeover.tailSequence === resumed.lastSequence,
        "Tail inspection must reflect epoch takeover without disturbing the tail",
      );
    }),
);

const notMaterializedOperations = conformanceCase(
  "fails every read and write against an unmaterialized Conversation",
  ({ ensure, expectFailure }) =>
    Effect.gen(function* () {
      const conversationId = decodeConversationId("conformance-not-materialized");
      const store = yield* ConversationStore;

      const failures = [
        yield* expectFailure(
          "appending to an unmaterialized Conversation",
          append(conversationId, batch("missing-batch-1", [record("missing-record-1", "first")])),
        ),
        yield* expectFailure("reading an unmaterialized Conversation", readAll(conversationId)),
        yield* expectFailure(
          "observing an unmaterialized Conversation",
          store
            .observe(ConversationObservation.make({ conversationId }))
            .pipe(Stream.take(1), Stream.runCollect),
        ),
        yield* expectFailure(
          "exporting an unmaterialized Conversation",
          store.export(ConversationExportRequest.make({ conversationId })),
        ),
        yield* expectFailure(
          "inspecting the tail of an unmaterialized Conversation",
          store.inspectTail(ConversationTailRequest.make({ conversationId })),
        ),
        yield* expectFailure(
          "saving a checkpoint for an unmaterialized Conversation",
          store.saveCheckpoint(
            SaveCheckpointRequest.make({
              checkpoint: checkpointAt(conversationId, ZERO_SEQUENCE, EMPTY_TAIL_DIGEST),
            }),
          ),
        ),
        yield* expectFailure(
          "loading a checkpoint for an unmaterialized Conversation",
          store.loadCheckpoint(LoadCheckpointRequest.make({ conversationId })),
        ),
      ];
      yield* Effect.forEach(
        failures,
        (failure) =>
          ensure(
            failure instanceof ConversationNotMaterialized &&
              failure.conversationId === conversationId,
            "Operations against an unmaterialized Conversation must fail as not materialized",
          ),
        { discard: true },
      );
    }),
);

