      });
      expect(findEvent(events, "ToolCallSucceeded")).toMatchObject({
        result: { output: { answer: "paid" }, budgetExhausted: false },
      });
    }),
  );

  it.effect("inherits defaults, clamps child overrides, and keeps partial results visible", () =>
    Effect.gen(function* () {
      for (const overrides of [
        undefined,
        { onExhaustion: "final-answer" as const, maxToolCalls: 20 },
      ]) {
        const starts = yield* Ref.make(0);

        const delegation = Subagent.define("delegate_defaults", {
          target: Agent.make("defaults-child", {
            input: ChildInput,
            output: ChildOutput,
            instructions: "Probe, then answer as JSON.",
            toolkit: probeToolkit,
            policy: overrides,
          }),
          failureMode: "return",
        });

        const parent = Agent.make("defaults-parent", {
          input: Schema.String,
          output: Schema.String,
          instructions: "Delegate.",
          toolkit: Toolkit.make(delegation.tool),
          policy: { maxTurns: 3, maxToolCalls: 1, toolConcurrency: 1, onExhaustion: "fail" },
        });

        const model = probingChildModel([
          { topic: "defaults", declares: 2, answer: '{"answer":"partial"}' },
        ]);

        const childLayer = SubagentRuntime.layer(delegation, model).pipe(
          Layer.provide(
            probeToolkit.toLayer({
              probe_doc: () => Ref.update(starts, (n) => n + 1).pipe(Effect.as("found")),
            }),
          ),
        );

        const handle = yield* AgentRuntime.start(parent, "start").pipe(
          Effect.provide([
            childLayer,
            delegatingModel(
              "defaults-parent",
              delegation.name,
              [{ id: "defaults", params: { question: "research:defaults" } }],
              '"done"',
            ),
          ]),
        );

        const completed = yield* handle.await;
        const result = findEvent(yield* handle.events, "ToolCallSucceeded");

        expect(result).toMatchObject({
          result:
            overrides === undefined
              ? {
                  _tag: "SubagentExecutionFailure",
                  classification: "child-failed",
                  errorTag: "AgentPolicyError",
                  message: "The child Run failed",
                }
              : { output: { answer: "partial" }, budgetExhausted: true },
        });
        expect(yield* Ref.get(starts)).toBe(0);
        const reservations = yield* SubagentReservations;
        const snapshot = yield* reservations.parentSnapshot(completed.runId);

        expect(snapshot.totalChildInvocations).toBe(1);
        expectSettledOnce(snapshot.reservations[0]);
      }
    }),
  );

  it.effect(
    "derives schemas without re-decoding transformed input and allows only a result projection",
    () =>
      Effect.gen(function* () {
        const input = Schema.Struct({ amount: Schema.NumberFromString });

        const target = Agent.make("transformed-child", {
          input,
          output: ChildOutput,
          instructions: ({ amount }) => `Amount ${amount + 1}`,
          toolkit: Toolkit.empty,
        });

        const delegation = Subagent.make("research", { target });

        const projected = Subagent.make("projected_result", {
          target,
          success: Schema.String,
          projectResult: (output) => Effect.succeed(output.answer),
        });

        const prompt = yield* Ref.make<unknown>(undefined);

        const parent = Agent.make("transformed-parent", {
          input: Schema.String,
          output: Schema.String,
          instructions: "Delegate.",
          toolkit: Toolkit.make(delegation.tool),
        });

        const handle = yield* AgentRuntime.start(parent, "start").pipe(
          Effect.provide([
            SubagentRuntime.layer(
              delegation,
              answeringModel("transformed", '{"answer":"ok"}', prompt),
            ),
            delegatingModel(
              "transformed-parent",
              delegation.name,
              [{ id: "transformed", params: { amount: "41" } }],
              '"done"',
            ),
          ]),
        );

        yield* handle.await;
        expect(findEvent(yield* handle.events, "ToolCallSucceeded")).toMatchObject({
          result: { output: { answer: "ok" }, budgetExhausted: false },
        });
        expect(JSON.stringify(yield* Ref.get(prompt))).toContain("Amount 42");
        expect(
          yield* projected.projectResult(
            { answer: "public" },
            { budgetExhausted: false },
            { amount: 41 },
          ),
        ).toBe("public");

        const proofs: [
          Assert<Equal<typeof delegation.name, "research">>,
          Assert<Equal<Tool.Parameters<typeof delegation.tool>, { readonly amount: number }>>,
          Assert<
            Equal<
              Tool.Success<typeof delegation.tool>,
              { readonly output: { readonly answer: string }; readonly budgetExhausted: boolean }
            >
          >,
        ] = [true, true, true];

        expect(proofs).toEqual([true, true, true]);
      }),
  );

  it("rejects a binding for a different target before acquiring resources", () => {
    const delegation = Subagent.define("delegate_identity", { target: childDefinition });
    const other = { ...childDefinition };

    expect(() =>
      SubagentRuntime.layer(
        delegation,
        Agent.withModel(other, answeringModel("other", '{"answer":"wrong"}')),
      ),
    ).toThrow(/exact target/);
  });
});

layer(TestServices)("SubagentRuntime SUB-034 per-invocation allowance", (it) => {
  const runAllowance = (options: {
    readonly name: string;
    readonly calls: ReadonlyArray<{ readonly id: string; readonly params: unknown }>;
    readonly childScripts: ReadonlyArray<{ topic: string; declares: number; answer: string }>;
    readonly runId: string;
  }) =>
    Effect.gen(function* () {
      const probeStarts = yield* Ref.make(0);

      const childBinding = Agent.withModel(
        probingChildDefinition,
        probingChildModel(options.childScripts),
      );

      const parent = Agent.withModel(
        allowanceCoordinator,
        delegatingModel(options.name, "delegate_allowance", options.calls, '{"report":"done"}'),
      );

      const probeLayer = probeToolkit.toLayer({
        probe_doc: ({ ref }) =>
          Ref.update(probeStarts, (count) => count + 1).pipe(Effect.as(`probed-${ref}`)),
      });

      const runtimeLayer = SubagentRuntime.layer(allowanceDelegation, childBinding, {
        mapChildFailure,
      }).pipe(Layer.provide(probeLayer));

      const detached = yield* AgentRuntime.start(
        parent,
        { mission: "m" },
        { runId: decodeRunId(options.runId) },
      ).pipe(Effect.provide(runtimeLayer));

      const result = yield* detached.await;
      const events = yield* detached.events;

      return { result, events, probeStarts: yield* Ref.get(probeStarts) };
    });

  it.effect(
    "SUB-034 the default allowance tightens the child below its Definition policy and the projection surfaces the exhaustion marker",
    () =>
      Effect.gen(function* () {
        const { result, events, probeStarts } = yield* runAllowance({
          name: "parent-allowance-default",
          calls: [{ id: "call-1", params: { topic: "small" } }],
          childScripts: [{ topic: "small", declares: 2, answer: '{"answer":"draft"}' }],
          runId: "parent-run-allowance-default",
        });

        // Definition ceiling 8 admits the batch of 2; the allowance of 1
        // rejects it, no probe executes, and the child soft-lands (RUN-021).
        expect(result.output).toEqual({ report: "done" });
        expect(probeStarts).toBe(0);
        expect(findEvent(events, "ToolCallSucceeded")).toMatchObject({
          result: { summary: "partial:draft" },
        });
        expect(findEvent(events, "SubagentCompleted")).toMatchObject({
          finishReason: "budget-exhausted",
        });
      }),
  );

  it.effect(
    "SUB-034 a model-granted allowance is clamped fail-closed to the per-invocation reservation slice",
    () =>
      Effect.gen(function* () {
        const { result, probeStarts } = yield* runAllowance({
          name: "parent-allowance-clamp",
          calls: [{ id: "call-1", params: { topic: "grant-100" } }],
          childScripts: [{ topic: "grant-100", declares: 5, answer: '{"answer":"clamped"}' }],
          runId: "parent-run-allowance-clamp",
        });

        // Requested 100 clamps to the slice ceiling of 4: the batch of 5 is
        // rejected. A broken clamp (min with the Definition's 8 only) would
        // have executed all five probes.
        expect(result.output).toEqual({ report: "done" });
        expect(probeStarts).toBe(0);
      }),
  );

  it.effect(
    "SUB-034 the orchestrator OBSERVES the budget-truncated partial, then grants an extension by re-delegating",
    () =>
      Effect.gen(function* () {
        const probeStarts = yield* Ref.make(0);

        const childBinding = Agent.withModel(
          probingChildDefinition,
          probingChildModel([
            { topic: "small", declares: 2, answer: '{"answer":"draft"}' },
            { topic: "grant-4", declares: 2, answer: '{"answer":"complete"}' },
          ]),
        );

        // Sequential, content-keyed coordinator: the granting call is
        // declared ONLY after the partial result is visible in the prompt —
        // the grant is a reaction to observed exhaustion, never preplanned.
        const parentModel = Model.make(
          "scripted",
          "parent-allowance-sequential",
          Layer.effect(
            LanguageModel.LanguageModel,
            LanguageModel.make({
              generateText: () => Effect.succeed([]),
              streamText: (request) => {
                const promptJson = JSON.stringify(request.prompt);

                if (promptJson.includes("finding:complete")) {
                  return Stream.fromIterable(finalParts('{"report":"done"}'));
                }
                if (promptJson.includes("partial:draft")) {
                  return Stream.fromIterable<Response.StreamPartEncoded>([
                    {
                      type: "tool-call",
                      id: "call-2",
                      name: "delegate_allowance",
                      params: { topic: "grant-4" },
                      providerExecuted: false,
                    },
                    { type: "finish", reason: "tool-calls", usage },
                  ]);
                }

                return Stream.fromIterable<Response.StreamPartEncoded>([
                  {
                    type: "tool-call",
                    id: "call-1",
                    name: "delegate_allowance",
                    params: { topic: "small" },
                    providerExecuted: false,
                  },
                  { type: "finish", reason: "tool-calls", usage },
                ]);
              },
            }),
          ),
        );

        const parent = Agent.withModel(allowanceCoordinator, parentModel);

        const probeLayer = probeToolkit.toLayer({
          probe_doc: ({ ref }) =>
            Ref.update(probeStarts, (count) => count + 1).pipe(Effect.as(`probed-${ref}`)),
        });

        const runtimeLayer = SubagentRuntime.layer(allowanceDelegation, childBinding, {
          mapChildFailure,
        }).pipe(Layer.provide(probeLayer));

        const detached = yield* AgentRuntime.start(
          parent,
          { mission: "m" },
          { runId: decodeRunId("parent-run-allowance-sequential") },
        ).pipe(Effect.provide(runtimeLayer));

        const result = yield* detached.await;
        const events = yield* detached.events;

        // Turn 1: default allowance 1 rejects the first child's batch — the
        // coordinator SEES "partial:draft" and only then grants allowance 4;
        // the second child executes both probes and returns the full finding.
        expect(result.output).toEqual({ report: "done" });
        expect(yield* Ref.get(probeStarts)).toBe(2);
        const succeeded = events.filter((event) => event._tag === "ToolCallSucceeded");

        expect(succeeded.map((event) => event.result)).toEqual([
          { summary: "partial:draft" },
          { summary: "finding:complete" },
        ]);
      }),
  );

  it.effect(
    "SUB-034 a configured allowance with a non-finite default clamps to the reservation slice, never the Definition policy",
    () =>
      Effect.gen(function* () {
        const brokenDefaultDelegation = Subagent.define("delegate_allowance_broken", {
          description: "Allowance configured with a broken default.",
          target: probingChildDefinition,
          parameters: ResearchParams,
          success: ResearchFindings,
          failure: ResearchDelegationFailed,
          prepareInput: ({ topic }) => Effect.succeed({ question: `research:${topic}` }),
          projectResult: (output, context) =>
            Effect.succeed({
              summary: `${context.budgetExhausted ? "partial:" : "finding:"}${output.answer}`,
            }),
          policy: allowancePolicy,
          toolCallAllowance: { default: Number.NaN },
        });

        const brokenCoordinator = Agent.make("allowance-broken-coordinator", {
          input: Schema.Struct({ mission: Schema.String }),
          output: Schema.Struct({ report: Schema.String }),
          instructions: "Delegate, then answer as JSON.",
          toolkit: Toolkit.make(brokenDefaultDelegation.tool),
          policy: AgentPolicy.make({
            maxTurns: 3,
            maxToolCalls: 3,
            maxDuration: "30 seconds",
            toolConcurrency: 2,
          }),
        });

        const probeStarts = yield* Ref.make(0);

        const childBinding = Agent.withModel(
          probingChildDefinition,
          // Declares 5: above the slice ceiling of 4, below the Definition's 8.
          probingChildModel([{ topic: "small", declares: 5, answer: '{"answer":"sliced"}' }]),
        );

        const parent = Agent.withModel(
          brokenCoordinator,
          delegatingModel(
            "parent-allowance-broken",
            "delegate_allowance_broken",
            [{ id: "call-1", params: { topic: "small" } }],
            '{"report":"done"}',
          ),
        );

        const probeLayer = probeToolkit.toLayer({
          probe_doc: ({ ref }) =>
            Ref.update(probeStarts, (count) => count + 1).pipe(Effect.as(`probed-${ref}`)),
        });

        const runtimeLayer = SubagentRuntime.layer(brokenDefaultDelegation, childBinding, {
          mapChildFailure,
        }).pipe(Layer.provide(probeLayer));

        const detached = yield* AgentRuntime.start(
          parent,
          { mission: "m" },
          { runId: decodeRunId("parent-run-allowance-broken") },
        ).pipe(Effect.provide(runtimeLayer));

        const result = yield* detached.await;

        // A broken default clamps to the SLICE (4): the batch of 5 is
        // rejected. Dropping the allowance entirely would have run all five
        // probes under the Definition's ceiling of 8.
        expect(result.output).toEqual({ report: "done" });
        expect(yield* Ref.get(probeStarts)).toBe(0);
      }),
  );

  it.effect(
    "SUB-034 a non-finite model-granted allowance falls back fail-closed to the default",
    () =>
      Effect.gen(function* () {
        const { result, probeStarts } = yield* runAllowance({
          name: "parent-allowance-nan",
          // "grant-garbage" extracts Number("garbage") === NaN.
          calls: [{ id: "call-1", params: { topic: "grant-garbage" } }],
          childScripts: [{ topic: "grant-garbage", declares: 2, answer: '{"answer":"nan-safe"}' }],
          runId: "parent-run-allowance-nan",
        });

        // NaN never reaches the child options: the default of 1 applies, the
        // batch of 2 is rejected, and the run still soft-lands bounded.
        expect(result.output).toEqual({ report: "done" });
        expect(probeStarts).toBe(0);
      }),
  );

  it.effect(
    "SUB-034 a durable settled budget-exhausted child surfaces the marker to projectResult",
    () =>
      Effect.gen(function* () {
        const invocations = yield* Ref.make(0);
        const child = durableChildIdentity("allowance-durable");

        const subagent = scriptedDurableHook({
          establish: (request) => {
            expect(request.toolCallAllowance).toBe(1);

            return {
              _tag: "settled",
              ...child,
              outcome: "completed",
              encodedResult: { answer: "durable partial" },
              finishReason: "budget-exhausted",
            };
          },
        });

        const parent = Agent.withModel(
          allowanceCoordinator,
          delegatingModel(
            "parent-allowance-durable",
            "delegate_allowance",
            [{ id: "call-1", params: { topic: "small" } }],
            '{"report":"done"}',
          ),
        );

        const probeLayer = probeToolkit.toLayer({
          probe_doc: () => Effect.succeed("unused"),
        });

        const runtimeLayer = SubagentRuntime.layer(
          allowanceDelegation,
          countingProbingChildBinding(invocations),
          { mapChildFailure, durable: { targetDigests: durableDigests } },
        ).pipe(Layer.provide(probeLayer));

        const detached = yield* AgentRuntime.start(
          parent,
          { mission: "m" },
          { runId: decodeRunId("parent-run-allowance-durable"), subagent },
        ).pipe(Effect.provide(runtimeLayer));

        const result = yield* detached.await;
        const events = yield* detached.events;

        expect(result.output).toEqual({ report: "done" });
        expect(yield* Ref.get(invocations)).toBe(0);
        // The durable Settlement's honest marker reached the projection: the
        // parent Tool result carries the budget-truncated partial.
        expect(findEvent(events, "ToolCallSucceeded")).toMatchObject({
          result: { summary: "partial:durable partial" },
        });
      }),
  );
});

/** Probing-child binding whose scripted model counts invocations (durable mode must never run it). */
const countingProbingChildBinding = (invocations: Ref.Ref<number>) =>
  Agent.withModel(
    probingChildDefinition,
    Model.make(
      "scripted",
      "probing-counting-child",
      Layer.effect(
        LanguageModel.LanguageModel,
        LanguageModel.make({
          generateText: () => Effect.succeed([]),
          streamText: () =>
            Stream.unwrap(
              Ref.update(invocations, (count) => count + 1).pipe(
                Effect.as(
                  Stream.fromIterable<Response.StreamPartEncoded>(
                    finalParts('{"answer":"in-process"}'),
                  ),
                ),
              ),
            ),
        }),
      ),
    ),
  );

import * as Schema from "effect/Schema";

const identifier = <const Name extends string>(name: Name) =>
  Schema.NonEmptyString.pipe(Schema.brand(`@effect-agent/core/${name}`));

/** Stable identity of an agent definition, distinct from a display name. */
export const AgentId = identifier("AgentId");
export type AgentId = typeof AgentId.Type;

/** Identity shared by runs that participate in one thread history. */
export const ThreadId = identifier("ThreadId");
export type ThreadId = typeof ThreadId.Type;

/** Identity of one accepted input submission. */
export const SubmissionId = identifier("SubmissionId");
export type SubmissionId = typeof SubmissionId.Type;

/** Durable identity returned once ledger admission and Thread readiness are committed. */
export const ReceiptId = identifier("ReceiptId");
export type ReceiptId = typeof ReceiptId.Type;

/** Identity of the single durable terminal outcome owed to one accepted Submission. */
export const SettlementId = identifier("SettlementId");
export type SettlementId = typeof SettlementId.Type;

/** Identity of one execution ownership period for accepted work. */
export const AttemptId = identifier("AttemptId");
export type AttemptId = typeof AttemptId.Type;

/** Identity of one logical agent run. */
export const RunId = identifier("RunId");
export type RunId = typeof RunId.Type;

/** Identity of one model turn within a run. */
export const TurnId = identifier("TurnId");
export type TurnId = typeof TurnId.Type;

/** Identity used to correlate a Tool Call with progress and its terminal outcome. */
export const ToolCallId = identifier("ToolCallId");
export type ToolCallId = typeof ToolCallId.Type;

/** Stable identity of one configured Subagent capability. */
export const DelegationId = identifier("DelegationId");
export type DelegationId = typeof DelegationId.Type;

/** Opaque position in a semantic event sequence. */
export const EventOffset = identifier("EventOffset");
export type EventOffset = typeof EventOffset.Type;

import { Schema } from "effect";

import { AgentId, ThreadId, DelegationId, RunId, ToolCallId, TurnId } from "./Identifiers.ts";
import { DelegationDepth } from "./SubagentContract.ts";
import { Selection } from "./ToolExposure.ts";

const RunEventBase = {
  eventVersion: Schema.Literal(1),
  runId: RunId,
  threadId: ThreadId,
  agentId: AgentId,
  sequence: Schema.Natural,
  timestamp: Schema.DateTimeUtcFromString,
  turnId: Schema.optionalKey(TurnId),
  toolCallId: Schema.optionalKey(ToolCallId),
};

/** Signals that the runtime has created a run and assigned its identities. */
export class RunStarted extends Schema.TaggedClass<RunStarted>()("RunStarted", RunEventBase) {}

/** Signals the start of a positive-numbered model turn. */
export class TurnStarted extends Schema.TaggedClass<TurnStarted>()("TurnStarted", {
  ...RunEventBase,
  turn: Schema.Int.check(Schema.isGreaterThan(0)),
}) {}

/** Signals that the model request for a turn is starting. */
export class ModelStarted extends Schema.TaggedClass<ModelStarted>()("ModelStarted", {
  ...RunEventBase,
  turn: Schema.Int.check(Schema.isGreaterThan(0)),
}) {}

/** Carries one live assistant text delta. */
export class TextDelta extends Schema.TaggedClass<TextDelta>()("TextDelta", {
  ...RunEventBase,
  text: Schema.String,
}) {}

/** Carries reasoning content explicitly exposed by the provider. */
export class ReasoningDelta extends Schema.TaggedClass<ReasoningDelta>()("ReasoningDelta", {
  ...RunEventBase,
  text: Schema.String,
}) {}

/** Reports a complete model-declared Tool Call and its execution boundary. */
export class ToolCallDeclared extends Schema.TaggedClass<ToolCallDeclared>()("ToolCallDeclared", {
  ...RunEventBase,
  toolCallId: ToolCallId,
  toolName: Schema.NonEmptyString,
  parameters: Schema.Json,
  providerExecuted: Schema.Boolean,
}) {}

/** Signals that a validated Tool Call handler has started. */
export class ToolCallStarted extends Schema.TaggedClass<ToolCallStarted>()("ToolCallStarted", {
  ...RunEventBase,
  toolCallId: ToolCallId,
  toolName: Schema.NonEmptyString,
}) {}

/** Carries a preliminary Tool result that is not the call's terminal outcome. */
export class ToolProgress extends Schema.TaggedClass<ToolProgress>()("ToolProgress", {
  ...RunEventBase,
  toolCallId: ToolCallId,
  toolName: Schema.NonEmptyString,
  result: Schema.Json,
  providerExecuted: Schema.Boolean,
}) {}

/** Records the successful terminal result of a Tool Call. */
export class ToolCallSucceeded extends Schema.TaggedClass<ToolCallSucceeded>()(
  "ToolCallSucceeded",
  {
    ...RunEventBase,
    toolCallId: ToolCallId,
    toolName: Schema.NonEmptyString,
    toolSelection: Schema.optionalKey(Selection),
    result: Schema.Json,
    providerExecuted: Schema.Boolean,
  },
) {}

/**
 * How this boundary handled a failed invocation, independently of its native failure mode.
 * `returned-to-model` records the result path; delivery still requires the complete batch to
 * commit and a later model call. A sibling, policy or later operation can still fail the Run.
 * This classification never implies that side effects were rolled back.
 */
export const ToolFailureHandling = Schema.Literals([
  "propagated",
  "returned-to-model",
  "returned-to-caller",
]);

export type ToolFailureHandling = typeof ToolFailureHandling.Type;

/** Records a terminal Tool Call failure using safe, serializable diagnostics. */
export class ToolCallFailed extends Schema.TaggedClass<ToolCallFailed>()("ToolCallFailed", {
  ...RunEventBase,
  toolCallId: ToolCallId,
  toolName: Schema.NonEmptyString,
  errorTag: Schema.NonEmptyString,
  message: Schema.String,
  providerExecuted: Schema.Boolean,
  /** Native configuration when a local Tool is known; absent on provider results and old events. */
  failureMode: Schema.optionalKey(Schema.Literals(["error", "return"])),
  /** Actual route at this boundary. Absence on older events means unknown, never recoverable. */
  failureHandling: Schema.optionalKey(ToolFailureHandling),
  /** Synthetic policy rejection; no handler ran and the failure streak is unchanged. */
  budgetRejected: Schema.optionalKey(Schema.Literal(true)),
}) {}

/** Signals that a decoded Tool Call requires approval before execution. */
export class ApprovalRequested extends Schema.TaggedClass<ApprovalRequested>()(
  "ApprovalRequested",
  {
    ...RunEventBase,
    toolCallId: ToolCallId,
    toolName: Schema.NonEmptyString,
  },
) {}

/** Records the normalized finish reason for a completed assistant turn. */
export class TurnCompleted extends Schema.TaggedClass<TurnCompleted>()("TurnCompleted", {
  ...RunEventBase,
  turn: Schema.Int.check(Schema.isGreaterThan(0)),
  finishReason: Schema.Literals([
    "stop",
    "length",
    "content-filter",
    "tool-calls",
    "error",
    "pause",
    "other",
    "unknown",
  ]),
}) {}

/** Advisory that one policy limit crossed its warning fraction; emitted once per limit per run. */
export class BudgetWarning extends Schema.TaggedClass<BudgetWarning>()("BudgetWarning", {
  ...RunEventBase,
  limit: Schema.Literals(["tokens", "tool-calls", "turns", "duration", "context"]),
  consumed: Schema.Natural,
  limitValue: Schema.Natural,
}) {}

/** Records that the engine reduced model context at a Turn seam without erasing source history. */
export class CompactionPerformed extends Schema.TaggedClass<CompactionPerformed>()(
  "CompactionPerformed",
  {
    ...RunEventBase,
    turn: Schema.Int.check(Schema.isGreaterThan(0)),
    kind: Schema.Literals(["clear-tool-results", "summarize", "rollover"]),
    tokensBeforeEstimate: Schema.Natural,
    tokensAfterEstimate: Schema.Natural,
  },
) {}

/**
 * Dimension that bound when a Run settled through the final-answer resolution
 * (RUN-018; the token dimension per RUN-025). This is the exhausted marker
 * the re-delegation grant flow (RUN-021) consumes and the durable
 * `SubmissionSettled` record persists (RUN-011).
 */
export const ExhaustedLimit = Schema.Literals(["tokens", "tool-calls", "turns"]);
export type ExhaustedLimit = typeof ExhaustedLimit.Type;

const CompletionFinishReason = Schema.Literals(["completed", "model-stop", "budget-exhausted"]);

type CompletionMetadata = Readonly<{
  finishReason: typeof CompletionFinishReason.Type;
  exhausted?: ExhaustedLimit | undefined;
}>;

const validateCompletionMetadata = ({
  exhausted,
  finishReason,
}: CompletionMetadata): string | undefined => {
  const isBudgetExhausted = finishReason === "budget-exhausted";

  return isBudgetExhausted === (exhausted !== undefined)
    ? undefined
    : '`exhausted` must be present exactly when `finishReason` is "budget-exhausted"';
};

const RunCompletedFields = Schema.Struct({
  ...RunEventBase,
  output: Schema.Json,
  /** Schema-encoded application disposition, present only for an ordinary completed Run. */
  runDisposition: Schema.optionalKey(Schema.Json),
  turns: Schema.Int.check(Schema.isGreaterThan(0)),
  finishReason: CompletionFinishReason,
  exhausted: Schema.optionalKey(ExhaustedLimit),
}).check(
  Schema.makeFilter((event) => validateCompletionMetadata(event)),
  Schema.makeFilter((event) =>
    event.finishReason === "budget-exhausted" && event.runDisposition !== undefined
      ? {
          path: ["runDisposition"],
          issue: '`runDisposition` is not allowed when `finishReason` is "budget-exhausted"',
        }
      : undefined,
  ),
);

/**
 * Successful terminal event carrying Schema-compatible output and the completed turn count.
 * `"budget-exhausted"` marks a Run that settled through the policy's final-answer resolution
 * after Turn, Tool Call, or token exhaustion — never a plain `"model-stop"` (RUN-011); its
 * `turns` count may exceed `maxTurns` by the single grace Turn, and `exhausted` names the
 * dimension that bound.
 *
 * Invariant: `exhausted` is present exactly when `finishReason` is
 * `"budget-exhausted"`, and a budget-exhausted completion has no application
 * run disposition. The checked Struct enforces both rules during construction,
 * decoding, and encoding without replacing the class in `RunEvent`.
 */
export class RunCompleted extends Schema.TaggedClass<RunCompleted>()(
  "RunCompleted",
  RunCompletedFields,
) {}

/** Terminal event for a run that failed with an expected error. */
export class RunFailed extends Schema.TaggedClass<RunFailed>()("RunFailed", {
  ...RunEventBase,
  errorTag: Schema.NonEmptyString,
  message: Schema.String,
}) {}

/** Terminal event for a run stopped by interruption. */
export class RunInterrupted extends Schema.TaggedClass<RunInterrupted>()("RunInterrupted", {
  ...RunEventBase,
  message: Schema.String,
}) {}

/** Terminal event for a run awaiting resumable external input. */
export class RunSuspended extends Schema.TaggedClass<RunSuspended>()("RunSuspended", {
  ...RunEventBase,
  reason: Schema.String,
}) {}

const SubagentText = Schema.String.check(Schema.isMaxLength(4 * 1024));

const SubagentEventBase = {
  ...RunEventBase,
  turnId: TurnId,
  toolCallId: ToolCallId,
  delegationId: DelegationId,
  childThreadId: ThreadId,
  childRunId: RunId,
  targetAgentId: AgentId,
  depth: DelegationDepth,
};

/** Signals that a delegation Tool Call passed preflight with preallocated child identity. */
export class SubagentRequested extends Schema.TaggedClass<SubagentRequested>()(
  "SubagentRequested",
  SubagentEventBase,
) {}

/** Signals that the child run has started inside its parent-owned scoped region. */
export class SubagentStarted extends Schema.TaggedClass<SubagentStarted>()(
  "SubagentStarted",
  SubagentEventBase,
) {}

/** Carries a bounded child progress summary without duplicating the child event stream. */
export class SubagentProgress extends Schema.TaggedClass<SubagentProgress>()("SubagentProgress", {
  ...SubagentEventBase,
  summary: SubagentText,
}) {}

/**
 * Records the child run's successful terminal outcome before the parent join.
 * Same invariant as `RunCompleted`: `exhausted` is present exactly when
 * `finishReason` is `"budget-exhausted"` (the pair travels verbatim from the
 * child's terminal event); consumers treat a divergent pair fail-safe.
 */
export class SubagentCompleted extends Schema.TaggedClass<SubagentCompleted>()(
  "SubagentCompleted",
  Schema.Struct({
    ...SubagentEventBase,
    turns: Schema.Int.check(Schema.isGreaterThan(0)),
    finishReason: CompletionFinishReason,
    exhausted: Schema.optionalKey(ExhaustedLimit),
  }).check(Schema.makeFilter((event) => validateCompletionMetadata(event))),
) {}

/** Records the child run's expected terminal failure using safe, serializable diagnostics. */
export class SubagentFailed extends Schema.TaggedClass<SubagentFailed>()("SubagentFailed", {
  ...SubagentEventBase,
  errorTag: Schema.NonEmptyString,
  message: SubagentText,
}) {}

/** Records that the child run was stopped by interruption before a terminal outcome. */
export class SubagentInterrupted extends Schema.TaggedClass<SubagentInterrupted>()(
  "SubagentInterrupted",
  {
    ...SubagentEventBase,
    reason: SubagentText,
  },
) {}

/** Records that the child's terminal outcome was joined into its parent delegation Tool Call. */
export class SubagentJoined extends Schema.TaggedClass<SubagentJoined>()(
  "SubagentJoined",
  SubagentEventBase,
) {}

/** Versioned union of stable semantic run events, excluding raw provider chunks. */
export const RunEvent = Schema.Union([
  RunStarted,
  TurnStarted,
  ModelStarted,
  TextDelta,
  ReasoningDelta,
  ToolCallDeclared,
  ToolCallStarted,
  ToolProgress,
  ToolCallSucceeded,
  ToolCallFailed,
  ApprovalRequested,
  TurnCompleted,
  BudgetWarning,
  CompactionPerformed,
  RunCompleted,
  RunFailed,
  RunInterrupted,
  RunSuspended,
  SubagentRequested,
  SubagentStarted,
  SubagentProgress,
  SubagentCompleted,
  SubagentFailed,
  SubagentInterrupted,
  SubagentJoined,
]);

export type RunEvent = typeof RunEvent.Type;

import { Context, Schema } from "effect";

import { AgentId, ThreadId, DelegationId, RunId, ToolCallId } from "./Identifiers.ts";

const Natural = Schema.Natural;

/** Tree authority ceiling. Each child exposes only its own Toolkit's permitted names. */
export class SubagentGrant extends Schema.Class<SubagentGrant>(
  "@effect-agent/capabilities/SubagentGrant",
)({
  allowedToolNames: Schema.Array(Schema.NonEmptyString).check(Schema.isMaxLength(128)),
  maxDepth: Schema.Int.check(Schema.isBetween({ minimum: 1, maximum: 16 })),
  /** Omitted permits either lifetime within the depth and reserved subtree budgets. */
  childLifetimes: Schema.optionalKey(
    Schema.Array(Schema.Literals(["attached", "background"])).check(Schema.isMaxLength(2)),
  ),
}) {}

/** Intersect inherited authority; another delegation can never restore a removed capability. */
export const narrowSubagentGrant = (
  declared: SubagentGrant,
  inherited?: SubagentGrant,
): SubagentGrant =>
  inherited === undefined
    ? declared
    : SubagentGrant.make({
        allowedToolNames: declared.allowedToolNames.filter((name) =>
          inherited.allowedToolNames.includes(name),
        ),
        maxDepth: Math.min(declared.maxDepth, inherited.maxDepth),
        childLifetimes: (declared.childLifetimes ?? ["attached", "background"]).filter((lifetime) =>
          (inherited.childLifetimes ?? ["attached", "background"]).includes(lifetime),
        ),
      });

/** Finite delegable caps for one parent Run. Absent means not configured; present values are finite. */
export class SubagentDelegationCaps extends Schema.Class<SubagentDelegationCaps>(
  "@effect-agent/capabilities/SubagentDelegationCaps",
)({
  maxTotalChildInvocations: Schema.optionalKey(Natural),
  maxConcurrentChildren: Schema.optionalKey(Natural),
  maxTurns: Schema.optionalKey(Natural),
  maxToolCalls: Schema.optionalKey(Natural),
  maxDurationMillis: Schema.optionalKey(Natural),
  maxInputTokens: Schema.optionalKey(Natural),
  maxOutputTokens: Schema.optionalKey(Natural),
  maxCostMicrousd: Schema.optionalKey(Natural),
  maxResultBytes: Schema.optionalKey(Natural),
}) {}

const AmountFields = {
  turns: Natural,
  toolCalls: Natural,
  durationMillis: Natural,
  inputTokens: Natural,
  outputTokens: Natural,
  costMicrousd: Natural,
  resultBytes: Natural,
} as const;

/** Exact amounts across every reservable delegation dimension. */
export class SubagentReservationAmounts extends Schema.Class<SubagentReservationAmounts>(
  "@effect-agent/capabilities/SubagentReservationAmounts",
)(AmountFields) {}

/** One child reservation against the parent Run's shared delegation pool. */
export const SubagentBudgetReservation = Schema.Struct({
  caps: SubagentDelegationCaps,
  allocation: SubagentReservationAmounts,
  /** Slots reserved for every descendant input beneath this input; absent reserves none. */
  descendantInvocations: Schema.optionalKey(Natural),
});

export type SubagentBudgetReservation = typeof SubagentBudgetReservation.Type;

/** Root-relative delegation depth; the direct child of a top-level run has depth 1. */
export const DelegationDepth = Schema.Int.check(Schema.isGreaterThanOrEqualTo(1));
export type DelegationDepth = typeof DelegationDepth.Type;

/** @deprecated Names are application-owned; use DelegationTool metadata for classification. */
export const delegationToolPrefix = "delegate_";

/** @deprecated Checks a legacy spelling only, never execution, nesting or recovery semantics. */
export const isDelegationToolName = (toolName: string): boolean =>
  toolName.startsWith(delegationToolPrefix);

/** Marks a Tool implementing the idempotent Subagent establishment protocol. */
export const DelegationTool = Context.Reference<boolean>("@effect-agent/core/DelegationTool", {
  defaultValue: () => false,
});

/** Marks a host-managed idempotent worker operation, independently of its Tool name. */
export const WorkerOperationTool = Context.Reference<boolean>(
  "@effect-agent/core/WorkerOperationTool",
  {
    defaultValue: () => false,
  },
);

/** Identifies the background launch operation within a generated management Toolkit. */
export const BackgroundSpawnTool = Context.Reference<boolean>(
  "@effect-agent/core/BackgroundSpawnTool",
  {
    defaultValue: () => false,
  },
);

/** Declaration metadata and inherited authority determine the effective visible Tool set. */
export const isSubagentToolAllowed = (
  grant: SubagentGrant | undefined,
  depth: number,
  name: string,
  annotations: Context.Context<never>,
): boolean =>
  grant === undefined ||
  (grant.allowedToolNames.includes(name) &&
    (Context.get(annotations, BackgroundSpawnTool)
      ? depth < grant.maxDepth &&
        (grant.childLifetimes ?? ["attached", "background"]).includes("background")
      : Context.get(annotations, DelegationTool)
        ? depth < grant.maxDepth &&
          (grant.childLifetimes ?? ["attached", "background"]).includes("attached")
        : true));

/** Persisted preparation classification, checked against the resolved Tool before replay. */
export const ToolExecutionKind = Schema.Literals(["ordinary", "delegation", "orchestration"]);
export type ToolExecutionKind = typeof ToolExecutionKind.Type;

/** Resolve only trusted declaration metadata; names never authorize automatic replay. */
export const getToolExecutionKind = (annotations: Context.Context<never>): ToolExecutionKind =>
  Context.get(annotations, WorkerOperationTool)
    ? "orchestration"
    : Context.get(annotations, DelegationTool)
      ? "delegation"
      : "ordinary";

/** Immutable lineage from a child Thread to the parent identity that established it. */
export class SubagentParentLink extends Schema.Class<SubagentParentLink>("SubagentParentLink")({
  delegationId: DelegationId,
  parentAgentId: AgentId,
  parentThreadId: ThreadId,
  parentRunId: RunId,
  parentToolCallId: ToolCallId,
  depth: DelegationDepth,
}) {}

import { Context, Schema } from "effect";
import type { Tool } from "effect/unstable/ai";

/** Registered native names only. Empty selection deliberately clears non-pinned Tools. */
export const ToolNames = Schema.Array(
  Schema.String.check(Schema.isMinLength(1), Schema.isMaxLength(256)),
).check(
  Schema.isMaxLength(1_024),
  Schema.makeFilter((names) => new Set(names).size === names.length, {
    title: "Tool names are unique",
  }),
);

/** One run-scoped replacement, independent of search and of model-visible result text. */
export class Selection extends Schema.Class<Selection>("@effect-agent/core/ToolExposure/Selection")(
  {
    toolNames: ToolNames,
  },
) {}

/** Exact declarations used by one model request, with the selection that produced them. */
export class Snapshot extends Schema.Class<Snapshot>("@effect-agent/core/ToolExposure/Snapshot")({
  exposedToolNames: ToolNames,
  selection: Schema.optionalKey(Selection),
}) {}

export const Limits = Schema.Struct({
  maxTools: Schema.Int.check(Schema.isGreaterThan(0), Schema.isLessThanOrEqualTo(1_024)),
  maxSchemaBytes: Schema.Int.check(Schema.isGreaterThan(0), Schema.isLessThanOrEqualTo(4_194_304)),
});

/** Omission preserves eager exposure. Selection changes take effect only after a complete batch. */
export interface Configuration {
  readonly initialToolNames?: ReadonlyArray<string> | undefined;
  readonly maxTools?: number | undefined;
  readonly maxSchemaBytes?: number | undefined;
}

/** Trusted grouping metadata; never inferred from a Tool's name. */
export const ToolNamespace = Context.Reference<string | undefined>(
  "@effect-agent/core/ToolExposure/ToolNamespace",
  { defaultValue: () => undefined },
);

/** An ordinary readonly Tool whose successful result has a `toolNames` field of native names. */
export const DiscoveryTool = Context.Reference<boolean>(
  "@effect-agent/core/ToolExposure/DiscoveryTool",
  { defaultValue: () => false },
);

/** Remains selected while eligible. Host visibility and inherited grants may hide an explicit
 * pin without failing the Run; discovery, context rollover and required completion stay mandatory.
 */
export const PinnedTool = Context.Reference<boolean>("@effect-agent/core/ToolExposure/PinnedTool", {
  defaultValue: () => false,
});

/** Extra documentation candidates executed through their owning native Tool, such as Code Mode. */
export interface AdditionalCatalogEntry {
  readonly tool: Tool.Any;
  readonly namespace: string;
  readonly method: string;
}

export const AdditionalToolCatalog = Context.Reference<ReadonlyArray<AdditionalCatalogEntry>>(
  "@effect-agent/core/ToolExposure/AdditionalToolCatalog",
  { defaultValue: () => [] },
);

/** The owning Tool description embeds its complete additional catalogue. */
export const IncludesCatalogDocumentation = Context.Reference<boolean>(
  "@effect-agent/core/ToolExposure/IncludesCatalogDocumentation",
  { defaultValue: () => false },
);

import { Effect, Schema } from "effect";

const UsageIdentity = Schema.NonEmptyString.check(Schema.isMaxLength(256));

/** Bounded provider response identity. Request configuration is not response evidence. */
export class ModelResponseIdentity extends Schema.Class<ModelResponseIdentity>(
  "@effect-agent/core/ModelResponseIdentity",
)({
  id: Schema.optionalKey(UsageIdentity),
  model: Schema.optionalKey(UsageIdentity),
}) {}

/** Missing legacy status means unknown, never a free call or a complete report. */
export const UsageCompleteness = Schema.Literals(["complete", "partial", "unknown"]);

const hasAdditiveTotal = (total: number, components: ReadonlyArray<number>): boolean => {
  const sum = components.reduce((accumulator, component) => accumulator + component, 0);

  return Number.isSafeInteger(sum) && total === sum;
};

const InputTokenUsageFields = Schema.Struct({
  total: Schema.Natural,
  uncached: Schema.Natural,
  cacheRead: Schema.Natural,
  cacheWrite: Schema.Natural,
}).check(
  Schema.makeFilter(
    (usage) => hasAdditiveTotal(usage.total, [usage.uncached, usage.cacheRead, usage.cacheWrite]),
    { title: "Input token total equals uncached, cache-read, and cache-write components" },
  ),
);

/** Provider-reported input-token components for one completed model call. */
export class InputTokenUsage extends Schema.Class<InputTokenUsage>(
  "@effect-agent/core/InputTokenUsage",
)(InputTokenUsageFields) {}

const OutputTokenUsageFields = Schema.Struct({
  total: Schema.Natural,
  text: Schema.Natural,
  reasoning: Schema.Natural,
}).check(
  Schema.makeFilter((usage) => hasAdditiveTotal(usage.total, [usage.text, usage.reasoning]), {
    title: "Output token total equals text and reasoning components",
  }),
);

/** Provider-reported output-token components for one completed model call. */
export class OutputTokenUsage extends Schema.Class<OutputTokenUsage>(
  "@effect-agent/core/OutputTokenUsage",
)(OutputTokenUsageFields) {}

/** Canonical, provider-independent accounting for one completed model call. */
export class ModelCallUsage extends Schema.Class<ModelCallUsage>(
  "@effect-agent/core/ModelCallUsage",
)({
  provider: UsageIdentity,
  /** Configured binding identity. See response.model for provider-reported identity. */
  model: UsageIdentity,
  serviceTier: Schema.optionalKey(UsageIdentity),
  pricingVersion: Schema.optionalKey(UsageIdentity),
  response: Schema.optionalKey(ModelResponseIdentity),
  purpose: Schema.optionalKey(Schema.Literals(["turn", "summary"])),
  usageStatus: Schema.optionalKey(UsageCompleteness),
  pricingStatus: Schema.optionalKey(Schema.Literals(["estimated", "unknown"])),
  inputTokens: InputTokenUsage,
  outputTokens: OutputTokenUsage,
  costMicrousd: Schema.Natural,
}) {}

/** Settlement-sized aggregate for calls sharing one pricing identity. */
export class ModelUsageGroup extends Schema.Class<ModelUsageGroup>(
  "@effect-agent/core/ModelUsageGroup",
)({
  provider: UsageIdentity,
  model: UsageIdentity,
  /** Actual returned model; absent when only the configured binding is known. */
  responseModel: Schema.optionalKey(UsageIdentity),
  serviceTier: Schema.optionalKey(UsageIdentity),
  pricingVersion: Schema.optionalKey(UsageIdentity),
  modelCalls: Schema.Natural.check(Schema.isGreaterThan(0)),
  inputTokens: InputTokenUsage,
  outputTokens: OutputTokenUsage,
  costMicrousd: Schema.Natural,
}) {}

const RunUsageSummaryFields = Schema.Struct({
  modelCalls: Schema.Natural,
  inputTokens: InputTokenUsage,
  outputTokens: OutputTokenUsage,
  costMicrousd: Schema.Natural,
  byModel: Schema.Array(ModelUsageGroup),
  /** Coverage of recorded calls only; interruptions can make the Run less complete. */
  usageStatus: Schema.optionalKey(UsageCompleteness),
  pricingStatus: Schema.optionalKey(UsageCompleteness),
  /** Observed invocations without retained accounting, excluded from numeric call/token totals. */
  unobservedModelCalls: Schema.optionalKey(Schema.Natural),
}).check(
  Schema.makeFilter(
    (summary) => {
      const identities = summary.byModel.map((group) =>
        JSON.stringify([
          group.provider,
          group.model,
          group.responseModel ?? null,
          group.serviceTier ?? null,
          group.pricingVersion ?? null,
        ]),
      );

      return (
        new Set(identities).size === identities.length &&
        hasAdditiveTotal(
          summary.modelCalls,
          summary.byModel.map((group) => group.modelCalls),
        ) &&
        hasAdditiveTotal(
          summary.inputTokens.total,
          summary.byModel.map((group) => group.inputTokens.total),
        ) &&
        hasAdditiveTotal(
          summary.inputTokens.uncached,
          summary.byModel.map((group) => group.inputTokens.uncached),
        ) &&
        hasAdditiveTotal(
          summary.inputTokens.cacheRead,
          summary.byModel.map((group) => group.inputTokens.cacheRead),
        ) &&
        hasAdditiveTotal(
          summary.inputTokens.cacheWrite,
          summary.byModel.map((group) => group.inputTokens.cacheWrite),
        ) &&
        hasAdditiveTotal(
          summary.outputTokens.total,
          summary.byModel.map((group) => group.outputTokens.total),
        ) &&
        hasAdditiveTotal(
          summary.outputTokens.text,
          summary.byModel.map((group) => group.outputTokens.text),
        ) &&
        hasAdditiveTotal(
          summary.outputTokens.reasoning,
          summary.byModel.map((group) => group.outputTokens.reasoning),
        ) &&
        hasAdditiveTotal(
          summary.costMicrousd,
          summary.byModel.map((group) => group.costMicrousd),
        )
      );
    },
    {
      title:
        "Run usage totals equal unique per-model pricing groups within safe-integer accounting",
    },
  ),
);

/** Settlement aggregate included with a terminal Run settlement. */
export class RunUsageSummary extends Schema.Class<RunUsageSummary>(
  "@effect-agent/core/RunUsageSummary",
)(RunUsageSummaryFields) {}

interface MutableUsageGroup {
  readonly provider: string;
  readonly model: string;
  readonly responseModel?: string | undefined;
  readonly serviceTier?: string | undefined;
  readonly pricingVersion?: string | undefined;
  modelCalls: number;
  inputTokens: {
    total: number;
    uncached: number;
    cacheRead: number;
    cacheWrite: number;
  };
  outputTokens: { total: number; text: number; reasoning: number };
  costMicrousd: number;
}

const emptyInputTokens = () => ({ total: 0, uncached: 0, cacheRead: 0, cacheWrite: 0 });
const emptyOutputTokens = () => ({ total: 0, text: 0, reasoning: 0 });

/** Canonical usage could not be aggregated without exceeding safe-integer accounting. */
export class UsageAggregationError extends Schema.TaggedError<UsageAggregationError>()(
  "UsageAggregationError",
  {
    field: Schema.NonEmptyString,
    message: Schema.String,
  },
) {}

const checkedAdd = (
  field: string,
  left: number,
  right: number,
): Effect.Effect<number, UsageAggregationError> => {
  const total = left + right;

  return Number.isSafeInteger(left) &&
    left >= 0 &&
    Number.isSafeInteger(right) &&
    right >= 0 &&
    Number.isSafeInteger(total)
    ? Effect.succeed(total)
    : Effect.fail(
        UsageAggregationError.make({
          field,
          message: `Canonical usage aggregation exceeded the safe-integer range at ${field}`,
        }),
      );
};

/**
 * Deterministically aggregate canonical per-call usage without making cached tokens free.
 * A validated seed retains earlier call totals and pricing groups without retaining those calls.
 * Empty contributions do not change completeness; the seed is never mutated.
 */
export const summarizeModelUsage = Effect.fn("summarizeModelUsage")(function* (
  calls: ReadonlyArray<ModelCallUsage>,
  seed?: RunUsageSummary,
): Effect.fn.Return<RunUsageSummary, UsageAggregationError> {
  const initial =
    seed === undefined
      ? undefined
      : yield* Schema.decodeUnknownEffect(RunUsageSummary)(seed).pipe(
          Effect.mapError(
            () =>
              new UsageAggregationError({
                field: "seed",
                message: "Canonical usage seed does not satisfy the RunUsageSummary Schema",
              }),
          ),
        );

  const inputTokens = initial === undefined ? emptyInputTokens() : { ...initial.inputTokens };
  const outputTokens = initial === undefined ? emptyOutputTokens() : { ...initial.outputTokens };
  const groups = new Map<string, MutableUsageGroup>();
  let modelCalls = initial?.modelCalls ?? 0;
  let costMicrousd = initial?.costMicrousd ?? 0;
  const hasSeedCalls = modelCalls > 0;

  let allUsageUnknown =
    !hasSeedCalls || initial?.usageStatus === undefined || initial.usageStatus === "unknown";

  let allUsageComplete = !hasSeedCalls || initial?.usageStatus === "complete";

  let allPricingUnknown =
    !hasSeedCalls || initial?.pricingStatus === undefined || initial.pricingStatus === "unknown";

  let allPricingComplete = !hasSeedCalls || initial?.pricingStatus === "complete";

  for (const group of initial?.byModel ?? []) {
    const key = JSON.stringify([
      group.provider,
      group.model,
      group.responseModel ?? null,
      group.serviceTier ?? null,
      group.pricingVersion ?? null,
    ]);

    groups.set(key, {
      ...group,
      inputTokens: { ...group.inputTokens },
      outputTokens: { ...group.outputTokens },
    });
  }

  for (const call of calls) {
    allUsageUnknown &&= call.usageStatus === undefined || call.usageStatus === "unknown";
    allUsageComplete &&= call.usageStatus === "complete";
    allPricingUnknown &&= call.pricingStatus !== "estimated";
    allPricingComplete &&= call.pricingStatus === "estimated";
    modelCalls = yield* checkedAdd("modelCalls", modelCalls, 1);
    inputTokens.total = yield* checkedAdd(
      "inputTokens.total",
      inputTokens.total,
      call.inputTokens.total,
    );
    inputTokens.uncached = yield* checkedAdd(
      "inputTokens.uncached",
      inputTokens.uncached,
      call.inputTokens.uncached,
    );
    inputTokens.cacheRead = yield* checkedAdd(
      "inputTokens.cacheRead",
      inputTokens.cacheRead,
      call.inputTokens.cacheRead,
    );
    inputTokens.cacheWrite = yield* checkedAdd(
      "inputTokens.cacheWrite",
      inputTokens.cacheWrite,
      call.inputTokens.cacheWrite,
    );
    outputTokens.total = yield* checkedAdd(
      "outputTokens.total",
      outputTokens.total,
      call.outputTokens.total,
    );
    outputTokens.text = yield* checkedAdd(
      "outputTokens.text",
      outputTokens.text,
      call.outputTokens.text,
    );
    outputTokens.reasoning = yield* checkedAdd(
      "outputTokens.reasoning",
      outputTokens.reasoning,
      call.outputTokens.reasoning,
    );
    costMicrousd = yield* checkedAdd("costMicrousd", costMicrousd, call.costMicrousd);

    const key = JSON.stringify([
      call.provider,
      call.model,
      call.response?.model ?? null,
      call.serviceTier ?? null,
      call.pricingVersion ?? null,
    ]);

    let group = groups.get(key);

    if (group === undefined) {
      group = {
        provider: call.provider,
        model: call.model,
        ...(call.response?.model === undefined ? {} : { responseModel: call.response.model }),
        ...(call.serviceTier === undefined ? {} : { serviceTier: call.serviceTier }),
        ...(call.pricingVersion === undefined ? {} : { pricingVersion: call.pricingVersion }),
        modelCalls: 0,
        inputTokens: emptyInputTokens(),
        outputTokens: emptyOutputTokens(),
        costMicrousd: 0,
      };
      groups.set(key, group);
    }
    group.modelCalls = yield* checkedAdd("byModel.modelCalls", group.modelCalls, 1);
    group.inputTokens.total = yield* checkedAdd(
      "byModel.inputTokens.total",
      group.inputTokens.total,
      call.inputTokens.total,
    );
    group.inputTokens.uncached = yield* checkedAdd(
      "byModel.inputTokens.uncached",
      group.inputTokens.uncached,
      call.inputTokens.uncached,
    );
    group.inputTokens.cacheRead = yield* checkedAdd(
      "byModel.inputTokens.cacheRead",
      group.inputTokens.cacheRead,
      call.inputTokens.cacheRead,
    );
    group.inputTokens.cacheWrite = yield* checkedAdd(
      "byModel.inputTokens.cacheWrite",
      group.inputTokens.cacheWrite,
      call.inputTokens.cacheWrite,
    );
    group.outputTokens.total = yield* checkedAdd(
      "byModel.outputTokens.total",
      group.outputTokens.total,
      call.outputTokens.total,
    );
    group.outputTokens.text = yield* checkedAdd(
      "byModel.outputTokens.text",
      group.outputTokens.text,
      call.outputTokens.text,
    );
    group.outputTokens.reasoning = yield* checkedAdd(
      "byModel.outputTokens.reasoning",
      group.outputTokens.reasoning,
      call.outputTokens.reasoning,
    );
    group.costMicrousd = yield* checkedAdd(
      "byModel.costMicrousd",
      group.costMicrousd,
      call.costMicrousd,
    );
  }

  return RunUsageSummary.make({
    modelCalls,
    inputTokens: InputTokenUsage.make(inputTokens),
    outputTokens: OutputTokenUsage.make(outputTokens),
    costMicrousd,
    usageStatus: allUsageUnknown ? "unknown" : allUsageComplete ? "complete" : "partial",
    pricingStatus: allPricingUnknown ? "unknown" : allPricingComplete ? "complete" : "partial",
    ...(initial?.unobservedModelCalls === undefined
      ? {}
      : { unobservedModelCalls: initial.unobservedModelCalls }),
    byModel: [...groups.values()].map((group) =>
      ModelUsageGroup.make({
        provider: group.provider,
        model: group.model,
        ...(group.responseModel === undefined ? {} : { responseModel: group.responseModel }),
        ...(group.serviceTier === undefined ? {} : { serviceTier: group.serviceTier }),
        ...(group.pricingVersion === undefined ? {} : { pricingVersion: group.pricingVersion }),
        modelCalls: group.modelCalls,
        inputTokens: InputTokenUsage.make(group.inputTokens),
        outputTokens: OutputTokenUsage.make(group.outputTokens),
        costMicrousd: group.costMicrousd,
      }),
    ),
  });
});

