  Schema.isMaxLength(20_000),
  Schema.isPattern(/\S/),
  Schema.makeFilter((text) => Encoding.encodeHex(JSON.stringify(text)).length / 2 <= 32_768, {
    expected: "at most 32768 JSON-encoded UTF-8 bytes",
