import type { Crypto } from "effect";
import { Effect, Schema } from "effect";

import { IntegrityCheck, IntegrityReport, type IntegrityCheckName } from "./Admin.ts";
import { digestCanonicalBatch, EMPTY_TAIL_DIGEST } from "./Digest.ts";
import {
  CanonicalBatch,
  CanonicalRecordEnvelope,
  type BatchId,
  type ProducerId,
  type RecordEnvelope,
} from "./Records.ts";
import {
  submissionInputRecordId,
  submissionSettlementRecordId,
  type SubmissionSnapshot,
} from "./SubmissionLedger.ts";
import type { ThreadCheckpoint, ThreadExport } from "./ThreadStore.ts";

/**
 * The production thread invariant checker, shared by the durable coordinator, admin
 * verification, and development harnesses. Keeping it independent of certification and
 * conformance modules prevents ordinary runtime imports from loading test-only dependencies.
 *
 * `verifyThreadInvariants` — hoisted from the DC eviction harness's `assertConvergence`
 * so the admin `verify` operation, the adapter certification tiers (WP2), and the chaos/soak
 * properties (WP4) all assert one set of claims.
 */

/**
 * Input of one invariant verification, assembled entirely from port reads (or from a captured
 * copy under test):
 *
 * - `export` — the Thread's canonical export (`ThreadStore.export`).
 * - `submissions` — every known Submission row of the lane (ledger scan + lookups). Order is
 *   irrelevant; the checker sorts by `queueSequence`.
 * - `batchProducers` — OPTIONAL per-batch producer identity directory. The digest chain hashes
 *   each batch's Schema-encoded `CanonicalBatch` — including its `producerId`, which the
 *   `ThreadStore` port deliberately does not export — so full chain recomputation needs
 *   this directory (capture it at append time, or from adapter-private storage). Without it the
 *   `digest-chain` and `checkpoint-binding` checks report `skipped` with the honest reason;
 *   adapter-level `verifyOnOpen` remains the storage-side full audit.
 * - `checkpoint` — the stored checkpoint to bind against the recomputed chain, when one exists.
 * - `checkpointsSupported` — whether the caller inspected a supporting adapter. Without this
 *   evidence or a supplied checkpoint, checkpoint verification is skipped.
 * - `requireAllSettled` — convergence mode (certification Tier 2, chaos, soak): additionally
 *   require every known Submission to be settled.
 */
export interface ThreadInvariantInput {
  readonly export: ThreadExport;
  readonly submissions: ReadonlyArray<SubmissionSnapshot>;
  readonly batchProducers?: ReadonlyMap<BatchId, ProducerId> | undefined;
  readonly checkpoint?: ThreadCheckpoint | undefined;
  /** Set only after checking the adapter's optional checkpoint capability. */
  readonly checkpointsSupported?: boolean | undefined;
  readonly requireAllSettled?: boolean | undefined;
}

const encodeEnvelope = Schema.encodeEffect(CanonicalRecordEnvelope);
const decodeEnvelope = Schema.decodeUnknownEffect(CanonicalRecordEnvelope);

const check = (
  name: IntegrityCheckName,
  status: "passed" | "failed" | "skipped",
  detail?: string,
): IntegrityCheck =>
  IntegrityCheck.make({
    name,
    status,
    ...(detail === undefined ? {} : { detail: detail.slice(0, 4_096) }),
  });

interface BatchRun {
  readonly batchId: BatchId;
  readonly records: Array<RecordEnvelope>;
  readonly lastSequence: number;
}

/** Group the export's records into their atomic append runs (batches append contiguously). */
const batchRunsOf = (records: ReadonlyArray<CanonicalRecordEnvelope>): Array<BatchRun> => {
  const runs: Array<BatchRun> = [];

  for (const envelope of records) {
    const current = runs.at(-1);

    if (current !== undefined && current.batchId === envelope.batchId) {
      current.records.push(envelope.record);
      runs[runs.length - 1] = { ...current, lastSequence: envelope.sequence };
      continue;
    }
    runs.push({
      batchId: envelope.batchId,
      records: [envelope.record],
      lastSequence: envelope.sequence,
    });
  }

  return runs;
};

/**
 * The shared thread invariant checker (plan §1/§3): the DC harness `assertConvergence`
 * claims, verbatim, as typed per-check results over a canonical export plus the lane's ledger
 * rows — read-only, never a repair:
 *
 * 1. `schema-round-trip` — every envelope re-encodes and re-decodes through its canonical
 *    Schema (a corrupted copy fails typed instead of decoding incorrectly).
 * 2. `record-identity` — no canonical record identity appears twice (DUR-007 dedupe held).
 * 3. `sequence-contiguity` — gap-free sequences from 1 through the exported tail.
 * 4. `digest-chain` — the tail digest recomputes from `EMPTY_TAIL_DIGEST` through every batch
 *    (requires the per-batch producer directory; skipped honestly otherwise).
 * 5. `fifo-input-order` / `fifo-settlement-order` — canonical input and settlement records
 *    follow the admitted queue order (DUR-004). Aborted settlements of never-run work (no
 *    canonical `input:{sid}` record) are exempt from the settlement comparison: P7 §7(c)
 *    settles them immediately without waiting for the head, and DUR-004 bounds execution
 *    order, which never-run work has none of.
 * 6. `terminal-uniqueness` — at most one canonical terminal record per Submission, exactly one
 *    for every settled ledger row (DUR-002).
 * 7. `ledger-canonical-agreement` — a settled ledger row has a canonical settlement record and
 *    the outcomes agree; canonical history remains the authority (DUR-015).
 * 8. `checkpoint-binding` — a stored checkpoint's digest matches the recomputed chain at its
 *    sequence (needs the chain; bounds are checked regardless).
 * 9. `all-settled` — convergence mode only: every known Submission settled.
 *
 * Requires only `Crypto.Crypto` (digest recomputation); it performs no port access, so the
 * admin operation, certification runners, and chaos properties feed it whatever copies they
 * hold.
 */
export const verifyThreadInvariants = Effect.fn("Thread.verifyThreadInvariants")(function* (
  input: ThreadInvariantInput,
): Effect.fn.Return<IntegrityReport, never, Crypto.Crypto> {
  const exported = input.export;
  const records = exported.records;
  const checks: Array<IntegrityCheck> = [];

  // 1. schema-round-trip
  {
    let failure: string | undefined;

    for (const envelope of records) {
      const roundTrip = yield* encodeEnvelope(envelope).pipe(
        Effect.flatMap(decodeEnvelope),
        Effect.exit,
      );

      if (roundTrip._tag === "Failure") {
        failure = `record ${envelope.record.recordId} does not round-trip its Schema`;
        break;
      }
    }
    checks.push(
      failure === undefined
        ? check("schema-round-trip", "passed")
        : check("schema-round-trip", "failed", failure),
    );
  }

  // 2. record-identity
  {
    const seen = new Set<string>();
    const duplicates = new Set<string>();

    for (const envelope of records) {
      if (seen.has(envelope.record.recordId)) duplicates.add(envelope.record.recordId);
      seen.add(envelope.record.recordId);
    }
    checks.push(
      duplicates.size === 0
        ? check("record-identity", "passed")
        : check(
            "record-identity",
            "failed",
            `duplicated canonical record identities: ${[...duplicates].join(", ")}`,
          ),
    );
  }

  // 3. sequence-contiguity
  {
    let contiguityFailure: string | undefined;

    for (const [index, envelope] of records.entries()) {
      if (envelope.sequence !== index + 1) {
        contiguityFailure = `sequence ${envelope.sequence} at position ${index} (expected ${index + 1})`;
        break;
      }
    }
    if (contiguityFailure === undefined && records.length !== exported.tailSequence) {
      contiguityFailure = `exported tail sequence ${exported.tailSequence} disagrees with ${records.length} records`;
    }
    checks.push(
      contiguityFailure === undefined
        ? check("sequence-contiguity", "passed")
        : check("sequence-contiguity", "failed", contiguityFailure),
    );
  }

  // 4. digest-chain (+ collect per-sequence chain digests for checkpoint binding)
  const chainDigestAtSequence = new Map<number, string>();

  if (input.batchProducers === undefined) {
    checks.push(
      check(
        "digest-chain",
        "skipped",
        "the ThreadStore port does not export per-batch producer identity; supply batchProducers (captured at append time) to recompute the chain — adapter-level verifyOnOpen performs the storage-side audit",
      ),
    );
  } else {
    let chain = EMPTY_TAIL_DIGEST;
    let chainFailure: string | undefined;

    for (const run of batchRunsOf(records)) {
      const producerId = input.batchProducers.get(run.batchId);

      if (producerId === undefined) {
        chainFailure = `no producer identity supplied for batch ${run.batchId}`;
        break;
      }
      const [first, ...rest] = run.records;

      if (first === undefined) {
        chainFailure = `batch ${run.batchId} grouped zero records`;
        break;
      }

      const digest = yield* digestCanonicalBatch(
        chain,
        CanonicalBatch.make({ batchId: run.batchId, producerId, records: [first, ...rest] }),
      ).pipe(Effect.exit);

      if (digest._tag === "Failure") {
        chainFailure = `batch ${run.batchId} could not be re-digested`;
        break;
      }
      chain = digest.value;
      chainDigestAtSequence.set(run.lastSequence, chain);
    }
    if (chainFailure === undefined && chain !== exported.tailDigest) {
      chainFailure = `recomputed tail digest ${chain} disagrees with exported tail digest ${exported.tailDigest}`;
    }
    checks.push(
      chainFailure === undefined
        ? check("digest-chain", "passed")
        : check("digest-chain", "failed", chainFailure),
    );
  }

  // Shared FIFO/terminal machinery
  const ordered = [...input.submissions].sort(
    (left, right) => left.queueSequence - right.queueSequence,
  );

  const recordIds = records.map((envelope) => envelope.record.recordId);

  // 5a. fifo-input-order
  {
    const expectedInputs = ordered.map((row) => submissionInputRecordId(row.submissionId));
    const expectedSet = new Set<string>(expectedInputs);
    const inputOrder = recordIds.filter((recordId) => expectedSet.has(recordId));
    const presentInputs = new Set(inputOrder);
    const expectedPresent = expectedInputs.filter((expected) => presentInputs.has(expected));

    const matches =
      inputOrder.length === expectedPresent.length &&
      inputOrder.every((recordId, index) => recordId === expectedPresent[index]);

    checks.push(
      matches
        ? check("fifo-input-order", "passed")
        : check(
            "fifo-input-order",
            "failed",
            `canonical input order [${inputOrder.join(", ")}] violates queue order`,
          ),
    );
  }

  // 5b. fifo-settlement-order — P7 §7(c) exemption: an ABORTED settlement for never-run work
  // (no canonical `input:{sid}` record) settles immediately by design, without waiting to
  // head the lane, so it is excluded from the FIFO comparison. DUR-004 bounds EXECUTION
  // order; the exempted rows provably never executed.
  {
    const recordIdSet = new Set<string>(recordIds);
    const abortedNeverRun = new Set<string>();

    for (const envelope of records) {
      const payload = envelope.record.payload;

      if (
        payload._tag === "SubmissionSettled" &&
        payload.outcome === "aborted" &&
        !recordIdSet.has(submissionInputRecordId(payload.submissionId))
      ) {
        abortedNeverRun.add(payload.submissionId);
      }
    }

    const expectedSettlements = ordered
      .filter((row) => !abortedNeverRun.has(row.submissionId))
      .map((row) => submissionSettlementRecordId(row.submissionId));

    const expectedSet = new Set<string>(expectedSettlements);
    const settlementOrder = recordIds.filter((recordId) => expectedSet.has(recordId));

    const presentSettlements = new Set(settlementOrder);

    const expectedPresent = expectedSettlements.filter((expected) =>
      presentSettlements.has(expected),
    );

    const matches =
      settlementOrder.length === expectedPresent.length &&
      settlementOrder.every((recordId, index) => recordId === expectedPresent[index]);

    checks.push(
      matches
        ? check("fifo-settlement-order", "passed")
        : check(
            "fifo-settlement-order",
            "failed",
            `canonical settlement order [${settlementOrder.join(", ")}] violates queue order`,
          ),
    );
  }

  // 6 + 7. terminal-uniqueness and ledger-canonical-agreement
  {
    const settlementsBySubmission = new Map<string, Array<CanonicalRecordEnvelope>>();

    for (const envelope of records) {
      if (envelope.record.payload._tag !== "SubmissionSettled") continue;
      const submissionId = envelope.record.payload.submissionId;
      const existing = settlementsBySubmission.get(submissionId) ?? [];

      existing.push(envelope);
      settlementsBySubmission.set(submissionId, existing);
    }
    let uniquenessFailure: string | undefined;
    let agreementFailure: string | undefined;

    for (const [submissionId, settlements] of settlementsBySubmission) {
      if (settlements.length > 1) {
        uniquenessFailure = `submission ${submissionId} has ${settlements.length} canonical terminal records`;
      }
    }
    for (const row of ordered) {
      const settlements = settlementsBySubmission.get(row.submissionId) ?? [];
      const canonical = settlements[0]?.record.payload;

      if (row.state === "settled") {
        if (settlements.length !== 1) {
          uniquenessFailure ??= `settled submission ${row.submissionId} has ${settlements.length} canonical terminal records (expected exactly 1)`;
        }
        if (
          canonical !== undefined &&
          canonical._tag === "SubmissionSettled" &&
          row.settledOutcome !== undefined &&
          canonical.outcome !== row.settledOutcome
        ) {
          agreementFailure = `submission ${row.submissionId}: ledger outcome ${row.settledOutcome} disagrees with canonical outcome ${canonical.outcome}`;
        }
        if (settlements.length === 0) {
          agreementFailure ??= `settled submission ${row.submissionId} has no canonical settlement record (DUR-015: history is the authority)`;
        }
      }
    }
    checks.push(
      uniquenessFailure === undefined
        ? check("terminal-uniqueness", "passed")
        : check("terminal-uniqueness", "failed", uniquenessFailure),
    );
    checks.push(
      agreementFailure === undefined
        ? check("ledger-canonical-agreement", "passed")
        : check("ledger-canonical-agreement", "failed", agreementFailure),
    );
  }

  // 8. checkpoint-binding
  if (input.checkpoint === undefined && input.checkpointsSupported !== true) {
    checks.push(check("checkpoint-binding", "skipped", "checkpoint support was not supplied"));
  } else if (input.checkpoint === undefined) {
    checks.push(check("checkpoint-binding", "passed", "no stored checkpoint"));
  } else if (input.checkpoint.throughSequence > exported.tailSequence) {
    checks.push(
      check(
        "checkpoint-binding",
        "failed",
        `checkpoint through-sequence ${input.checkpoint.throughSequence} is ahead of the tail ${exported.tailSequence}`,
      ),
    );
  } else if (input.batchProducers === undefined) {
    checks.push(
      check(
        "checkpoint-binding",
        "skipped",
        "digest binding needs the recomputed chain; supply batchProducers (the adapter rejects mismatched checkpoints on save/load regardless)",
      ),
    );
  } else {
    const bound = chainDigestAtSequence.get(input.checkpoint.throughSequence);

    checks.push(
      bound === input.checkpoint.tailDigest
        ? check("checkpoint-binding", "passed")
        : check(
            "checkpoint-binding",
            "failed",
            `checkpoint digest ${input.checkpoint.tailDigest} does not match the recomputed chain at sequence ${input.checkpoint.throughSequence}`,
          ),
    );
  }

  // 9. all-settled (convergence mode)
  if (input.requireAllSettled === true) {
    const nonterminal = ordered.filter((row) => row.state !== "settled");

    checks.push(
      nonterminal.length === 0 && ordered.length > 0
        ? check("all-settled", "passed")
        : check(
            "all-settled",
            "failed",
            ordered.length === 0
              ? "no Submissions are known to the lane"
              : `nonterminal submissions: ${nonterminal
                  .map((row) => `${row.submissionId}(${row.state})`)
                  .join(", ")}`,
          ),
    );
  }

  return IntegrityReport.make({
    threadId: exported.threadId,
    tailSequence: exported.tailSequence,
    recordCount: records.length,
    submissionCount: ordered.length,
    checks,
    ok: checks.every((result) => result.status !== "failed"),
  });
});

import { ThreadId } from "@effect-agent/core/Identifiers";
import type { Effect, Option, Stream } from "effect";
import { Context, Schema } from "effect";

import {
  BatchId,
  CanonicalBatch,
  CanonicalRecordEnvelope,
  CanonicalSequence,
  Digest,
  ObservationOffset,
  PersistedJson,
  ProducerEpoch,
} from "./Records.ts";

export class ThreadMaterialization extends Schema.Class<ThreadMaterialization>(
  "@effect-agent/thread/ThreadMaterialization",
)({
  threadId: ThreadId,
  producerEpoch: ProducerEpoch,
}) {}

export class FencedAppendRequest extends Schema.Class<FencedAppendRequest>(
  "@effect-agent/thread/FencedAppendRequest",
)({
  threadId: ThreadId,
  batch: CanonicalBatch,
  expectedTailSequence: CanonicalSequence,
  expectedTailDigest: Digest,
  producerEpoch: ProducerEpoch,
}) {}

export class AppendResult extends Schema.Class<AppendResult>("@effect-agent/thread/AppendResult")({
  firstSequence: CanonicalSequence,
  lastSequence: CanonicalSequence,
  tailDigest: Digest,
  replayed: Schema.Boolean,
}) {}

export class ThreadRead extends Schema.Class<ThreadRead>("@effect-agent/thread/ThreadRead")({
  threadId: ThreadId,
  afterSequence: Schema.optionalKey(CanonicalSequence),
  limit: Schema.Natural.check(Schema.isGreaterThan(0), Schema.isLessThanOrEqualTo(1_024)),
}) {}

export class ThreadObservation extends Schema.Class<ThreadObservation>(
  "@effect-agent/thread/ThreadObservation",
)({
  threadId: ThreadId,
  afterOffset: Schema.optionalKey(ObservationOffset),
}) {}

export class ThreadExportRequest extends Schema.Class<ThreadExportRequest>(
  "@effect-agent/thread/ThreadExportRequest",
)({
  threadId: ThreadId,
}) {}

export class ThreadTailRequest extends Schema.Class<ThreadTailRequest>(
  "@effect-agent/thread/ThreadTailRequest",
)({
  threadId: ThreadId,
}) {}

/**
 * The committed tail of one Thread Log. A resuming producer composes its next
 * FencedAppendRequest from this value instead of exporting the whole log.
 */
export class ThreadTail extends Schema.Class<ThreadTail>("@effect-agent/thread/ThreadTail")({
  threadId: ThreadId,
  tailSequence: CanonicalSequence,
  tailDigest: Digest,
  producerEpoch: ProducerEpoch,
}) {}

/** Maximum canonical records represented by one Thread export. */
export const MAX_THREAD_EXPORT_RECORDS = 131_072;

export class ThreadExport extends Schema.Class<ThreadExport>("@effect-agent/thread/ThreadExport")({
  format: Schema.Literal("effect-agent/thread@1"),
  threadId: ThreadId,
  tailSequence: CanonicalSequence,
  tailDigest: Digest,
  records: Schema.Array(CanonicalRecordEnvelope).check(
    Schema.isMaxLength(MAX_THREAD_EXPORT_RECORDS),
  ),
}) {}

/**
 * A disposable projection snapshot. Adapters bind its sequence and digest to the canonical
 * log; consumers decode `state` and decide projection compatibility before suffix replay.
 * Legacy metadata is optional for application projections and preserved when supplied.
 * Runtime-owned recovery checkpoints populate and compare it before using cached state.
 */
export class ThreadCheckpoint extends Schema.Class<ThreadCheckpoint>(
  "@effect-agent/thread/ThreadCheckpoint",
)({
  schemaVersion: Schema.Literal(1),
  threadId: ThreadId,
  throughSequence: CanonicalSequence,
  tailDigest: Digest,
  /** @deprecated For application projections; retained for existing data and runtime recovery. */
  engineVersion: Schema.optionalKey(Schema.NonEmptyString),
  /** @deprecated For application projections; retained for existing data and runtime recovery. */
  agentDefinitionDigest: Schema.optionalKey(Digest),
  /** @deprecated For application projections; retained for existing data and runtime recovery. */
  modelDigest: Schema.optionalKey(Digest),
  /** @deprecated For application projections; retained for existing data and runtime recovery. */
  toolDigest: Schema.optionalKey(Digest),
  state: PersistedJson,
  createdAt: Schema.DateTimeUtcFromString,
}) {}

export class SaveCheckpointRequest extends Schema.Class<SaveCheckpointRequest>(
  "@effect-agent/thread/SaveCheckpointRequest",
)({
  checkpoint: ThreadCheckpoint,
}) {}

/** Replace the disposable recovery view only under the current canonical producer fence. */
export class SaveRecoveryCheckpointRequest extends Schema.Class<SaveRecoveryCheckpointRequest>(
  "@effect-agent/thread/SaveRecoveryCheckpointRequest",
)({
  checkpoint: ThreadCheckpoint,
  producerEpoch: ProducerEpoch,
}) {}

export class LoadCheckpointRequest extends Schema.Class<LoadCheckpointRequest>(
  "@effect-agent/thread/LoadCheckpointRequest",
)({
  threadId: ThreadId,
  atOrBeforeSequence: Schema.optionalKey(CanonicalSequence),
}) {}

export class ThreadStoreError extends Schema.TaggedError<ThreadStoreError>()("ThreadStoreError", {
  operation: Schema.String,
  message: Schema.String,
  cause: Schema.optionalKey(Schema.Defect()),
}) {}

export class ThreadNotMaterialized extends Schema.TaggedError<ThreadNotMaterialized>()(
  "ThreadNotMaterialized",
  { threadId: ThreadId },
) {}

/**
 * A canonical append that cannot commit: `batch-digest` replays a batch ID with different
 * content, `record-identity` reuses a canonical record ID, and `tail` declares a stale expected
 * tail. Tail conflicts carry the actual committed tail as a diagnostic resume hint.
 */
export class AppendConflict extends Schema.TaggedError<AppendConflict>()("AppendConflict", {
  threadId: ThreadId,
  batchId: BatchId,
  reason: Schema.Literals(["batch-digest", "record-identity", "tail"]),
  actualTailSequence: Schema.optionalKey(CanonicalSequence),
  actualTailDigest: Schema.optionalKey(Digest),
}) {}

export class FenceRejected extends Schema.TaggedError<FenceRejected>()("FenceRejected", {
  threadId: ThreadId,
  actualEpoch: ProducerEpoch,
  attemptedEpoch: ProducerEpoch,
}) {}

export class CheckpointRejected extends Schema.TaggedError<CheckpointRejected>()(
  "CheckpointRejected",
  {
    threadId: ThreadId,
    reason: Schema.Literals(["ahead-of-tail", "digest-mismatch", "unsupported-version", "corrupt"]),
  },
) {}

export type ThreadStoreFailure =
  | ThreadStoreError
  | ThreadNotMaterialized
  | AppendConflict
  | FenceRejected;

/**
 * Optional, disposable projection storage. Neither history execution nor durable recovery
 * requires it. Adapters that offer it must bind every checkpoint to a canonical batch tail.
 * Application consumers own projection compatibility; this port does not interpret metadata.
 */
export interface ThreadCheckpoints {
  readonly save: (
    request: SaveCheckpointRequest,
  ) => Effect.Effect<void, ThreadStoreError | ThreadNotMaterialized | CheckpointRejected>;
  readonly load: (
    request: LoadCheckpointRequest,
  ) => Effect.Effect<
    Option.Option<ThreadCheckpoint>,
    ThreadStoreError | ThreadNotMaterialized | CheckpointRejected
  >;
}

/**
 * Optional latest-only recovery cache, independent of application projection checkpoints.
 * Saves atomically validate the producer epoch and canonical batch tail. An older snapshot
 * cannot replace a newer one; equal-tail replacement repairs disposable state. Invalid cached
 * data fails with CheckpointRejected, while infrastructure failures remain ThreadStoreError.
 * Loading at an earlier tail or outside the adapter's cache locality may return none so callers
 * can replay canonical records. Canonical records and the ledger remain authority.
 */
export interface ThreadRecoveryCheckpoints {
  readonly save: (
    request: SaveRecoveryCheckpointRequest,
  ) => Effect.Effect<
    void,
    ThreadStoreError | ThreadNotMaterialized | CheckpointRejected | FenceRejected
  >;
  readonly load: ThreadCheckpoints["load"];
}

export class ThreadStore extends Context.Service<
  ThreadStore,
  {
    readonly materialize: (
      request: ThreadMaterialization,
    ) => Effect.Effect<void, ThreadStoreError | FenceRejected>;
    readonly append: (
      request: FencedAppendRequest,
    ) => Effect.Effect<
      AppendResult,
      ThreadStoreError | ThreadNotMaterialized | AppendConflict | FenceRejected
    >;
    readonly read: (
      request: ThreadRead,
    ) => Stream.Stream<CanonicalRecordEnvelope, ThreadStoreError | ThreadNotMaterialized>;
    readonly observe: (
      request: ThreadObservation,
    ) => Stream.Stream<CanonicalRecordEnvelope, ThreadStoreError | ThreadNotMaterialized>;
    readonly export: (
      request: ThreadExportRequest,
    ) => Effect.Effect<ThreadExport, ThreadStoreError | ThreadNotMaterialized>;
    readonly inspectTail: (
      request: ThreadTailRequest,
    ) => Effect.Effect<ThreadTail, ThreadStoreError | ThreadNotMaterialized>;
    /** Absent when this adapter does not support disposable checkpoints. */
    readonly checkpoints?: ThreadCheckpoints | undefined;
    readonly recoveryCheckpoints?: ThreadRecoveryCheckpoints | undefined;
  }
>()("@effect-agent/thread/ThreadStore") {}

import { ThreadId, RunId, SubmissionId, ToolCallId } from "@effect-agent/core/Identifiers";
import { Context, Effect, Layer, Schema } from "effect";

import { Digest, PersistedJson, ToolCallPrepared } from "./Records.ts";

/**
 * Everything a reconciliation policy can consult about one prepared-but-unsettled ordinary Tool
 * Call (durability §10): deterministic identities for supplier-side lookup plus the exact
 * Schema-encoded parameters and their digest. Built from the canonical `ToolCallPrepared` record
 * and the owning Submission's identities — never from in-memory Attempt state.
 */
export class PreparedToolCallEvidence extends Schema.Class<PreparedToolCallEvidence>(
  "@effect-agent/thread/PreparedToolCallEvidence",
)({
  threadId: ThreadId,
  submissionId: SubmissionId,
  runId: RunId,
  turn: ToolCallPrepared.fields.turn,
  toolCallId: ToolCallId,
  toolName: ToolCallPrepared.fields.toolName,
  parameters: PersistedJson,
  parametersDigest: Digest,
}) {}

/** Proof that the external execution never started: the call may re-execute on resume. */
export class ReconciliationNeverStarted extends Schema.TaggedClass<ReconciliationNeverStarted>(
  "@effect-agent/thread/ReconciliationNeverStarted",
)("NeverStarted", {}) {}

/**
 * Proof that the external execution completed: `result` is the recovered supplier truth, which
 * becomes canonical (`ToolCallSettled` + `ToolCallResolved`) WITHOUT executing anything.
 */
export class ReconciliationCompleted extends Schema.TaggedClass<ReconciliationCompleted>(
  "@effect-agent/thread/ReconciliationCompleted",
)("CompletedWithResult", {
  result: PersistedJson,
  isFailure: Schema.Boolean,
}) {}

/** The call is safe to repeat under a stable external idempotency contract. */
export class ReconciliationSafeToRetry extends Schema.TaggedClass<ReconciliationSafeToRetry>(
  "@effect-agent/thread/ReconciliationSafeToRetry",
)("SafeToRetry", {}) {}

/** No proof either way: the outcome is Unknown and requires authorized resolution (DUR-017). */
export class ReconciliationUncertain extends Schema.TaggedClass<ReconciliationUncertain>(
  "@effect-agent/thread/ReconciliationUncertain",
)("Uncertain", {
  reason: Schema.String,
}) {}

/**
 * What a reconciliation policy can prove about one prepared-but-unsettled ordinary Tool Call
 * (durability §10): execution never started, execution completed with a recoverable result,
 * execution is safe to repeat, or nothing — in which case the Run enters Unknown. The engine
 * never manufactures an error result and continues.
 */
export const ReconciliationDecision = Schema.Union([
  ReconciliationNeverStarted,
  ReconciliationCompleted,
  ReconciliationSafeToRetry,
  ReconciliationUncertain,
]);

export type ReconciliationDecision = typeof ReconciliationDecision.Type;

/** The reconciliation policy itself failed (supplier unreachable, corrupt lookup, ...). The
 * caller treats this as no proof: the call stays open and the pass may retry. */
export class ToolReconcilerError extends Schema.TaggedError<ToolReconcilerError>()(
  "ToolReconcilerError",
  {
    toolCallId: ToolCallId,
    message: Schema.String,
    cause: Schema.optionalKey(Schema.Defect()),
  },
) {}

/**
 * Application-registered reconciliation policy consulted by recovery for every open ordinary
 * Tool Call before an Unknown Outcome is recorded (durability §10, DUR-009). A decision is a
 * claim about EXTERNAL truth — typically an idempotency-keyed supplier lookup — never a guess
 * from canonical state alone.
 *
 * `ToolReconciler.uncertain` is the fail-closed default (AGENTS rule 11): with no registered
 * policy, every open call stays Unknown and routes to the authorized DUR-017 resolution path.
 */
export class ToolReconciler extends Context.Service<
  ToolReconciler,
  {
    readonly reconcile: (
      evidence: PreparedToolCallEvidence,
    ) => Effect.Effect<ReconciliationDecision, ToolReconcilerError>;
  }
>()("@effect-agent/thread/ToolReconciler") {
  /** Fail-closed default: no proof is ever asserted, every open call stays Unknown. */
  static readonly uncertain: Layer.Layer<ToolReconciler> = Layer.succeed(this)({
    reconcile: () =>
      Effect.succeed(
        ReconciliationUncertain.make({
          reason: "No reconciliation policy is registered; the outcome stays unknown",
        }),
      ),
  });
}

import { type ThreadId } from "@effect-agent/core/Identifiers";
import type { Scope } from "effect";
import { Context, Deferred, Effect, Layer, Ref, Stream } from "effect";

/**
 * Incarnation-local, thread-keyed wake registrations. A registration is installed before
 * its returned Effect can be awaited, which lets a caller subscribe, check durable authority,
 * and then park without a lost-wakeup window.
 */
export interface WakeSubscriptionHub {
  /** Register one Scope-owned waiter and return its one-shot wake Effect. */
  readonly subscribe: (
    threadId: ThreadId,
  ) => Effect.Effect<Effect.Effect<void>, never, Scope.Scope>;
  /** Wake every currently registered waiter for exactly this Thread. */
  readonly notify: (threadId: ThreadId) => Effect.Effect<void>;
}

interface WakeRegistration {
  readonly id: number;
  readonly deferred: Deferred.Deferred<void>;
}

type WakeRegistrations = ReadonlyMap<ThreadId, ReadonlyMap<number, Deferred.Deferred<void>>>;

/**
 * Build the shared per-incarnation registration primitive used by host WakeSchedulers. The hub
 * contains hints only: eviction may discard it, while a reconnecting caller re-subscribes and
 * rechecks canonical storage. Scope finalizers remove cancelled waiters, and notify broadcasts
 * instead of consuming a signal that belongs to another waiter.
 */
export const makeWakeSubscriptionHub: Effect.Effect<WakeSubscriptionHub> = Effect.gen(function* () {
  const registrations = yield* Ref.make<WakeRegistrations>(new Map());
  const nextId = yield* Ref.make(0);

  const remove = (threadId: ThreadId, id: number) =>
    Ref.update(registrations, (current) => {
      const existing = current.get(threadId);

      if (existing === undefined || !existing.has(id)) return current;
      const next = new Map(current);
      const thread = new Map(existing);

      thread.delete(id);
      if (thread.size === 0) {
        next.delete(threadId);
      } else {
        next.set(threadId, thread);
      }

      return next;
    });

  const subscribe = Effect.fn("WakeSubscriptionHub.subscribe")(
    (threadId: ThreadId): Effect.Effect<Effect.Effect<void>, never, Scope.Scope> =>
      Effect.gen(function* () {
        const deferred = yield* Deferred.make<void>();
        const id = yield* Ref.getAndUpdate(nextId, (current) => current + 1);
        const registration: WakeRegistration = { id, deferred };

        yield* Effect.addFinalizer(() => remove(threadId, registration.id));
        yield* Ref.update(registrations, (current) => {
          const next = new Map(current);
          const thread = new Map(current.get(threadId) ?? []);

          thread.set(registration.id, registration.deferred);
          next.set(threadId, thread);

          return next;
        });

        return registration.deferred;
      }).pipe(Effect.map((deferred) => Deferred.await(deferred))),
  );

  const notify = Effect.fn("WakeSubscriptionHub.notify")(function* (threadId: ThreadId) {
    const waiters = yield* Ref.modify(registrations, (current) => {
      const thread = current.get(threadId);

      if (thread === undefined) return [[], current] as const;
      const next = new Map(current);

      next.delete(threadId);

      return [[...thread.values()], next] as const;
    });

    yield* Effect.forEach(waiters, (waiter) => Deferred.succeed(waiter, undefined), {
      discard: true,
    });
  });

  return { subscribe, notify };
});

/**
 * Liveness hint channel for durable schedulers. `notify` announces that a Thread lane may
 * have claimable, canonical, or settled work; `wakes` is the all-lanes subscription surface for
 * workers, while `subscribe` installs an efficient one-Thread wait registration.
 *
 * Correctness must NEVER depend on delivery: notifications may be dropped, coalesced, duplicated,
 * or observed by no subscriber (a notify before any subscription is simply lost). Every consumer
 * must pair a wake with durable authority: workers use periodic SubmissionLedger scans, while a
 * public progress waiter subscribes before its canonical read and reconnects/rechecks after an
 * incarnation loss (persistence §14).
 *
 * Each run of `wakes` creates its own subscription whose resources live in that run's Scope and
 * are released when the consuming stream ends or is interrupted. Implementations must not spawn
 * daemon fibers.
 */
export class WakeScheduler extends Context.Service<
  WakeScheduler,
  {
    /** Best-effort hint that `threadId` may have claimable or settled work. Never fails. */
    readonly notify: (threadId: ThreadId) => Effect.Effect<void>;
    /** Scope-owned one-shot registration for exactly one Thread. */
    readonly subscribe: (
      threadId: ThreadId,
    ) => Effect.Effect<Effect.Effect<void>, never, Scope.Scope>;
    /** Scope-owned subscription to wake hints, starting at subscription time. */
    readonly wakes: Stream.Stream<ThreadId>;
  }
>()("@effect-agent/thread/WakeScheduler") {
  /**
   * Discards every notification and never wakes anyone. Valid because WakeScheduler is only a
   * liveness hint: consumers relying on ledger scans stay correct, merely slower.
   */
  static readonly layerNoop: Layer.Layer<WakeScheduler> = Layer.succeed(WakeScheduler, {
    notify: () => Effect.void,
    subscribe: () => Effect.succeed(Effect.never),
    wakes: Stream.never,
  });
}

import type * as Agent from "@effect-agent/core/Agent";
import type { AgentPolicy } from "@effect-agent/core/AgentPolicy";
import type { SubmissionId, ThreadId } from "@effect-agent/core/Identifiers";
import type { SubagentBudgetReservation } from "@effect-agent/core/SubagentContract";
import { WorkerError, type WorkerRef, type WorkerSource } from "@effect-agent/core/Worker";
import { Context, Effect, Option, Schema } from "effect";

import type { DefinitionDigests, Digest, PersistedJson, WorkerOrigin } from "./Records.ts";
import type { Principal, SubmissionSnapshot } from "./SubmissionLedger.ts";

/** Host-verified source input; absence never means the latest input in the Thread. */
export interface WorkerPolicySource {
  readonly threadId: ThreadId;
  readonly definition: Agent.AnyDefinition;
  readonly definitions: DefinitionDigests;
  readonly submission?: SubmissionSnapshot;
}

/** Initial input is validated again at destination admission, including idempotent replay. */
export type WorkerPolicyTarget = {
  readonly definition: Agent.AnyDefinition;
  readonly definitions: DefinitionDigests;
  readonly source: WorkerSource;
} & (
  | {
      readonly _tag: "InitialInput";
      readonly sourceSubmission?: SubmissionSnapshot;
      readonly input: PersistedJson;
      readonly inputDigest: Digest;
    }
  | {
      readonly _tag: "RetainedWorker";
      /** Verified against canonical source history before this request reaches the resolver. */
      readonly origin: WorkerOrigin;
    }
);

/**
 * Opt-in host authority for policies captured in immutable application input. None preserves
 * the registered Definition's existing policy/override semantics. Some is a complete policy,
 * never merged with static overrides. Decode and authorize the exact captured revision; do not
 * read mutable settings or substitute a current capture for missing historical authority.
 * RetainedWorker may affirm only origin.policy, never replace a continuing worker's allowance.
 * Return WorkerError(unavailable) for temporarily unavailable authority so delivery can retry.
 * Implementations are acquired through Effect Layers; capture their dependencies in Layer R.
 */
export const WorkerPolicyResolver = Context.Reference<{
  readonly resolveSource: (
    request: WorkerPolicySource,
  ) => Effect.Effect<Option.Option<AgentPolicy>, WorkerError>;
  readonly resolveTarget: (
    request: WorkerPolicyTarget,
  ) => Effect.Effect<Option.Option<AgentPolicy>, WorkerError>;
}>("@effect-agent/thread/WorkerPolicyResolver", {
  defaultValue: () => ({
    resolveSource: () => Effect.succeed(Option.none()),
    resolveTarget: () => Effect.succeed(Option.none()),
  }),
});

const Positive = Schema.Int.check(Schema.isGreaterThan(0));

/** A host-authorized ceiling on active background workers, not retained workers or Run usage. */
export const WorkerConcurrencyLimit = Schema.Struct({
  maxActiveWorkersPerSource: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
});

export type WorkerConcurrencyLimit = typeof WorkerConcurrencyLimit.Type;

/**
 * Optional source-aware operational authority. Resolution occurs inside every new source
 * reservation attempt, against the same canonical history used for the append CAS. None
 * preserves WorkerHostConfig; Some can only narrow it. The selected submission is exact,
 * never the latest input. Implementations must authorize that immutable capture and retain
 * construction dependencies in Layer R. Unavailable authority must return WorkerError(unavailable).
 *
 * One worker occupies a slot while any of its inputs remain unacknowledged. Steering an active
 * worker does not acquire another slot. Decreases (including zero) do not cancel incumbents;
 * an idle worker needs a slot again. Idempotent retained reservations do not reacquire slots.
 */
export const WorkerConcurrencyResolver = Context.Reference<{
  readonly resolve: (request: {
    readonly source: WorkerSource;
    readonly sourceSubmission?: SubmissionSnapshot;
    readonly worker: WorkerRef;
    readonly principal: Principal;
  }) => Effect.Effect<Option.Option<WorkerConcurrencyLimit>, WorkerError>;
}>("@effect-agent/thread/WorkerConcurrencyResolver", {
  defaultValue: () => ({ resolve: () => Effect.succeed(Option.none()) }),
});

/** Host ceilings apply across all declarations owned by one source Thread. */
export const WorkerHostLimits = Schema.Struct({
  maxWorkersPerSource: Positive.check(Schema.isLessThanOrEqualTo(100)),
  /** Active background workers across declarations; omission retains source Tool concurrency. */
  maxActiveWorkersPerSource: Schema.optionalKey(Positive.check(Schema.isLessThanOrEqualTo(100))),
  maxInputsPerWorker: Positive.check(Schema.isLessThanOrEqualTo(1_000)),
  maxPendingInputsPerWorker: Positive.check(Schema.isLessThanOrEqualTo(100)),
  lifetimeMillis: Positive.check(Schema.isLessThanOrEqualTo(604_800_000)),
  /** Preparation may repeat after loss before its decision commits; keep callbacks side-effect free. */
  reportPreparationTimeoutMillis: Schema.optionalKey(
    Positive.check(Schema.isLessThanOrEqualTo(30_000)),
  ),
});

export type WorkerHostLimits = typeof WorkerHostLimits.Type;

export const WorkerHostConfig = Context.Reference<WorkerHostLimits>(
  "@effect-agent/thread/WorkerHostConfig",
  {
    defaultValue: () => ({
      maxWorkersPerSource: 32,
      maxInputsPerWorker: 64,
      maxPendingInputsPerWorker: 8,
      lifetimeMillis: 86_400_000,
    }),
  },
);

/**
 * Authenticate every acquisition/operation and authorize its exact source Thread. A returned
 * Principal is host-owned admission identity. Context access authenticates source metadata;
 * read, send and control remain separate grants. WorkerRefs and caller-supplied Thread
 * identifiers alone never confer any of them.
 */
export interface WorkerHostAuthorizationRequest {
  readonly sourceThreadId: ThreadId;
  /** An explicitly selected owner input; authorize this locator as well as the Thread. */
  readonly sourceSubmissionId?: SubmissionId;
  readonly principal: Principal;
  readonly operation: WorkerError["operation"];
  readonly access: "context" | "read" | "send" | "control";
  readonly worker?: WorkerRef;
}

export const WorkerHostAuthorizer = Context.Reference<{
  readonly authorize: (
    request: WorkerHostAuthorizationRequest,
  ) => Effect.Effect<Principal, WorkerError>;
}>("@effect-agent/thread/WorkerHostAuthorizer", {
  defaultValue: () => ({
    authorize: (request) =>
      WorkerError.make({
        operation: request.operation,
        reason: "denied",
      }),
  }),
});

/**
 * Deployment-owned permission to fund a root's background worker independently. The decision
 * covers the exact immutable origin and is checked again before each input admission. It never
 * changes delegation depth or Tool authority. Omission denies independent funding.
 */
export const WorkerBudgetAuthorizer = Context.Reference<{
  readonly authorize: (request: {
    readonly source: WorkerSource;
    readonly principal: Principal;
    readonly worker: WorkerRef;
    readonly policy: AgentPolicy;
    readonly budget: SubagentBudgetReservation;
  }) => Effect.Effect<void, WorkerError>;
}>("@effect-agent/thread/WorkerBudgetAuthorizer", {
  defaultValue: () => ({
    authorize: () => WorkerError.make({ operation: "start", reason: "denied" }),
  }),
});

import type * as Agent from "@effect-agent/core/Agent";
import {
  type InputPromptSource,
  type InstructionSource,
  type ModelServices,
  type RunDispositionDeclaration,
} from "@effect-agent/core/Agent";
import { type ThreadId, AgentId } from "@effect-agent/core/Identifiers";
import {
  AdditionalToolCatalog,
  DiscoveryTool,
  IncludesCatalogDocumentation,
  PinnedTool,
  ToolNamespace,
} from "@effect-agent/core/ToolExposure";
import { type RuntimeBinding } from "@effect-agent/engine/AgentRuntime";
import {
  WorkerReportPreparationFailure,
  type WorkerReporting,
} from "@effect-agent/engine/SubagentHost";
import { type Crypto, type Option, type Scope, Context, Effect, Layer, Schema } from "effect";
import type { Tool } from "effect/unstable/ai";

import { digestDefinitions, type DigestError } from "../Digest.ts";
import type { DurableWorkerFailure, DurableWorkerRequirements } from "../DurableAgentRuntime.ts";
import type { DefinitionDigestInput, DefinitionDigests } from "../Records.ts";
import type { Claim, Settlement } from "../SubmissionLedger.ts";

/**
 * No Agent Binding is registered for the requested stable identity. Recovery
 * fails closed: it never substitutes the latest Binding or runs different
 * code.
 */
export class BindingUnavailable extends Schema.TaggedError<BindingUnavailable>()(
  "BindingUnavailable",
  {
    agentId: AgentId,
    message: Schema.String,
  },
) {}

/**
 * A Binding is registered for the identity but its exact stored
 * definition/model/tool digests do not match the claimed head's stored
 * digests byte-for-byte. Fail closed (SUB-023): missing or different code is
 * a typed compatibility failure, never a silent substitution.
 */
export class BindingDigestMismatch extends Schema.TaggedError<BindingDigestMismatch>()(
  "BindingDigestMismatch",
  {
    agentId: AgentId,
    message: Schema.String,
  },
) {}

/** The typed refusal family of durable Binding resolution (spec §11, SUB-032). */
export type DurableBindingFailure = BindingUnavailable | BindingDigestMismatch;

/** Byte-for-byte equality of two stored definition digest triples (SUB-023). */
export const definitionDigestsEqual = (
  left: DefinitionDigests,
  right: DefinitionDigests,
): boolean =>
  left.agent === right.agent && left.model === right.model && left.tools === right.tools;

type ExecutableDefinition = Agent.AnyDefinition & {
  readonly instructions: InstructionSource<never, unknown, unknown>;
  readonly inputPrompt?: InputPromptSource<never, unknown, unknown> | undefined;
};

/** Executable model Binding accepted by durable registration descriptors. */
export type ExecutableAgentBinding = {
  readonly definition: ExecutableDefinition;
  readonly model: Layer.Layer<ModelServices, never, unknown>;
};

/**
 * Internal coordinator entry point for one fenced Attempt over an already-granted claim.
 * The generic signature matches `runAttempt` and is specialized for each captured Agent.
 */
type ResolvedAttemptDriver = <
  InputSchema extends Schema.Top,
  OutputSchema extends Schema.Top,
  Instructions,
  Tools extends Record<string, Tool.Any>,
  Provider,
  ModelProvides,
  ModelRequires,
  InstructionError,
  InstructionRequirements,
  RunDispositionValue extends
    | RunDispositionDeclaration<OutputSchema["Type"], Schema.Top>
    | undefined,
  InputPromptValue extends InputPromptSource<InputSchema["Type"], unknown, unknown> | undefined,
>(
  agent: RuntimeBinding<
    InputSchema,
    OutputSchema,
    Instructions,
    Tools,
    Provider,
    ModelProvides,
    ModelRequires,
    InstructionError,
    InstructionRequirements,
    RunDispositionValue,
    InputPromptValue
  >,
  threadId: ThreadId,
  claim: Claim,
) => Effect.Effect<
  Option.Option<Settlement>,
  DurableWorkerFailure,
  DurableWorkerRequirements<
    RuntimeBinding<
      InputSchema,
      OutputSchema,
      Instructions,
      Tools,
      Provider,
      ModelProvides,
      ModelRequires,
      InstructionError,
      InstructionRequirements,
      RunDispositionValue,
      InputPromptValue
    >,
    InstructionRequirements
  >
>;

type CapturedAttempt<A extends ExecutableAgentBinding> = (
  agent: A,
  threadId: ThreadId,
  claim: Claim,
) => Effect.Effect<Option.Option<Settlement>, DurableWorkerFailure, DurableWorkerRequirements<A>>;

/**
 * An Agent with its worker services captured, ready to drive a fenced Attempt.
 * Concrete Schema and model types stay inside this closure when registrations are collected.
 */
interface CapturedBinding {
  readonly agentId: AgentId;
  /** Exact immutable definition whose codecs and behavior the worker captured. */
  readonly definition: Agent.AnyDefinition;
  /** Captured independently from per-Attempt services: report preparation has no fenced Claim. */
  readonly reporting?: ReadonlyArray<WorkerReporting<WorkerReportPreparationFailure>>;
  readonly attempt: (
    driver: ResolvedAttemptDriver,
    threadId: ThreadId,
    claim: Claim,
  ) => Effect.Effect<Option.Option<Settlement>, DurableWorkerFailure>;
}

type ReportRequirements<Reports extends ReadonlyArray<WorkerReporting<unknown, unknown>>> = [
  Reports[number],
] extends [never]
  ? never
  : Reports[number] extends WorkerReporting<unknown, infer R>
    ? Exclude<R, Scope.Scope>
    : never;

const captureReporting = <R>(reports: ReadonlyArray<WorkerReporting<unknown, R>>) =>
  Effect.map(Effect.context<Exclude<R, Scope.Scope>>(), (context) =>
    reports.map((report): WorkerReporting<WorkerReportPreparationFailure> => ({
      ...report,
      prepare: (value) =>
        Effect.scoped(Effect.suspend(() => report.prepare(value))).pipe(
          Effect.provide(context),
          Effect.mapError((error) =>
            Schema.is(WorkerReportPreparationFailure)(error)
              ? error
              : WorkerReportPreparationFailure.make({ stage: "preparation" }),
          ),
        ),
    })),
  );

/** One exact executable registration used by durable claim-time resolution. */
export interface ResolvedBinding extends CapturedBinding {
  readonly digests: DefinitionDigests;
}

/** Trusted claim identity for resolving per-Attempt application services. Not model input. */
export interface AgentAttemptContext {
  readonly threadId: ThreadId;
  readonly submissionId: Claim["submissionId"];
  readonly attemptId: Claim["attemptId"];
}

const capture = <A extends ExecutableAgentBinding, Provides = never, Requires = never>(
  agent: A,
  attemptLayer?: (context: AgentAttemptContext) => Layer.Layer<Provides, never, Requires>,
): Effect.Effect<
  CapturedBinding,
  never,
  Exclude<DurableWorkerRequirements<A>, Provides> | Requires
> =>
  Effect.map(
    Effect.context<Exclude<DurableWorkerRequirements<A>, Provides> | Requires>(),
    (context): CapturedBinding => ({
      agentId: agent.definition.id,
      definition: agent.definition,
      attempt: (driver, threadId, claim) => {
        // Registration closes one concrete Binding before heterogeneous registrations are
        // collected. TypeScript cannot instantiate the higher-rank RuntimeBinding parameters
        // from the intentionally erased public shape, so specialize the driver back to A here.
        const run = driver as unknown as CapturedAttempt<A>;
        const execute = run(agent, threadId, claim);

        const scoped =
          attemptLayer === undefined
            ? execute
            : execute.pipe(
                Effect.provide(
                  Layer.fresh(
                    attemptLayer({
                      threadId,
                      submissionId: claim.submissionId,
                      attemptId: claim.attemptId,
                    }),
                  ),
                ),
              );

        return scoped.pipe(Effect.provide(context)) as Effect.Effect<
          Option.Option<Settlement>,
          DurableWorkerFailure
        >;
      },
    }),
  );

/**
 * Build one exact worker registration from an executable Agent Binding and
 * its already-computed definition digests.
 *
 * `make(agent, digests)` captures the binding plus its worker-requirement
 * Context at Layer/effect construction time. Hosts that start from application
 * version declarations should use `compileRegistrations`; low-level fixtures
 * may supply a previously computed digest triple directly.
 */
export const DurableWorkerBinding = {
  make: <
    A extends ExecutableAgentBinding,
    const Reports extends ReadonlyArray<WorkerReporting<unknown, unknown>> = readonly [],
  >(
    agent: A,
    digests: DefinitionDigests,
    reporting?: Reports,
  ): Effect.Effect<
    ResolvedBinding,
    never,
    DurableWorkerRequirements<A> | ReportRequirements<Reports>
  > =>
    Effect.gen(function* () {
      const binding = yield* capture(agent);
      const reports = yield* captureReporting(reporting ?? []);

      return { ...binding, digests, reporting: reports };
    }) as Effect.Effect<
      ResolvedBinding,
      never,
      DurableWorkerRequirements<A> | ReportRequirements<Reports>
    >,
} as const;

/** INTERNAL identity-only capture retained for the legacy direct worker path. */
export const makeLegacyWorkerBinding = capture;

export const resolveWorkerBinding = (
  bindings: ReadonlyArray<ResolvedBinding>,
  agentId: AgentId,
  digests: DefinitionDigests,
): Effect.Effect<ResolvedBinding, DurableBindingFailure> => {
  const registered = bindings.filter((binding) => binding.agentId === agentId);

  if (registered.length === 0) {
    return Effect.fail(
      BindingUnavailable.make({
        agentId,
        message: `No Agent Binding is registered for ${agentId}; recovery never substitutes different code (SUB-023)`,
      }),
    );
  }
  const exact = registered.find((binding) => definitionDigestsEqual(binding.digests, digests));

  if (exact === undefined) {
    return Effect.fail(
      BindingDigestMismatch.make({
        agentId,
        message: `The registered Binding for ${agentId} does not match the stored definition digests exactly; missing or different code fails closed (SUB-023)`,
      }),
    );
  }

  return Effect.succeed(exact);
};

/** Resolve authoring-time admission through the one exact host registration, never by identity alone. */
export const resolveDefinitionBinding = (
  bindings: ReadonlyArray<ResolvedBinding>,
  definition: Pick<Agent.AnyDefinition, "id">,
): Effect.Effect<ResolvedBinding, BindingUnavailable> => {
  const candidates = bindings.filter((binding) => binding.agentId === definition.id);
  const binding = candidates[0];

  if (candidates.length !== 1 || binding === undefined) {
    return Effect.fail(
      BindingUnavailable.make({
        agentId: definition.id,
        message: "Registered admission requires exactly one binding for the Agent identity",
      }),
    );
  }

  if (!Object.is(binding.definition, definition)) {
    return Effect.fail(
      BindingUnavailable.make({
        agentId: definition.id,
        message: "Registered admission requires the exact Agent Definition used in registration",
      }),
    );
  }

  return Effect.succeed(binding);
};

/** Application versions and a model Layer, supplied directly or through an existing Binding. */
export type AgentRegistration<A extends ExecutableAgentBinding = ExecutableAgentBinding> = (
  | { readonly agent: A; readonly model?: never; readonly definitions: DefinitionDigestInput }
  | {
      readonly agent: A["definition"];
      readonly model: A["model"];
      readonly definitions: DefinitionDigestInput;
    }
) & {
  /**
   * Source-owned reports capture services outside attemptLayer and open a fresh Scope per
   * preparation. Version changes with this registration. Missing exact code and preparation
   * failures become retained report refusals; durable delivery retries reuse the frozen input.
   */
  readonly reporting?: ReadonlyArray<WorkerReporting<unknown, unknown>>;
  /**
   * Build fresh services for exactly one fenced Attempt, across all its Tool/model turns.
   * Finalizes on completion, suspension, failure and interruption. Never reused after eviction.
   * Resolve invocation authority from the trusted claim identity, not captured caller state.
   * Keep fallible resource acquisition lazy in typed Tool operations; this Layer cannot fail.
   */
  readonly attemptLayer?: (context: AgentAttemptContext) => Layer.Layer<never, never, unknown>;
};

type EntryWorkerRequirements<Entry> = Entry extends {
  readonly agent: infer A extends ExecutableAgentBinding;
}
  ? DurableWorkerRequirements<A>
  : Entry extends {
        readonly agent: infer D extends ExecutableDefinition;
        readonly model: infer M extends ExecutableAgentBinding["model"];
      }
    ? DurableWorkerRequirements<{ readonly definition: D; readonly model: M }>
    : never;

type EntryAttemptRequirements<Entry> = Entry extends {
  readonly attemptLayer: (
    context: AgentAttemptContext,
  ) => Layer.Layer<infer Provides, never, infer Requires>;
}
  ? Exclude<EntryWorkerRequirements<Entry>, Provides> | Requires
  : EntryWorkerRequirements<Entry>;

type EntryRequirements<Entry> =
  | EntryAttemptRequirements<Entry>
  | (Entry extends {
      readonly reporting: infer Reports extends ReadonlyArray<WorkerReporting<unknown, unknown>>;
    }
      ? ReportRequirements<Reports>
      : never);

type RegistrationRequirements<Entries extends ReadonlyArray<AgentRegistration>> = [
  Entries[number],
] extends [never]
  ? never
  : EntryRequirements<Entries[number]>;

const registrationDefinitions = (entry: AgentRegistration): DefinitionDigestInput => {
  const definition = entry.model === undefined ? entry.agent.definition : entry.agent;
  const exposure = definition.toolExposure;

  if (
    exposure === undefined &&
    !Object.values(definition.toolkit.tools).some(
      (tool) =>
        Context.get(tool.annotations, DiscoveryTool) || Context.get(tool.annotations, PinnedTool),
    )
  )
    return entry.definitions;

  return {
    ...entry.definitions,
    agent: {
      declaration: entry.definitions.agent,
      toolExposure: {
        initialToolNames: exposure === undefined ? null : [...(exposure.initialToolNames ?? [])],
        maxTools: exposure?.maxTools ?? 64,
        maxSchemaBytes: exposure?.maxSchemaBytes ?? 262_144,
        requiredCompletion:
          definition.completion?.required === true ? definition.completion.tool : null,
        tools: Object.values(definition.toolkit.tools).map((tool) => ({
          name: tool.name,
          pinned: Context.get(tool.annotations, PinnedTool),
          discovery: Context.get(tool.annotations, DiscoveryTool),
          namespace: Context.get(tool.annotations, ToolNamespace) ?? null,
          includesCatalogDocumentation: Context.get(tool.annotations, IncludesCatalogDocumentation),
          additional: Context.get(tool.annotations, AdditionalToolCatalog).map((entry) => ({
            name: entry.tool.name,
            namespace: entry.namespace,
            method: entry.method,
          })),
        })),
      },
    },
  };
};

const compileRegistration = <Entry extends AgentRegistration>(
  entry: Entry,
): Effect.Effect<ResolvedBinding, DigestError, Crypto.Crypto | EntryRequirements<Entry>> =>
  Effect.flatMap(
    digestDefinitions(registrationDefinitions(entry)),
    (digests) =>
      Effect.gen(function* () {
        const binding = yield* capture(
          entry.model === undefined ? entry.agent : { definition: entry.agent, model: entry.model },
          entry.attemptLayer,
        );

        const reporting = yield* captureReporting(entry.reporting ?? []);

        return { ...binding, digests, reporting };
      }),
    // The erased descriptor accepts arbitrary provided services. Restore the concrete entry's
    // Exclude<worker requirements, provided services> | layer requirements at this collection seam.
  ) as Effect.Effect<ResolvedBinding, DigestError, Crypto.Crypto | EntryRequirements<Entry>>;

/** Compile heterogeneous Agent descriptors into exact, dependency-closed worker registrations. */
export const compileRegistrations = <const Entries extends ReadonlyArray<AgentRegistration>>(
  entries: Entries,
): Effect.Effect<
  ReadonlyArray<ResolvedBinding>,
  DigestError,
  Crypto.Crypto | RegistrationRequirements<Entries>
> => {
  // `Effect.forEach` instantiates a generic callback at its constraint. Specialize the callback to
  // this tuple's distributed requirement union before collection so empty and heterogeneous tuples
  // retain their exact service requirements.
  const compileEntry = compileRegistration as unknown as (
    entry: Entries[number],
  ) => Effect.Effect<
    ResolvedBinding,
    DigestError,
    Crypto.Crypto | RegistrationRequirements<Entries>
  >;

  return Effect.forEach(entries, compileEntry);
};

import { Option, Schema } from "effect";

const ErrorMessage = Schema.Struct({ message: Schema.String });
const ErrorTag = Schema.Struct({ _tag: Schema.NonEmptyString });
const decodeErrorMessage = Schema.decodeUnknownOption(ErrorMessage);
const decodeErrorTag = Schema.decodeUnknownOption(ErrorTag);

interface ForeignDiagnostic {
  readonly tag?: string | undefined;
  readonly message?: string | undefined;
}

/**
 * Inspect a foreign failure without trusting its property accessors. Schema owns the accepted
 * fields, while the guards around each decode keep hostile proxies and getters from escaping as
 * defects during diagnostic projection.
 */
export const inspectForeignDiagnostic = (value: unknown): ForeignDiagnostic => {
  let tag: string | undefined;
  let message: string | undefined;

  try {
    tag = Option.getOrUndefined(decodeErrorTag(value))?._tag;
  } catch {
    // A diagnostic is best effort. The caller supplies the stable fallback classification.
  }

  try {
    message = Option.getOrUndefined(decodeErrorMessage(value))?.message;
  } catch {
    // A hostile message accessor must not replace the original failure with a defect.
  }

  return {
    ...(tag === undefined ? {} : { tag }),
    ...(message === undefined ? {} : { message }),
  };
};

/** Render an opaque foreign value without allowing its coercion hooks to escape. */
export const safeUnknownString = (value: unknown, fallback: string): string => {
  try {
    return String(value);
  } catch {
    return fallback;
  }
};

import { RunId, SubmissionId } from "@effect-agent/core/Identifiers";
import { RunPolicyUsage } from "@effect-agent/core/RunPolicyUsage";
import { Selection } from "@effect-agent/core/ToolExposure";
import { RunUsageSummary } from "@effect-agent/core/Usage";
import { Option, Schema } from "effect";
import { Prompt } from "effect/unstable/ai";

import { CanonicalRecordEnvelope, CanonicalSequence, Digest, PersistedJson } from "../Records.ts";

/** Retired accounting is additive; the latest Tool batch always remains replayable verbatim. */
export class JournalCheckpointSeed extends Schema.Class<JournalCheckpointSeed>(
  "@effect-agent/thread/internal/JournalCheckpointSeed",
)({
  runId: RunId,
  throughSequence: CanonicalSequence,
  firstSequence: Schema.optionalKey(CanonicalSequence),
  toolSelection: Schema.optionalKey(Selection),
  committedTurns: Schema.Natural,
  policyUsage: RunPolicyUsage,
  modelCalls: Schema.Natural,
  unobservedModelCalls: Schema.Natural,
  inputTokens: Schema.Natural,
  outputTokens: Schema.Natural,
  lastInputTokens: Schema.Natural,
  lastOutputTokens: Schema.Natural,
  costMicrousd: Schema.Natural,
  summarizedModelUsage: RunUsageSummary,
  protectedContext: Schema.optionalKey(PersistedJson),
  contextWindowId: Schema.optionalKey(Schema.String),
  frontier: Schema.optionalKey(
    Schema.Struct({
      sequence: CanonicalSequence,
      tag: Schema.Literals(["ModelResponseRecorded", "ToolCallSettled"]),
    }),
  ),
  /** Canonical replacement whose covered batches were validated before retirement. */
  compaction: CanonicalRecordEnvelope,
}) {}

/** A bounded sparse projection, never a canonical log or a submission-ownership record. */
export class RecoveryCheckpointState extends Schema.Class<RecoveryCheckpointState>(
  "@effect-agent/thread/internal/RecoveryCheckpointState",
)({
  schemaVersion: Schema.Literal(1),
  policyAccountingVersion: Schema.Literal(1),
  submissionId: SubmissionId,
  submissionIds: Schema.Array(SubmissionId).check(Schema.isMaxLength(4_096)),
  seed: JournalCheckpointSeed,
  records: Schema.Array(CanonicalRecordEnvelope).check(Schema.isMaxLength(4_096)),
}) {}

export class RecoveryCheckpointContents extends Schema.Class<RecoveryCheckpointContents>(
  "@effect-agent/thread/internal/RecoveryCheckpointContents",
)({
  state: RecoveryCheckpointState,
  digest: Digest,
}) {}

export const RECOVERY_ENGINE_VERSION = "effect-agent/recovery@1";

/**
 * Late evidence can invalidate an old compaction. Such histories use full canonical replay;
 * an omitted run/turn must never be treated as proven absent by a sparse projection.
 */
export const checkpointSuffixCompatible = (
  seed: JournalCheckpointSeed,
  records: ReadonlyArray<CanonicalRecordEnvelope>,
  retained: ReadonlyArray<CanonicalRecordEnvelope>,
): boolean =>
  records.every(({ sequence, record: { payload } }) => {
    if ("runId" in payload && payload.runId !== undefined && payload.runId !== seed.runId)
      return false;
    if ("turn" in payload && payload.turn <= seed.committedTurns) return false;
    if (payload._tag === "ToolCallSettled" || payload._tag === "ToolCallResolved") {
      // These records have no turn. The retained declaration/preparation proves their scope.
      return [...retained, ...records].some(
        ({ sequence: declarationSequence, record: { payload: candidate } }) => {
          if (
            candidate._tag !== "ModelResponseRecorded" ||
            candidate.runId !== payload.runId ||
            candidate.turn <= seed.committedTurns ||
            seed.compaction.record.payload._tag !== "CompactionCreated" ||
            declarationSequence <= seed.compaction.record.payload.coversThrough ||
            declarationSequence >= sequence
          )
            return false;
          const decoded = Schema.decodeUnknownOption(Prompt.Prompt)(candidate.messages);

          return (
            Option.isSome(decoded) &&
            decoded.value.content.some(
              (message) =>
                message.role === "assistant" &&
                message.content.some(
                  (part) => part.type === "tool-call" && part.id === payload.toolCallId,
                ),
            )
          );
        },
      );
    }

    return payload._tag !== "CompactionCreated" || payload.coversThrough >= seed.throughSequence;
  });

import { type RunId } from "@effect-agent/core/Identifiers";

import {
  type CanonicalRecordEnvelope,
  type CompactionCreated,
  type ToolCallSettled,
} from "../Records.ts";
import { type JournalCheckpointSeed } from "./journal-checkpoint.ts";

/** Metadata for one exact canonical prefix, including the same optional checkpoint seed. */
export interface JournalMetadata {
  readonly ownerRunId: RunId | undefined;
  readonly seed: JournalCheckpointSeed | undefined;
  readonly firstSequenceByRun: ReadonlyMap<string, number>;
  readonly lastResponseSequenceByRun: ReadonlyMap<string, number>;
  readonly terminalSequenceByRun: ReadonlyMap<string, number>;
  readonly settledSpans: ReadonlyArray<{ readonly from: number; readonly to: number }>;
  readonly settledToolCallRecordIds: ReadonlySet<string>;
  readonly settledById: ReadonlyMap<
    string,
    Pick<ToolCallSettled, "isFailure" | "budgetRejected" | "toolSelection">
  >;
  readonly compactions: ReadonlyArray<{
    readonly payload: CompactionCreated;
    readonly sequence: number;
  }>;
}

/**
 * Attempt-local metadata collector. Feed every validated record exactly once, in canonical order,
 * including records omitted from the control view. A snapshot is independent of later suffix
 * additions and may only accompany a replay stream bounded at that same captured tail.
 */
export const makeJournalMetadata = (
  ownerRunId: RunId | undefined,
  seed?: JournalCheckpointSeed,
) => {
  const firstSequenceByRun = new Map<string, number>();

  if (seed?.firstSequence !== undefined) firstSequenceByRun.set(seed.runId, seed.firstSequence);
  const lastResponseSequenceByRun = new Map<string, number>();
  const terminalSequenceByRun = new Map<string, number>();
  const settledSpans: Array<{ readonly from: number; readonly to: number }> = [];
  const settledToolCallRecordIds = new Set<string>();

  const settledById = new Map<
    string,
    Pick<ToolCallSettled, "isFailure" | "budgetRejected" | "toolSelection">
  >();

  const compactions: Array<{ readonly payload: CompactionCreated; readonly sequence: number }> = [];

  return {
    add: (envelope: CanonicalRecordEnvelope): void => {
      const payload = envelope.record.payload;

      if (
        (payload._tag === "RunCompleted" ||
          payload._tag === "RunFailed" ||
          payload._tag === "SubmissionSettled") &&
        payload.runId !== undefined &&
        !terminalSequenceByRun.has(payload.runId)
      )
        terminalSequenceByRun.set(payload.runId, envelope.sequence);
      if (payload._tag === "CompactionCreated") {
        compactions.push({ payload, sequence: envelope.sequence });

        return;
      }
      if (
        "runId" in payload &&
        typeof payload.runId === "string" &&
        !firstSequenceByRun.has(payload.runId)
      )
        firstSequenceByRun.set(payload.runId, envelope.sequence);
      if (payload._tag === "ModelResponseRecorded") {
        lastResponseSequenceByRun.set(payload.runId, envelope.sequence);
      } else if (payload._tag === "ToolCallSettled") {
        settledToolCallRecordIds.add(envelope.record.recordId);
        if (payload.runId === ownerRunId)
          settledById.set(envelope.record.recordId, {
            isFailure: payload.isFailure,
            ...(payload.toolSelection === undefined
              ? {}
              : { toolSelection: payload.toolSelection }),
            ...(payload.budgetRejected === undefined
              ? {}
              : { budgetRejected: payload.budgetRejected }),
          });
        const from = lastResponseSequenceByRun.get(payload.runId);

        if (from !== undefined && from < envelope.sequence)
          settledSpans.push({ from, to: envelope.sequence });
      }
    },
    snapshot: (): JournalMetadata => ({
      ownerRunId,
      seed,
      firstSequenceByRun: new Map(firstSequenceByRun),
      lastResponseSequenceByRun: new Map(lastResponseSequenceByRun),
      terminalSequenceByRun: new Map(terminalSequenceByRun),
      settledSpans: [...settledSpans],
      settledToolCallRecordIds: new Set(settledToolCallRecordIds),
      settledById: new Map(settledById),
      compactions: [...compactions],
    }),
  };
};

import type { AgentId, ThreadId } from "@effect-agent/core/Identifiers";
import type { InboxPage } from "@effect-agent/core/Messaging";
import {
  MessageAdmission,
  MessageRef,
  MessageStatus,
  MessagingError,
  PeerName,
} from "@effect-agent/core/Messaging";
import { IdempotencyKey, type Principal } from "@effect-agent/core/Receipt";
import type { WorkerSource } from "@effect-agent/core/Worker";
import {
  type MessagingHost,
  type PeerTarget,
  type SendPeerMessage,
} from "@effect-agent/engine/MessagingHost";
import { Clock, Crypto, DateTime, Effect, Option, Schema, Stream } from "effect";

import { digestJson } from "../Digest.ts";
import type { DurableSubmitOptions } from "../DurableAgentRuntime.ts";
import {
  MessageDeliveryFailpoint,
  MessageDeliveryStore,
  type MessageDeliveryRecord,
  prepareMessageDelivery,
} from "../MessageDelivery.ts";
import {
  PeerAuthorizer,
  PeerRoutes,
  PeerDeliveryLifetime,
  PeerMessageCapacity,
} from "../MessagingHost.ts";
import {
  BatchId,
  CanonicalBatch,
  CanonicalSequence,
  type DeploymentId,
  type Digest,
  PeerMessagePrepared,
  PersistedJson,
  type ProducerId,
  RecordEnvelope,
  RecordId,
} from "../Records.ts";
import { PreparedInput } from "../Subscription.ts";
import {
  FencedAppendRequest,
  ThreadExportRequest,
  ThreadRead,
  ThreadTailRequest,
  ThreadStore,
} from "../ThreadStore.ts";
import {
  definitionDigestsEqual,
  resolveDefinitionBinding,
  type ResolvedBinding,
} from "./agent-registration.ts";

export interface MessagingRuntimeOptions {
  readonly bindings: ReadonlyArray<ResolvedBinding>;
  readonly deploymentId: DeploymentId;
  readonly producerId: ProducerId;
}

const failure = (operation: MessagingError["operation"], reason: MessagingError["reason"]) =>
  MessagingError.make({ operation, reason });

const sameRef = Schema.toEquivalence(MessageRef);
const sameAdmission = Schema.toEquivalence(MessageAdmission);
const sameJson = Schema.toEquivalence(PersistedJson);

/** Thread-owned durable peer delivery. Source proof and the independent due index survive Run settlement. */
export const makeMessagingRuntime = Effect.fn("MessagingHost.make")(function* (
  options: MessagingRuntimeOptions,
) {
  const deps = {
    ...options,
    store: yield* ThreadStore,
    deliveries: yield* Effect.serviceOption(MessageDeliveryStore),
    crypto: yield* Crypto.Crypto,
    authorizer: yield* PeerAuthorizer,
    routes: yield* PeerRoutes,
    lifetimeMillis: yield* PeerDeliveryLifetime,
    maxMessagesPerSource: yield* PeerMessageCapacity,
    failpoint: yield* MessageDeliveryFailpoint,
  };

  const digest = (value: Schema.Json) =>
    digestJson(value).pipe(
      Effect.provideService(Crypto.Crypto, deps.crypto),
      Effect.mapError(() => failure("send", "storage")),
    );

  const read = (threadId: ThreadId) =>
    deps.store
      .export(ThreadExportRequest.make({ threadId }))
      .pipe(Effect.mapError(() => failure("context", "storage")));

  const sourceOf = Effect.fn("MessagingHost.source")(function* (threadId: ThreadId) {
    const log = yield* read(threadId);
    const created = log.records[0]?.record.payload;

    if (created?._tag !== "ThreadCreated") return yield* failure("context", "not-found");

    const matching = deps.bindings.filter(
      (binding) =>
        binding.agentId === created.agentId &&
        definitionDigestsEqual(binding.digests, created.definitions),
    );

    if (matching.length !== 1) return yield* failure("context", "binding-mismatch");

    return { log, address: { threadId, agentId: created.agentId } };
  });

  const decodeProof = Effect.fn("MessagingHost.decodeProof")(function* (record: RecordEnvelope) {
    if (record.payload._tag !== "PeerMessagePrepared") return yield* failure("send", "corrupt");

    const envelope = yield* Schema.decodeUnknownEffect(PreparedInput)(
      record.payload.encodedEnvelope,
    ).pipe(Effect.mapError(() => failure("send", "corrupt")));

    if (
      envelope.messageAdmission === undefined ||
      envelope.messageAdmission.message.messageId !== record.payload.messageId
    )
      return yield* failure("send", "corrupt");

    return {
      envelope,
      sourcePrincipal: record.payload.sourcePrincipal,
      operation: record.payload.operation,
      deadlineAtMillis: record.payload.deadlineAtMillis,
      createdAtMillis: DateTime.toEpochMillis(record.createdAt),
    };
  });

  const proof = Effect.fn("MessagingHost.proof")(function* (message: MessageRef) {
    const source = yield* sourceOf(message.ownerThreadId);

    const record = source.log.records.find(
      ({ record }) =>
        record.payload._tag === "PeerMessagePrepared" &&
        record.payload.messageId === message.messageId,
    )?.record;

    if (record === undefined) return yield* failure("reply", "invalid-reference");
    const saved = yield* decodeProof(record);

    if (
      saved.envelope.messageAdmission?.sender.agentId !== source.address.agentId ||
      !sameRef(saved.envelope.messageAdmission.message, message)
    )
      return yield* failure("reply", "invalid-reference");

    return saved;
  });

  const authorizeEnvelope = Effect.fn("MessagingHost.authorizeEnvelope")(function* (
    saved: Effect.Success<ReturnType<typeof proof>>,
    operation: "send" | "reply",
  ) {
    const metadata = saved.envelope.messageAdmission;

    if (metadata === undefined) return yield* failure(operation, "corrupt");

    const principal = yield* deps.authorizer.authorize({
      source: metadata.sender,
      principal: saved.sourcePrincipal,
      operation: saved.operation,
      access: "send",
      peerName: metadata.peerName,
      destination: { threadId: saved.envelope.threadId, agentId: saved.envelope.agentId },
    });

    if (principal !== saved.envelope.deliveryPrincipal) return yield* failure(operation, "denied");
  });

  const status = (row: MessageDeliveryRecord): MessageStatus =>
    MessageStatus.make({
      message: row.key,
      status: row.status,
      receipt: row.receipt,
      settlement:
        row.settlement === null
          ? null
          : { settlementId: row.settlement.settlementId, outcome: row.settlement.outcome },
      reason: row.refusal ?? row.parkReason,
    });

  const deliveries = (operation: MessagingError["operation"]) =>
    Option.isSome(deps.deliveries)
      ? Effect.succeed(deps.deliveries.value)
      : failure(operation, "unavailable");

  const mapStore =
    (operation: MessagingError["operation"]) =>
    (error: { readonly _tag: string; readonly reason?: string }) =>
      failure(
        operation,
        error.reason === "capacity"
          ? "capacity"
          : error.reason === "conflict"
            ? "conflict"
            : "storage",
      );

  const lifetime = Schema.decodeUnknownEffect(
    Schema.Int.check(Schema.isGreaterThan(0), Schema.isLessThanOrEqualTo(604_800_000)),
  )(deps.lifetimeMillis).pipe(Effect.mapError(() => failure("send", "capacity")));

  const capacity = Schema.decodeUnknownEffect(
    Schema.Int.check(Schema.isGreaterThan(0), Schema.isLessThanOrEqualTo(1_000)),
  )(deps.maxMessagesPerSource ?? 256).pipe(Effect.mapError(() => failure("send", "capacity")));

  const facet = (
    threadId: ThreadId,
    principal: Principal,
    toolSource?: WorkerSource,
  ): MessagingHost["Service"] => {
    const authorize = Effect.fn("MessagingHost.authorize")(function* (
      operation: MessagingError["operation"],
      access: "context" | "read" | "send" | "control",
      peer?: PeerTarget,
      destination?: { readonly threadId: ThreadId; readonly agentId: AgentId },
    ) {
      const source = yield* sourceOf(threadId);

      if (
        toolSource !== undefined &&
        (toolSource.agentId !== source.address.agentId || toolSource.threadId !== threadId)
      )
        return yield* failure(operation, "denied");
      if (peer !== undefined)
        yield* Schema.decodeUnknownEffect(PeerName)(peer.name).pipe(
          Effect.mapError(() => failure(operation, "invalid-input")),
        );

      const deliveryPrincipal = yield* deps.authorizer.authorize({
        source: source.address,
        principal,
        operation,
        access,
        ...(peer === undefined ? {} : { peerName: peer.name }),
        ...(destination === undefined ? {} : { destination }),
      });

      return { ...source, deliveryPrincipal };
    });

    const send = Effect.fn("MessagingHost.send")(function* (
      request: SendPeerMessage,
      operation: "send" | "reply",
    ) {
      const initial = yield* authorize(operation, "send", request);

      const target = yield* resolveDefinitionBinding(deps.bindings, request.target).pipe(
        Effect.mapError(() => failure(operation, "binding-mismatch")),
      );

      const encoded = yield* Schema.decodeUnknownEffect(Schema.toEncoded(target.definition.input))(
        request.encodedInput,
      ).pipe(Effect.mapError(() => failure(operation, "invalid-input")));

      const input = yield* Schema.decodeUnknownEffect(PersistedJson)(encoded).pipe(
        Effect.flatMap(Schema.encodeEffect(Schema.fromJsonString(PersistedJson))),
        Effect.flatMap(Schema.decodeEffect(Schema.fromJsonString(PersistedJson))),
        Effect.mapError(() => failure(operation, "invalid-input")),
      );

      const key = yield* Schema.decodeUnknownEffect(IdempotencyKey)(request.idempotencyKey).pipe(
        Effect.mapError(() => failure(operation, "invalid-input")),
      );

      const inReplyTo =
        request.inReplyTo === undefined
          ? undefined
          : yield* Schema.decodeUnknownEffect(MessageRef)(request.inReplyTo).pipe(
              Effect.mapError(() => failure(operation, "invalid-reference")),
            );

      const message: MessageRef = {
        ownerThreadId: threadId,
        messageId: Schema.decodeSync(IdempotencyKey)(
          `peer:${yield* digest([threadId, principal, request.name, operation, key])}`,
        ),
      };

      const store = yield* deliveries(operation);
      const window = yield* lifetime;
      const maxMessages = yield* capacity;

      for (let attempt = 0; attempt < 8; attempt++) {
        const current = attempt === 0 ? initial : yield* sourceOf(threadId);

        const prior = current.log.records.find(
          ({ record }) =>
            record.payload._tag === "PeerMessagePrepared" &&
            record.payload.messageId === message.messageId,
        )?.record;

        let saved: Effect.Success<ReturnType<typeof proof>>;

        if (prior !== undefined) {
          saved = yield* decodeProof(prior);
          const metadata = saved.envelope.messageAdmission;

          if (
            metadata === undefined ||
            metadata.peerName !== request.name ||
            saved.envelope.agentId !== target.agentId ||
            !definitionDigestsEqual(saved.envelope.definitions, target.digests) ||
            !sameJson(saved.envelope.input, input) ||
            (inReplyTo === undefined || metadata.inReplyTo === undefined
              ? inReplyTo !== metadata.inReplyTo
              : !sameRef(inReplyTo, metadata.inReplyTo))
          )
            return yield* failure(operation, "conflict");
          yield* authorize(operation, "send", request, {
            threadId: saved.envelope.threadId,
            agentId: target.agentId,
          });
          yield* authorizeEnvelope(saved, operation);
        } else {
          if (
            current.log.records.filter(
              ({ record }) => record.payload._tag === "PeerMessagePrepared",
            ).length >= maxMessages
          )
            return yield* failure(operation, "capacity");
          let destinationThread: ThreadId;

          if (operation === "reply") {
            if (inReplyTo === undefined) return yield* failure(operation, "invalid-reference");

            const inbound = current.log.records.find(
              ({ record }) =>
                record.payload._tag === "UserInputRecorded" &&
                record.payload.messageAdmission !== undefined &&
                sameRef(record.payload.messageAdmission.message, inReplyTo),
            )?.record.payload;

            if (
              inbound?._tag !== "UserInputRecorded" ||
              inbound.messageAdmission === undefined ||
              inbound.messageAdmission.sender.agentId !== target.agentId
            )
              return yield* failure(operation, "invalid-reference");
            destinationThread = inbound.messageAdmission.returnAddress.threadId;
          } else {
            destinationThread = yield* deps.routes.resolve({
              source: current.address,
              principal,
              peerName: request.name,
              targetAgentId: target.agentId,
            });
          }

          const allowed = yield* authorize(operation, "send", request, {
            threadId: destinationThread,
            agentId: target.agentId,
          });

          const metadata = MessageAdmission.make({
            schemaVersion: 1,
            message,
            peerName: request.name,
            sender: current.address,
            returnAddress: current.address,
            ...(inReplyTo === undefined ? {} : { inReplyTo }),
          });

          const envelope = PreparedInput.make({
            schemaVersion: 1,
            threadId: destinationThread,
            agentId: target.agentId,
            definitions: target.digests,
            deliveryPrincipal: allowed.deliveryPrincipal,
            input,
            inputDigest: yield* digest(input),
            admissionKey: message.messageId,
            authorization: { policyId: "peer-message", decisionId: message.messageId },
            messageAdmission: metadata,
          });

          const encodedEnvelope = yield* Schema.encodeEffect(PreparedInput)(envelope).pipe(
            Effect.mapError(() => failure(operation, "invalid-input")),
          );

          const tail = yield* deps.store
            .inspectTail(ThreadTailRequest.make({ threadId }))
            .pipe(Effect.mapError(mapStore(operation)));

          if (
            tail.tailSequence !== current.log.tailSequence ||
            tail.tailDigest !== current.log.tailDigest
          )
            continue;
          const createdAtMillis = yield* Clock.currentTimeMillis;

          yield* deps.failpoint
            .hit("peer:before-prepared-append")
            .pipe(Effect.mapError(mapStore(operation)));

          const appended = yield* deps.store
            .append(
              FencedAppendRequest.make({
                threadId,
                producerEpoch: tail.producerEpoch,
                expectedTailSequence: tail.tailSequence,
                expectedTailDigest: tail.tailDigest,
                batch: CanonicalBatch.make({
                  batchId: Schema.decodeSync(BatchId)(message.messageId),
                  producerId: deps.producerId,
                  records: [
                    RecordEnvelope.make({
                      recordId: Schema.decodeSync(RecordId)(message.messageId),
                      family: "thread",
                      schemaVersion: 1,
                      createdAt: DateTime.makeUnsafe(createdAtMillis),
                      deploymentId: deps.deploymentId,
                      payload: PeerMessagePrepared.make({
                        messageId: message.messageId,
                        encodedEnvelope,
                        sourcePrincipal: principal,
                        operation,
                        deadlineAtMillis: createdAtMillis + window,
                      }),
                    }),
                  ],
                }),
              }),
            )
            .pipe(
              Effect.as(true),
              Effect.catchTag(["AppendConflict", "FenceRejected"], () => Effect.succeed(false)),
              Effect.mapError(mapStore(operation)),
            );

          if (!appended) continue;
          yield* deps.failpoint
            .hit("peer:after-prepared-append")
            .pipe(Effect.mapError(mapStore(operation)));
          saved = {
            envelope,
            sourcePrincipal: principal,
            operation,
            createdAtMillis,
            deadlineAtMillis: createdAtMillis + window,
          };
        }

        const prepared = yield* prepareMessageDelivery({
          key: message,
          envelope: saved.envelope,
          createdAtMillis: saved.createdAtMillis,
          deadlineAtMillis: saved.deadlineAtMillis,
        }).pipe(
          Effect.provideService(Crypto.Crypto, deps.crypto),
          Effect.mapError(mapStore(operation)),
        );

        return status(yield* store.insert(prepared).pipe(Effect.mapError(mapStore(operation))));
      }

      return yield* failure(operation, "capacity");
    });

    const lookup = Effect.fn("MessagingHost.lookup")(function* (
      request: PeerTarget & { readonly message: MessageRef },
      operation: "inspect" | "retry",
    ) {
      yield* authorize(operation, operation === "inspect" ? "read" : "control", request);

      const message = yield* Schema.decodeUnknownEffect(MessageRef)(request.message).pipe(
        Effect.mapError(() => failure(operation, "invalid-reference")),
      );

      if (message.ownerThreadId !== threadId) return yield* failure(operation, "denied");
      const store = yield* deliveries(operation);
      const row = yield* store.get(message).pipe(Effect.mapError(mapStore(operation)));

      if (row === null) return yield* failure(operation, "not-found");
      if (
        row.envelope.messageAdmission?.peerName !== request.name ||
        row.envelope.agentId !== request.target.id
      )
        return yield* failure(operation, "invalid-reference");
      yield* authorize(operation, operation === "inspect" ? "read" : "control", request, {
        threadId: row.envelope.threadId,
        agentId: row.envelope.agentId,
      });

      return { row, store };
    });

    return {
      context: authorize("context", "context").pipe(
        Effect.map(
          (source): WorkerSource => toolSource ?? { _tag: "programmatic", ...source.address },
        ),
      ),
      send: (request) => send(request, "send"),
      reply: (request) => send(request, "reply"),
      inspect: (request) => lookup(request, "inspect").pipe(Effect.map(({ row }) => status(row))),
      retry: Effect.fn("MessagingHost.retry")(function* (request) {
        const { row, store } = yield* lookup(request, "retry");

        yield* authorizeEnvelope(yield* proof(row.key), "send");
        const nowMillis = yield* Clock.currentTimeMillis;

        return status(
          yield* store
            .change(row.key, {
              _tag: "Recover",
              expectedVersion: row.version,
              nowMillis,
              deadlineAtMillis: nowMillis + (yield* lifetime),
            })
            .pipe(Effect.mapError(mapStore("retry"))),
        );
      }),
      inbox: Effect.fn("MessagingHost.inbox")(function* (request) {
        const current = yield* authorize("inbox", "read", request);

        const limit = yield* Schema.decodeUnknownEffect(
          Schema.Int.check(Schema.isGreaterThan(0), Schema.isLessThanOrEqualTo(100)),
        )(request.limit).pipe(Effect.mapError(() => failure("inbox", "capacity")));

        let after = yield* Schema.decodeUnknownEffect(CanonicalSequence)(request.after ?? 0).pipe(
          Effect.mapError(() => failure("inbox", "invalid-reference")),
        );

        const items: Array<(typeof InboxPage.Type)["items"][number]> = [];

        while (after < current.log.tailSequence && items.length < limit) {
          const records = yield* Stream.runCollect(
            deps.store.read(ThreadRead.make({ threadId, afterSequence: after, limit: 1_024 })),
          ).pipe(Effect.mapError(() => failure("inbox", "storage")));

          if (records.length === 0) break;
          for (const entry of records) {
            if (entry.sequence > current.log.tailSequence) break;
            after = entry.sequence;
            const payload = entry.record.payload;

            if (
              payload._tag === "UserInputRecorded" &&
              payload.messageAdmission?.sender.agentId === request.target.id
            ) {
              yield* authorize("inbox", "read", request, payload.messageAdmission.sender);
              items.push({ sequence: entry.sequence, admission: payload.messageAdmission });
            }
            if (items.length >= limit) break;
          }
        }

        return { items, next: after < current.log.tailSequence ? after : null };
      }),
    };
  };

  return {
    acquire: Effect.fn("MessagingHost.acquire")(function* (request: {
      readonly sourceThreadId: ThreadId;
      readonly principal: Principal;
    }) {
      const service = facet(request.sourceThreadId, request.principal);

      yield* service.context;

      return service;
    }),
    forTool: (source: WorkerSource, principal: Principal) =>
      facet(source.threadId, principal, source),
    validateAdmission: Effect.fn("MessagingHost.validateAdmission")(function* (
      unvalidated: MessageAdmission,
      options: DurableSubmitOptions,
      agentId: AgentId,
      inputDigest: Digest,
    ) {
      const admission = yield* Schema.decodeUnknownEffect(MessageAdmission)(unvalidated).pipe(
        Effect.mapError(() => failure("send", "invalid-input")),
      );

      const saved = yield* proof(admission.message);
      const envelope = saved.envelope;

      if (
        envelope.messageAdmission === undefined ||
        !sameAdmission(envelope.messageAdmission, admission) ||
        envelope.threadId !== options.threadId ||
        envelope.agentId !== agentId ||
        envelope.inputDigest !== inputDigest ||
        envelope.deliveryPrincipal !== options.principal ||
        envelope.admissionKey !== options.idempotencyKey ||
        !definitionDigestsEqual(envelope.definitions, options.definitions)
      )
        return yield* failure("send", "denied");
      yield* authorizeEnvelope(saved, "send");

      return admission;
    }),
  };
});

/** Count UTF-8 bytes without allocating an encoded copy of the string. */
export const utf8ByteLength = (value: string): number => {
  let bytes = 0;
  let index = 0;

  while (index < value.length) {
    const codePoint = value.codePointAt(index) ?? 0;

    bytes += codePoint <= 0x7f ? 1 : codePoint <= 0x7ff ? 2 : codePoint <= 0xffff ? 3 : 4;
    index += codePoint > 0xffff ? 2 : 1;
  }

  return bytes;
};

import type * as Agent from "@effect-agent/core/Agent";
import { AgentPolicy } from "@effect-agent/core/AgentPolicy";
import { ThreadId, type SubmissionId } from "@effect-agent/core/Identifiers";
import { IdempotencyKey, type Receipt } from "@effect-agent/core/Receipt";
import { SubagentDelegationCaps, SubagentGrant } from "@effect-agent/core/SubagentContract";
import {
  WorkerError,
  WorkerHistoryEntry,
  type WorkerContext,
  type WorkerRef,
} from "@effect-agent/core/Worker";
