      const reservations = yield* SubagentReservations;
      const snapshot = yield* reservations.parentSnapshot(runId);

      expect(snapshot.totalChildInvocations).toBe(1);
      expectSettledOnce(snapshot.reservations[0]);
    }),
  );
});

