  ToolCallFailed,
  ApprovalRequested,
  TurnCompleted,
  BudgetWarning,
  CompactionPerformed,
  RunCompleted,
  RunFailed,
  RunInterrupted,
  RunSuspended,
  SubagentRequested,
  SubagentStarted,
  SubagentProgress,
  SubagentCompleted,
  SubagentFailed,
  SubagentInterrupted,
