import { type CompactionPolicy } from "@effect-agent/core/AgentPolicy";
import { type RunId, type ThreadId } from "@effect-agent/core/Identifiers";
import { Context, Effect, Layer, Option, Schema, Stream } from "effect";
import { type LanguageModel, type Model, Prompt } from "effect/unstable/ai";

import { ContextHandoff, type ContextRolloverRequest } from "./ContextWindow.ts";
import {
  buildCompactedView,
  buildRolloverHandoff,
  choosePruneBound,
  chooseSummarizeCut,
  collectCoveredMessages,
  estimatePromptTokens,
  evaluateMessageTokenEstimates,
  renderForSummary,
  SUMMARY_MAX_LENGTH,
  SUMMARY_REQUEST_PREFIX,
  SUMMARY_REQUEST_SUFFIX,
  type ContextCompactionState,
} from "./internal/compaction.ts";

/**
 * A proposed view change. Source indices are exclusive prefix bounds, never record sequences.
 * Summaries contain at most 65,536 characters; the interpreter rejects oversized decisions
 * before committing or changing coverage.
 */
export const CompactionDecision = Schema.Union([
  Schema.Struct({
    kind: Schema.Literal("rollover"),
    through: Schema.Natural,
    handoff: Schema.optionalKey(ContextHandoff),
  }),
  Schema.Struct({ kind: Schema.Literal("clear-tool-results"), through: Schema.Natural }),
  Schema.Struct({
    kind: Schema.Literal("summarize"),
    through: Schema.Natural,
    summary: Schema.NonEmptyString.check(
      Schema.isMaxLength(SUMMARY_MAX_LENGTH),
      Schema.isPattern(/\S/),
    ),
  }),
]);

export type CompactionDecision = typeof CompactionDecision.Type;

/** Expected strategy or decision-validation failure. Causes stay in the live Effect only. */
export class CompactionError extends Schema.TaggedError<CompactionError>()("CompactionError", {
  message: Schema.String.check(Schema.isMaxLength(4_096)),
  cause: Schema.optionalKey(Schema.Defect()),
}) {}

/** Upstream Model.captureRequirements returns this closed Layer. */
export type CompactionModelLayer = Layer.Layer<
  LanguageModel.LanguageModel | Model.ProviderName | Model.ModelName
>;

/** A full message estimate, or undefined to use the native structural estimate. */
export type ContextMessageTokenEstimator = (message: Prompt.Message) => number | undefined;

/**
 * One bounded pass over an immutable source snapshot. A harness owns state, metering, and
 * application of decisions. The interpreter permits at most one prune followed by one replacement
 * (summary or rollover), and one call to summarize per Turn, shared across every trigger.
 * All model work must use summarize so it is metered.
 * Callback failures and requirements pass through unchanged; strategy dependencies belong to
 * its construction Layer. Protected messages cannot be removed and Tool pairs cannot be split by a decision.
 */
export interface CompactionRequest<E, R> {
  readonly threadId: ThreadId;
  readonly runId: RunId;
  readonly turn: number;
  readonly source: Prompt.Prompt;
  readonly state: Readonly<ContextCompactionState>;
  readonly policy: CompactionPolicy;
  readonly targetTokens: number | undefined;
  readonly trigger: "pressure" | "overflow" | "requested";
  /** Budget admission may prohibit a separate model call while still allowing a rollover. */
  readonly modelCallAllowed: boolean;
  /** The current captured Model's message accounting, including native fallback. */
  readonly estimateMessageTokens?: ContextMessageTokenEstimator | undefined;
  /** Present for a successful, singleton context rollover Tool; through excludes later steering. */
  readonly requested?: (ContextRolloverRequest & { readonly through: number }) | undefined;
  readonly summarize: (
    prompt: Prompt.Prompt,
    model?: CompactionModelLayer,
  ) => Effect.Effect<string, E, R>;
}

export interface ContextCompaction {
  /** Non-negative finite integer estimate, used for admission and derived prompt overhead too. */
  readonly estimate: (messages: ReadonlyArray<Prompt.Message>) => number;
  /** Emit decisions sequentially; the consumer commits each before pulling the next. */
  readonly compact: <E, R>(
    request: CompactionRequest<E, R>,
  ) => Stream.Stream<CompactionDecision, E | CompactionError, R>;
}

const evaluateEstimates = <A>(
  override: ContextMessageTokenEstimator | undefined,
  operation: (estimate: (message: Prompt.Message) => number) => A,
): Effect.Effect<A, CompactionError> =>
  Effect.suspend(() => {
    const result = evaluateMessageTokenEstimates(override, operation);

    return Option.isSome(result)
      ? Effect.succeed(result.value)
      : CompactionError.make({
          message: "Message token estimator returned an invalid token count",
        });
  });

const defaultCompactor = (model?: CompactionModelLayer): ContextCompaction => ({
  estimate: estimatePromptTokens,
  compact: <E, R>(request: CompactionRequest<E, R>) =>
    Stream.unwrap(
      Effect.gen(function* () {
        const { source, policy, targetTokens, trigger, modelCallAllowed } = request;

        if (request.requested !== undefined) {
          return Stream.succeed({ kind: "rollover", ...request.requested });
        }
        const forceSummarize = trigger === "overflow";
        const state = { ...request.state };

        const keepRecentTokens =
          targetTokens === undefined
            ? policy.keepRecentTokens
            : Math.max(1, Math.min(policy.keepRecentTokens, targetTokens));

        const decisions: Array<CompactionDecision> = [];

        if (!forceSummarize && policy.mode !== "summarize") {
          const through = yield* evaluateEstimates(request.estimateMessageTokens, (estimate) =>
            choosePruneBound(source.content, state, keepRecentTokens, targetTokens, estimate),
          );

          if (through > state.clearedThrough) {
            state.clearedThrough = through;
            decisions.push({ kind: "clear-tool-results", through });
            if (
              targetTokens !== undefined &&
              (yield* evaluateEstimates(request.estimateMessageTokens, (estimate) =>
                estimatePromptTokens(buildCompactedView(source.content, state), estimate),
              )) <= targetTokens
            ) {
              return Stream.fromIterable(decisions);
            }
          }
        }
        const prune = Stream.fromIterable(decisions);

        if ((!modelCallAllowed || policy.mode === "prune") && !forceSummarize) return prune;

        return prune.pipe(
          Stream.concat(
            Stream.unwrap(
              Effect.gen(function* () {
                const through = yield* evaluateEstimates(
                  request.estimateMessageTokens,
                  (estimate) =>
                    chooseSummarizeCut(source.content, state, keepRecentTokens, estimate),
                );

                const covered = collectCoveredMessages(source.content, state, through);

                if (covered.length === 0) return Stream.empty;

                const transcript = renderForSummary(
                  covered,
                  state.replacement?.kind === "summarize"
                    ? state.replacement.summary
                    : state.replacement?.handoff,
                );

                if (transcript === undefined) {
                  return yield* CompactionError.make({
                    message: `Previous compaction summary exceeds ${SUMMARY_MAX_LENGTH} characters`,
                  });
                }

                const prompt = Prompt.fromMessages([
                  Prompt.userMessage({
                    content: [
                      Prompt.textPart({
                        text: `${SUMMARY_REQUEST_PREFIX}${transcript}${SUMMARY_REQUEST_SUFFIX}`,
                      }),
                    ],
                  }),
                ]);

                const text = yield* request.summarize(prompt, model);

                return Stream.succeed({
                  kind: "summarize",
                  through,
                  summary: text.trim(),
                } satisfies CompactionDecision);
              }),
            ),
          ),
        );
      }),
    ),
});

/**
 * The sole interpreter compaction port. Runs without an installed service provide layer at their
 * composition boundary. Decorators yield this service during construction and receive their
 * underlying implementation through Layer.provide. Direct harnesses use the same Layer contract.
 */
export class ContextCompactor extends Context.Service<ContextCompactor, ContextCompaction>()(
  "@effect-agent/engine/ContextCompactor",
) {
  static readonly layer = Layer.succeed(ContextCompactor, defaultCompactor());

  /**
   * Start fresh windows without a summarizer call. The engine retains instructions/input and
   * commits each boundary; a bounded emergency handoff preserves user inputs and unseen results.
   * Applications provide notes/history tools alongside this strategy.
   */
  static readonly layerRollover = Layer.succeed(ContextCompactor, {
    estimate: estimatePromptTokens,
    compact: <E, R>(request: CompactionRequest<E, R>) =>
      Stream.unwrap(
        Effect.gen(function* () {
          if (request.requested !== undefined) {
            return Stream.succeed({
              kind: "rollover",
              ...request.requested,
            } satisfies CompactionDecision);
          }

          // Trailing user steering may not be canonical until the next response. Keep it verbatim.
          const through =
            request.source.content.findLastIndex(
              (message) => message.role === "assistant" || message.role === "tool",
            ) + 1;

          if (collectCoveredMessages(request.source.content, request.state, through).length === 0) {
            return Stream.empty;
          }

          const handoff = yield* evaluateEstimates(request.estimateMessageTokens, (estimate) =>
            buildRolloverHandoff(
              request.source.content,
              request.state,
              request.targetTokens,
              through,
              estimate,
            ),
          );

          if (handoff === undefined)
            return Stream.fail(
              CompactionError.make({
                message: "Insufficient context capacity for an automatic rollover handoff",
              }),
            );

          return Stream.succeed({
            kind: "rollover",
            through,
            handoff,
          } satisfies CompactionDecision);
        }),
      ),
  });

  /** Use the bounded default algorithm with a separate upstream Effect AI Model. */
  static readonly layerWithModel = <Provider, Requirements>(
    model: Model.Model<Provider, LanguageModel.LanguageModel, Requirements>,
  ): Layer.Layer<ContextCompactor, never, Requirements> =>
    Layer.effect(
      ContextCompactor,
      Effect.map(model.captureRequirements, (captured) => defaultCompactor(captured)),
    );
}

import { RunId, ThreadId } from "@effect-agent/core/Identifiers";
import { Context, type Effect, Encoding, Schema } from "effect";

/** Model-authored continuation state; fuller notes belong in an application-owned memory store. */
export const ContextHandoff = Schema.NonEmptyString.check(
  Schema.isMaxLength(20_000),
  Schema.isPattern(/\S/),
  Schema.makeFilter((text) => Encoding.encodeHex(JSON.stringify(text)).length / 2 <= 32_768, {
    expected: "at most 32768 JSON-encoded UTF-8 bytes",
  }),
);

/** Successful output of an explicitly designated context-window Tool. */
export const ContextRolloverRequest = Schema.Struct({
  handoff: Schema.optionalKey(ContextHandoff),
});

export type ContextRolloverRequest = typeof ContextRolloverRequest.Type;

/**
 * Host-selected exclusive source-message boundary, applied at the next safe model seam.
 * Omit through to reset the prefix before the protected current instructions/input. The
 * engine resolves that prefix after preparation; an empty prior prefix needs no new window.
 */
export const ContextRolloverSelection = Schema.Struct({
  ...ContextRolloverRequest.fields,
  through: Schema.optionalKey(Schema.Natural),
});

export type ContextRolloverSelection = typeof ContextRolloverSelection.Type;

/**
 * Bounds resolved alongside the native model for one Turn. Output reserve must match the
 * selected provider configuration. Uncounted overhead includes only provider framing or image
 * token costs absent from the prompt estimate; prompt text, output contracts, and native Tool
 * schemas are counted by the engine. These are live-context bounds, not cumulative Run budgets.
 */
export class ModelCallContext extends Schema.Class<ModelCallContext>("ModelCallContext")({
  contextCapacity: Schema.Int.check(Schema.isGreaterThan(0)),
  maxInputTokens: Schema.optionalKey(Schema.Int.check(Schema.isGreaterThan(0))),
  outputReserveTokens: Schema.Natural,
  uncountedOverheadTokens: Schema.Natural,
}) {}

/**
 * Definition-owned control annotation. A successful singleton application Tool carrying this
 * annotation returns ContextRolloverRequest. The engine applies it at the next Turn seam,
 * including after durable Tool-result replay. A Tool name alone never grants this authority.
 */
export const ContextRolloverTool = Context.Reference<boolean>(
  "@effect-agent/engine/ContextRolloverTool",
  { defaultValue: () => false },
);

/** Best available live-context estimate, independent of cumulative Run budgets. */
export class ContextWindowStatus extends Schema.Class<ContextWindowStatus>("ContextWindowStatus")({
  threadId: ThreadId,
  runId: RunId,
  windowId: Schema.NonEmptyString.check(Schema.isMaxLength(256)),
  estimatedTokens: Schema.Natural,
  contextTokenLimit: Schema.NullOr(Schema.Natural),
  remainingTokens: Schema.NullOr(Schema.Natural),
}) {}

/** Engine-owned identity and context accounting for the current Run. */
export class ContextWindow extends Context.Service<
  ContextWindow,
  {
    readonly status: Effect.Effect<ContextWindowStatus>;
  }
>()("@effect-agent/engine/ContextWindow") {}

import { ToolCallId } from "@effect-agent/core/Identifiers";
import { Context, Schema } from "effect";
import type { Effect, Option } from "effect";
import type { Tool } from "effect/unstable/ai";

/**
 * Declared external execution class of one Tool, used by the durable runtime
 * to decide which Tool Calls need the prepared/settled uncertainty protocol:
 *
 * - `"readonly"`: the handler performs no external mutation. A crash between
 *   start and settlement is a free re-run; no prepared record is written.
 * - `"idempotent"`: the handler declares an external idempotency contract
 *   (it owns key derivation). Prepared/settled records are written and
 *   recovery may re-execute without reconciliation proof.
 * - `"uncertain"`: no external contract is declared. Prepared/settled records
 *   are written and recovery must reconcile or record an Unknown Outcome.
 */
export type ToolExecutionClassValue = "readonly" | "idempotent" | "uncertain";

/**
 * Effect AI Tool annotation key declaring a Tool's execution class, applied
 * with `Tool.annotate(ToolExecutionClass, "...")`.
 *
 * Unannotated Tools default to `"uncertain"`: security and durability
 * decisions are fail-closed, so the framework never infers a safer class
 * from a Tool's shape.
 */
export const ToolExecutionClass = Context.Reference<ToolExecutionClassValue>(
  "@effect-agent/engine/ToolExecutionClass",
  { defaultValue: () => "uncertain" },
);

/** Read a Tool's declared execution class, falling back to the fail-closed `"uncertain"` default. */
export const getToolExecutionClass = (tool: Tool.Any): ToolExecutionClassValue =>
  Context.get(tool.annotations, ToolExecutionClass);

/** Stable identity of one Step within one Tool Call: `(toolCallId, stepName)`. */
export interface RunStepKey {
  readonly toolCallId: ToolCallId;
  readonly stepName: string;
}

/** A previously committed Step result in its canonical encoded form. */
export interface PersistedStepResult {
  readonly encodedOutput: unknown;
}

/**
 * Dependency-neutral Step persistence seam implemented by a durable
 * coordinator and consumed by the engine-provided `DurableStep` service.
 *
 * `lookup` returns the committed result for a Step identity when one exists;
 * `commit` durably records one successful encoded output. Only success is
 * ever committed — recording failures would replay a transient failure
 * forever. Both operations are keyed by the deterministic `RunStepKey`, so
 * replays and racing writers dedupe on record identity in the adapter.
 */
export interface RunStepHook<Error = never, Requirements = never> {
  readonly lookup: (
    key: RunStepKey,
  ) => Effect.Effect<Option.Option<PersistedStepResult>, Error, Requirements>;
  readonly commit: (
    key: RunStepKey,
    encodedOutput: unknown,
  ) => Effect.Effect<void, Error, Requirements>;
}

/**
 * Typed failure of one `DurableStep.do` call.
 *
 * `duplicate-step-name` is an identity conflict: Step names must be
 * deterministic and unique within one Tool Call, and reuse would silently
 * replay another Step's recorded result. `recorded-result-invalid` is the
 * replay-with-different-content conflict: a committed result that no longer
 * decodes through the declared output Schema is never silently accepted.
 */
export class DurableStepError extends Schema.TaggedError<DurableStepError>()("DurableStepError", {
  stepName: Schema.String,
  reason: Schema.Literals([
    "duplicate-step-name",
    "lookup-failed",
    "recorded-result-invalid",
    "output-encoding-failed",
    "commit-failed",
    "no-active-tool-call",
  ]),
  message: Schema.String.check(Schema.isMaxLength(4_096)),
  toolCallId: Schema.optionalKey(ToolCallId),
  /** Diagnostic cause for the live Effect only; Run events retain the fixed public message. */
  cause: Schema.optionalKey(Schema.Defect()),
}) {}

/**
 * Service value provided locally by the engine to each Tool Call's handler.
 *
 * `do` runs one named Step with exactly-once-recorded, at-least-once-executed
 * semantics: a committed result decodes through `output` and returns without
 * executing the body; otherwise the body runs (a crash mid-body re-executes
 * on the next Attempt), the success is encoded through `output`, and only
 * then committed. The Schema argument is the canonical codec for the recorded
 * result, not decoration. A Step never makes a non-idempotent external API
 * exactly-once — the body must use the external system's idempotency key,
 * reconciliation API, or compensating workflow.
 */
export interface DurableStepService {
  readonly do: <Output extends Schema.Top, BodyError, BodyServices>(
    name: string,
    output: Output,
    execute: Effect.Effect<Output["Type"], BodyError, BodyServices>,
  ) => Effect.Effect<
    Output["Type"],
    DurableStepError | BodyError,
    BodyServices | Output["DecodingServices"] | Output["EncodingServices"]
  >;
}

/**
 * Engine-owned Durable Step seam.
 *
 * Declaring this service in `Tool.make({ dependencies: [DurableStep] })` is
 * what makes a Tool a Durable Tool: its handler divides external effects into
 * named Steps and may be re-entered after interruption. The engine provides
 * the service locally to every Tool Call, bound to that call's identity; it
 * is never satisfied from an application Layer and is excluded from the
 * runtime's public requirements. Without a durable runtime the engine
 * provides an ephemeral pass-through that executes each Step once and
 * records nothing — the durable claim attaches to the runtime, not the Tool.
 */
export class DurableStep extends Context.Service<DurableStep, DurableStepService>()(
  "@effect-agent/engine/DurableStep",
) {}

import type { AnyDefinition } from "@effect-agent/core/Agent";
import {
  type InboxPage,
  type MessageRef,
  type MessageStatus,
  MessagingError,
} from "@effect-agent/core/Messaging";
import type { IdempotencyKey } from "@effect-agent/core/Receipt";
import type { WorkerSource } from "@effect-agent/core/Worker";
import { Context, type Effect } from "effect";

export interface PeerTarget {
  readonly name: string;
  readonly target: AnyDefinition;
}

/** A fixed declaration chooses the route. Caller input never selects a destination Thread. */
export interface SendPeerMessage extends PeerTarget {
  readonly encodedInput: unknown;
  readonly idempotencyKey: IdempotencyKey;
  /** Correlation on sends; replies additionally resolve and authorize the recorded return address. */
  readonly inReplyTo?: MessageRef;
}

/** Trusted per-invocation facet. It carries caller authority without exposing it in Tool schemas. */
export class MessagingHost extends Context.Service<
  MessagingHost,
  {
    readonly context: Effect.Effect<WorkerSource, MessagingError>;
    readonly send: (request: SendPeerMessage) => Effect.Effect<MessageStatus, MessagingError>;
    readonly reply: (
      request: SendPeerMessage & { readonly inReplyTo: MessageRef },
    ) => Effect.Effect<MessageStatus, MessagingError>;
    readonly inbox: (
      request: PeerTarget & { readonly after?: number; readonly limit: number },
    ) => Effect.Effect<InboxPage, MessagingError>;
    readonly inspect: (
      request: PeerTarget & { readonly message: MessageRef },
    ) => Effect.Effect<MessageStatus, MessagingError>;
    readonly retry: (
      request: PeerTarget & { readonly message: MessageRef },
    ) => Effect.Effect<MessageStatus, MessagingError>;
  }
>()("@effect-agent/engine/MessagingHost") {
  static readonly unavailable: MessagingHost["Service"] = {
    context: MessagingError.make({ operation: "context", reason: "unavailable" }),
    send: () => MessagingError.make({ operation: "send", reason: "unavailable" }),
    reply: () => MessagingError.make({ operation: "reply", reason: "unavailable" }),
    inbox: () => MessagingError.make({ operation: "inbox", reason: "unavailable" }),
    inspect: () => MessagingError.make({ operation: "inspect", reason: "unavailable" }),
    retry: () => MessagingError.make({ operation: "retry", reason: "unavailable" }),
  };

  /** Runtime-owned per-call binding. Unconfigured Runs deny peer operations. */
  static readonly forTool = Context.Reference<
    (source: Extract<WorkerSource, { readonly _tag: "tool" }>) => MessagingHost["Service"]
  >("@effect-agent/engine/MessagingHost/forTool", {
    defaultValue: () => () => MessagingHost.unavailable,
  });
}

import {
  type AgentId,
  type ThreadId,
  type DelegationId,
  type RunId,
  type ToolCallId,
} from "@effect-agent/core/Identifiers";
import { type DelegationDepth } from "@effect-agent/core/SubagentContract";
import { type RunTotals } from "@effect-agent/core/Usage";
import { Context, Schema } from "effect";
import type { Effect } from "effect";

/**
 * Shared identity carried by every pre-base Subagent event payload. The
 * emitting Tool handler supplies delegation lineage and its own Tool Call
 * identity; the engine stamps the remaining fields it is authoritative for
 * (`eventVersion`, `runId`, `threadId`, `agentId`, `sequence`,
 * `timestamp`, and the emitting batch's `turnId`) when the payload is woven
 * into the parent stream.
 */
export interface SubagentEventBasePayload {
  readonly toolCallId: ToolCallId;
  readonly delegationId: DelegationId;
  readonly childThreadId: ThreadId;
  readonly childRunId: RunId;
  readonly targetAgentId: AgentId;
  readonly depth: DelegationDepth;
}

/** Pre-base payload for the core `SubagentRequested` event. */
export interface SubagentRequestedPayload extends SubagentEventBasePayload {
  readonly _tag: "SubagentRequested";
}

/** Pre-base payload for the core `SubagentStarted` event. */
export interface SubagentStartedPayload extends SubagentEventBasePayload {
  readonly _tag: "SubagentStarted";
}

/** Pre-base payload for the core `SubagentProgress` event; `summary` is at most 4096 characters. */
export interface SubagentProgressPayload extends SubagentEventBasePayload {
  readonly _tag: "SubagentProgress";
  readonly summary: string;
}

/** Pre-base payload for the core `SubagentCompleted` event; `turns` is a positive integer. */
export interface SubagentCompletedPayload extends SubagentEventBasePayload {
  readonly _tag: "SubagentCompleted";
  readonly turns: number;
  readonly finishReason: "completed" | "model-stop" | "budget-exhausted";
  /** Dimension that bound when the child settled budget-exhausted (the RUN-021 grant-flow marker). */
  readonly exhausted?: "tokens" | "tool-calls" | "turns" | undefined;
  /** What the child spent, so a parent can account for delegated work. */
  readonly usage?: RunTotals | undefined;
}

/** Pre-base payload for the core `SubagentFailed` event; `message` is at most 4096 characters. */
export interface SubagentFailedPayload extends SubagentEventBasePayload {
  readonly _tag: "SubagentFailed";
  readonly errorTag: string;
  readonly message: string;
}

/** Pre-base payload for the core `SubagentInterrupted` event; `reason` is at most 4096 characters. */
export interface SubagentInterruptedPayload extends SubagentEventBasePayload {
  readonly _tag: "SubagentInterrupted";
  readonly reason: string;
}

/** Pre-base payload for the core `SubagentJoined` event. */
export interface SubagentJoinedPayload extends SubagentEventBasePayload {
  readonly _tag: "SubagentJoined";
}

/**
 * Discriminated union of pre-base Subagent lifecycle event payloads accepted
 * by `RunEventSink.emit`. Each variant is the corresponding core `RunEvent`
 * class minus the base fields the engine stamps. The stamped event is
 * constructed through the core Schema class, so core field checks (bounded
 * text, positive turns) still apply; violating them is a defect of the
 * emitting handler, not an expected failure.
 */
export type SubagentEventPayload =
  | SubagentRequestedPayload
  | SubagentStartedPayload
  | SubagentProgressPayload
  | SubagentCompletedPayload
  | SubagentFailedPayload
  | SubagentInterruptedPayload
  | SubagentJoinedPayload;

/** A handler emitted a Subagent event after its Tool batch had already settled. */
export class RunEventSinkClosedError extends Schema.TaggedError<RunEventSinkClosedError>()(
  "RunEventSinkClosedError",
  {
    message: Schema.String,
  },
) {}

/**
 * Service value accepted by Tool handlers to emit first-class Subagent
 * lifecycle events into the parent Run's semantic stream.
 *
 * The sink is backed by a bounded queue drained by the Run's own event stream.
 * A burst may suspend the emitting handler until that internal stream drains
 * capacity, but an external detached observer cannot backpressure the Tool
 * batch. Emitting after the owning Tool batch has settled — or outside any
 * Tool batch — fails closed with `RunEventSinkClosedError`.
 */
export interface RunEventSinkService {
  readonly emit: (payload: SubagentEventPayload) => Effect.Effect<void, RunEventSinkClosedError>;
}

/**
 * Engine-owned seam through which Tool handlers emit Subagent lifecycle
 * events onto the parent Run stream.
 *
 * The engine provides this service locally to every Tool batch, bound to that
 * batch's Run identity and Turn; it is never satisfied from an application
 * Layer and is excluded from the runtime's public requirements.
 */
export class RunEventSink extends Context.Service<RunEventSink, RunEventSinkService>()(
  "@effect-agent/engine/RunEventSink",
) {}

import { type AnyDefinition } from "@effect-agent/core/Agent";
import { type AgentInputError } from "@effect-agent/core/AgentError";
import { type AgentPolicy } from "@effect-agent/core/AgentPolicy";
import {
  type AgentId,
  type ThreadId,
  type DelegationId,
  type ReceiptId,
  type RunId,
  type SubmissionId,
  type ToolCallId,
  type TurnId,
} from "@effect-agent/core/Identifiers";
import { type MemoryRecallError } from "@effect-agent/core/MemoryReference";
import { RunPolicyUsage } from "@effect-agent/core/RunPolicyUsage";
import {
  type SubagentBudgetReservation,
  type DelegationDepth,
  type SubagentParentLink,
  type SubagentGrant,
  type ToolExecutionKind,
} from "@effect-agent/core/SubagentContract";
import type { Snapshot } from "@effect-agent/core/ToolExposure";
import { Selection } from "@effect-agent/core/ToolExposure";
import { type ModelCallUsage } from "@effect-agent/core/Usage";
import type { WorkerBudgetScope } from "@effect-agent/core/Worker";
import { type Cause, Effect, Context, type DateTime, Layer, Schema } from "effect";
import type { LanguageModel, Model, Prompt, Response } from "effect/unstable/ai";

import type { CompactionError, ContextMessageTokenEstimator } from "./ContextCompactor.ts";
import type { ContextRolloverSelection, ModelCallContext } from "./ContextWindow.ts";
import type { RunStepHook, ToolExecutionClassValue } from "./DurableStep.ts";

/** Live, trusted application diagnostics. Never persisted, transported, or automatically logged. */
interface ToolFailureIdentity {
  readonly agentId: AgentId;
  readonly threadId: ThreadId;
  readonly runId: RunId;
  readonly turnId: TurnId;
  readonly toolName: string;
  /** Best-effort error tag, with the existing `UnknownError` fallback. */
  readonly tag: string;
}

/** A model-declared Handler returned a declared failure instead of failing the Run. */
export interface ModelToolFailure extends ToolFailureIdentity {
  readonly _tag: "ModelToolFailure";
  readonly kind: "declared-failure";
  /** Raw provider identity, without the telemetry ID filter. */
  readonly toolCallId: ToolCallId;
  readonly executionClass: ToolExecutionClassValue;
  readonly message?: never;
  readonly cause?: never;
}

interface ProgrammaticToolFailureIdentity extends ToolFailureIdentity {
  readonly _tag: "ProgrammaticToolFailure";
  /** `${parentToolCallId}#${sequenceIndex}`, raw and unique only within this in-memory pass. */
  readonly toolCallId: string;
  readonly parentToolCallId: ToolCallId;
  /** Presence means the Handler started and consumed budget; side effects may exist. */
  readonly sequenceIndex: number;
  readonly executionClass: ToolExecutionClassValue;
}

interface ProgrammaticDeclaredFailure extends ProgrammaticToolFailureIdentity {
  readonly kind: "declared-failure";
  readonly message?: never;
  readonly cause?: never;
}

interface ProgrammaticHandlerFailure extends ProgrammaticToolFailureIdentity {
  readonly kind: "handler-error";
  readonly message?: never;
  /** The original, uncollapsed Cause captured before the broker's diagnostic projection. */
  readonly cause: Cause.Cause<unknown>;
}

interface ProgrammaticDiagnosticFailure extends ProgrammaticToolFailureIdentity {
  readonly kind: "infrastructure" | "protocol";
  /** At most 4096 UTF-8 bytes. Never a declared payload. */
  readonly message: string;
  /** Original Cause when one exists; never fabricated from a source-less rejection. */
  readonly cause?: Cause.Cause<unknown> | undefined;
}

/** A programmatic Handler started and its failure became a broker outcome. */
export type ProgrammaticToolFailure =
  | ProgrammaticDeclaredFailure
  | ProgrammaticHandlerFailure
  | ProgrammaticDiagnosticFailure;

/** A programmatic invocation was rejected before its Handler started. No inner identity exists. */
export interface ProgrammaticPreflightFailure extends ToolFailureIdentity {
  readonly _tag: "ProgrammaticPreflightFailure";
  readonly kind: "infrastructure" | "protocol";
  readonly parentToolCallId: ToolCallId;
  /** Absent if the Tool could not be resolved. */
  readonly executionClass?: ToolExecutionClassValue | undefined;
  /** At most 4096 UTF-8 bytes. */
  readonly message: string;
  /** Original Cause only for Cause-backed rejection, never fabricated from an outcome. */
  readonly cause?: Cause.Cause<unknown> | undefined;
}

/** Plain readonly interfaces, intentionally not persisted or transported Schemas (RUN-036). */
export type ToolFailureObservation =
  | ModelToolFailure
  | ProgrammaticToolFailure
  | ProgrammaticPreflightFailure;

/**
 * Trusted in-process observation of non-propagating application Tool failures (RUN-036).
 * Capture reporting dependencies before installation. Delivery is inline under the existing
 * Tool permit for started calls; preflight reporting is serialized per broker. Delivery is at
 * most once per in-memory attempt, with isolated observer/reporter defects.
 * External interruption may end delivery. Replacement Attempts may repeat IDs and observations.
 * Never reenter ToolBroker, RunEventSink, or Agent execution, or intentionally self-interrupt.
 */
export interface RunToolFailureObserver {
  readonly observe: (observation: ToolFailureObservation) => Effect.Effect<void>;
}

/** Resolved once per Run; durable coordinators capture it at Layer acquisition. Default absent. */
export const CurrentToolFailureObserver = Context.Reference<RunToolFailureObserver | undefined>(
  "@effect-agent/engine/CurrentToolFailureObserver",
  { defaultValue: () => undefined },
);

/** The sole installation seam, shared by ephemeral Runs and durable platform options. */
export const toolFailureObserverLayer = (observer: RunToolFailureObserver): Layer.Layer<never> =>
  Layer.succeed(CurrentToolFailureObserver)(observer);

/** Number of queued inputs consumed at one documented Turn seam. */
export const CommandDrainPolicy = Schema.Literals(["one", "all"]);
export type CommandDrainPolicy = typeof CommandDrainPolicy.Type;

/** Engine-normalized input command. Capability packages may adapt richer audit records to it. */
export interface RunInputCommand {
  readonly kind: "steering" | "follow-up";
  readonly input: Prompt.RawInput;
}

/**
 * Dependency-neutral input seam used by the interpreter.
 *
 * A capability adapter owns queue bounds and Scope finalization. The engine calls
 * `start` before the first drain, `drain` only at safe Turn seams, and `end`
 * exactly once when the Run leaves its Scope.
 */
export interface RunInputHook<Error = never, Requirements = never> {
  readonly start?: (() => Effect.Effect<void, Error, Requirements>) | undefined;
  readonly drain: (
    policy: CommandDrainPolicy,
  ) => Effect.Effect<ReadonlyArray<RunInputCommand>, Error, Requirements>;
  readonly end?: (() => Effect.Effect<void, never, Requirements>) | undefined;
}

/** Decision returned by an ephemeral approval adapter. */
export type RunApprovalDecision =
  | {
      readonly _tag: "approved";
      readonly reason?: string | undefined;
    }
  | {
      readonly _tag: "denied";
      readonly reason?: string | undefined;
    }
  | {
      readonly _tag: "unresolved";
      readonly reason?: string | undefined;
    };

/** Native Effect AI approval request enriched with stable Run identities. */
export interface RunApprovalRequest {
  readonly request: Response.ToolApprovalRequestPart;
  readonly threadId: ThreadId;
  readonly runId: RunId;
  readonly turnId: TurnId;
  readonly toolCallId: ToolCallId;
  readonly toolName: string;
  readonly parameters: unknown;
}

/** Dependency-neutral approval decision hook. */
export interface RunApprovalHook<Error = never, Requirements = never> {
  readonly request: (
    request: RunApprovalRequest,
  ) => Effect.Effect<RunApprovalDecision, Error, Requirements>;
}

/** Input passed to ordered context transformation and compaction adapters. */
export interface RunContextRequest {
  readonly threadId: ThreadId;
  readonly runId: RunId;
  readonly turnId: TurnId;
  readonly turn: number;
  /**
   * Official engine history for this Attempt before context preparation. The
   * engine never replaces or mutates this value. Durable prompt
   * reconstruction can produce a different model-visible basis afterward, so
   * adapters that need canonical retrieval should key it by the supplied Run
   * identities rather than infer durable state from this Prompt alone.
   */
  readonly source: Prompt.Prompt;
  /**
   * The exact model-visible final-output contract the engine appends to the
   * prepared prompt after this hook returns (RUN-028), or
   * undefined when the definition's output Schema cannot render to JSON
   * Schema. Exposed so a limit-targeting adapter can reserve the contract's
   * overhead in its own window calculation; the hook can size for the
   * contract but cannot remove or alter it.
   */
  readonly outputContract?: string | undefined;
}

/**
 * One captured provider configuration and its context bounds. Build the native Model Layer
 * from the same resolved values as context; do not defer route selection inside its requests.
 * Capture provider requirements in the preparation Layer. The engine acquires this closed
 * Layer once per Turn and keeps it through compaction, dispatch, accounting, and overflow retry.
 */
export interface ResolvedModelCall {
  readonly model: Layer.Layer<LanguageModel.LanguageModel | Model.ProviderName | Model.ModelName>;
  readonly context: ModelCallContext;
  /**
   * The selected provider's native Tool schema transformer, such as toCodecOpenAI or
   * toCodecAnthropic. Omission uses generic JSON Schema and is suitable only when the provider
   * does not rewrite schemas. Select it from the same captured configuration as the Model Layer.
   * Provider-defined Tools count their native name/configuration arguments instead; their
   * provider-generated call parameter schemas are never transformed into function declarations.
   */
  readonly toolSchemaTransformer?: LanguageModel.CodecTransformer | undefined;
  /**
   * Replace the entire estimate of a message, including its framing, with a non-negative finite
   * integer. Undefined uses the native structural estimate for that message. Capture any model
   * or content-specific reservation before returning this callback; it must be deterministic for
   * copied message content and same-Turn retries, without consulting mutable provider state.
   * The engine shares it across admission, built-in compaction sizing, and default summaries.
   * Do not also charge a replaced message through uncountedOverheadTokens.
   */
  readonly estimateMessageTokens?: ContextMessageTokenEstimator | undefined;
}

/** Prepared model-only context returned by a context adapter. */
export interface PreparedRunContext {
  /** Replace non-pinned registered native Tools at this Turn boundary. */
  readonly toolSelection?: Selection | undefined;
  readonly prompt: Prompt.Prompt;
  /** Resolves actual model selection and admission together, once at this Turn boundary. */
  readonly modelCall?: ResolvedModelCall | undefined;
  /**
   * Start a fresh native context window even below capacity. Coverage must map to a complete
   * canonical prefix for durable Runs and cannot discard protected input or split Tool pairs.
   * Omit through to select prior history before this Run's protected instructions/input; this
   * is a no-op when no prior prefix remains, including after a committed reset is recovered.
   * Leave the source prefix intact; the engine commits and applies the selected rollover.
   */
  readonly rollover?: ContextRolloverSelection | undefined;
}

/**
 * Model-only prompt transformation. Compaction requires a safely mapped original
 * instruction/input block and content-equivalent covered prefixes across Turns.
 * Incompatible changes fail with CompactionError before compaction or model I/O.
 */
export interface RunContextHook<Error = never, Requirements = never> {
  /**
   * Resources acquired by `prepare` belong to the current Turn and close before
   * the next Turn starts. Acquire resources shared across Turns in a surrounding
   * Run Layer or Scope instead.
   */
  readonly prepare: (
    request: RunContextRequest,
  ) => Effect.Effect<PreparedRunContext, Error, Requirements>;
}

/**
 * Supplies model-visible reference context for one Turn without changing the
 * prompt that compaction covers or the history that the engine commits.
 *
 * The engine treats the returned input as untrusted, validates it before
 * provider I/O, and includes it in the Turn's context and completion-reserve
 * admission. It never passes this input to the compaction summary Model. A
 * same-Turn provider-overflow retry reuses the loaded snapshot. Return an
 * empty Prompt when the Turn needs no references.
 */
export interface RunTransientContextHook<Error = never, Requirements = never> {
  readonly load: (
    request: RunContextRequest,
  ) => Effect.Effect<Prompt.RawInput, Error, Requirements>;
}

/** Context service failures retain their concrete tags and structured fields. */
export type RunContextPreparationError = AgentInputError | MemoryRecallError | CompactionError;

/**
 * One usage delta. Turn-boundary consumption charges `modelCalls: 1` after a
 * complete response and before any Tool starts; the programmatic Tool broker
 * charges `modelCalls: 0, toolCalls: 1` before each inner handler starts
 * (RUN-017).
 */
export interface RunUsageDelta {
  readonly modelCalls: 0 | 1;
  readonly inputTokens: number;
  readonly outputTokens: number;
  readonly totalTokens: number;
  readonly toolCalls: number;
  readonly costMicrousd: number;
  readonly usage: Response.Usage;
  /** Present for model-call deltas; absent for programmatic Tool-only charges. */
  readonly modelUsage?: ModelCallUsage | undefined;
}

/** Stable pricing identity returned alongside a host's microdollar estimate. */
export interface RunCostEstimate {
  readonly costMicrousd: number;
  readonly serviceTier?: string | undefined;
  readonly pricingVersion?: string | undefined;
  /** Unknown estimates do not prove a free call and fail an explicit cost budget after usage is retained. */
  readonly pricingStatus?: "estimated" | "unknown" | undefined;
}

/** A number preserves the original estimator API; the object form adds pricing provenance. */
export type RunCostEstimateValue = number | RunCostEstimate;

/** Model identity presented beside the legacy raw-usage estimator argument. */
export interface RunCostEstimateRequest {
  readonly provider: string;
  /** Configured binding identity; only response.model identifies the returned model. */
  readonly model: string;
  readonly usage: Response.Usage;
  /** Actual provider response fields, never the configured binding name. */
  readonly response?:
    | {
        readonly id?: string | undefined;
        readonly model?: string | undefined;
      }
    | undefined;
  /** Native Effect AI provider metadata, runtime-only; HTTP details are excluded. */
  readonly finishMetadata?: Response.FinishPart["metadata"] | undefined;
  readonly purpose?: "turn" | "summary" | undefined;
}

/**
 * Host-owned price lookup; durable hosts close every dependency before installing it. Raw usage
 * remains the first argument for source and runtime compatibility with the original estimator API.
 */
export type RunCostEstimator<Error = never, Requirements = never> = (
  usage: Response.Usage,
  request: RunCostEstimateRequest,
) => Effect.Effect<RunCostEstimateValue, Error, Requirements>;

/**
 * Dependency-neutral hierarchical budget hook. A typed failure at a Turn-seam
 * consumption or a stream-guard pull stops the Run. A mid-pass programmatic
 * consumption failure instead becomes that call's outcome (RUN-017 —
 * exhaustion prevents the call): the Run still stops at the next Turn seam,
 * because the following model call's `consume` and the guarded stream pulls
 * re-enforce the same budget.
 */
export interface RunBudgetHook<Error = never, Requirements = never> {
  /**
   * Guard one active model or Tool stream pull. Hierarchical budget adapters
   * use an absolute deadline so repeated pulls share one duration allowance.
   */
  readonly guard: <A, E, R>(
    effect: Effect.Effect<A, E, R>,
  ) => Effect.Effect<A, E | Error, R | Requirements>;
  readonly consume: (delta: RunUsageDelta) => Effect.Effect<void, Error, Requirements>;
}

/**
 * One application Tool Call of a completed Turn as the durable runtime sees
 * it: stable identity, the encoded (wire-form) parameters exactly as official
 * history carries them, and the Tool's declared execution class (fail-closed
 * `"uncertain"` for unannotated Tools).
 */
export interface RunToolCallDescriptor {
  readonly toolCallId: ToolCallId;
  readonly toolName: string;
  /** Encoded JSON parameters — the same value official history and canonical records carry. */
  readonly parameters: unknown;
  readonly executionClass: ToolExecutionClassValue;
  /** Definition-owned classification; never inferred from the Tool name. */
  readonly executionKind: ToolExecutionKind;
}

/** Decision returned by a host's action-time Tool authorization policy. */
export type RunToolAuthorizationDecision =
  | { readonly _tag: "allowed" }
  | { readonly _tag: "denied"; readonly reason: string };

/**
 * Exact authority presented before one application Tool Handler may start.
 *
 * `input` is the Agent Schema's encoded Run input. Durable coordinators replace it with the exact
 * canonical Submission input admitted for the logical Run on every Attempt.
 * `call` is the exact still-executable call being authorized. Recorded settled calls are never
 * reauthorized because no Handler can start for them.
 */
export interface RunToolAuthorizationRequest {
  readonly threadId: ThreadId;
  readonly runId: RunId;
  readonly turnId: TurnId;
  readonly turn: number;
  readonly input: unknown;
  readonly call: RunToolCallDescriptor;
  /** Present for an ephemeral inner invocation; the outer Tool's approval grants no inner authority. */
  readonly programmatic?:
    | {
        readonly parentToolCallId: ToolCallId;
        readonly sequenceIndex: number;
      }
    | undefined;
}

/** Host policy invoked before each executable native or programmatic application call. */
export interface RunToolAuthorizationHook<Error = never, Requirements = never> {
  readonly authorize: (
    request: RunToolAuthorizationRequest,
  ) => Effect.Effect<RunToolAuthorizationDecision, Error, Requirements>;
}

/**
 * Host-owned model-context preparation, independent of action-time Tool authorization.
 *
 * Runs use this service when provided; durable coordinators capture it while their runtime
 * Layer is acquired. Implementations acquire dependencies in their Layer and preserve the
 * declared error tags. Layer acquisition failures belong to the providing Effect, not this union.
 * Without this service, Runs apply no host context loading. Provide `ContextCompactor`
 * separately to select native compaction; neither service replaces `RunToolAuthorization`.
 */
export class RunContextPreparation extends Context.Service<
  RunContextPreparation,
  {
    /** Optional transformation of the model-visible prompt. */
    readonly hook?: RunContextHook<RunContextPreparationError, never> | undefined;
    /** Optional per-Turn reference context, excluded from history and compaction coverage. */
    readonly transientContext?:
      | RunTransientContextHook<RunContextPreparationError, never>
      | undefined;
  }
>()("@effect-agent/engine/RunContextPreparation") {}

/** Explicit no-preparer Layer used by compatible runtime assemblies. */
export const RunContextPreparationPassthrough: Layer.Layer<RunContextPreparation> = Layer.succeed(
  RunContextPreparation,
)({});

/**
 * Host action-time authority for native and programmatic application Tools. Implementations close over
 * their dependencies at Layer construction and return a denial when execution is not authorized.
 * Durable coordinators capture this service once and retain it across replacement Attempts.
 * Ephemeral Runs also resolve this service at their Run boundary. A typed per-run
 * `RunOptions.toolAuthorization` overrides it while retaining its own error and requirement channel.
 */
export class RunToolAuthorization extends Context.Service<
  RunToolAuthorization,
  RunToolAuthorizationHook
>()("@effect-agent/engine/RunToolAuthorization") {
  /** Explicit compatibility policy: Tool execution requires no additional host authorization. */
  static readonly allowAll: Layer.Layer<RunToolAuthorization> = Layer.succeed(
    RunToolAuthorization,
    { authorize: () => Effect.succeed({ _tag: "allowed" }) },
  );
}

/**
 * Payload of one durable response commit: the completed Turn's identity, its
 * response messages in official (encoded) form, and every application Tool
 * Call it declared. The engine invokes it only for Turns that declare
 * application Tool Calls; no-tool Turns keep their late single-batch commit.
 */
export interface RunTurnResponseCommit {
  readonly toolExposure?: Snapshot | undefined;
  readonly turn: number;
  readonly turnId: TurnId;
  /** The Turn's response messages in official history form (encoded Tool parameters). */
  readonly responseMessages: Prompt.Prompt;
  readonly calls: ReadonlyArray<RunToolCallDescriptor>;
}

/**
 * One compaction decision the engine applied to its model-visible view
 * (RUN-026). The durable coordinator maps the covered source prefix to complete canonical
 * records, including settled current-Run batches for rollover. It must never infer a wider cutoff
 * from policy or token estimates.
 */
export interface RunCompactionCommit {
  readonly turn: number;
  /** Exact pre-compaction source and exclusive message bound; live values, never persisted. */
  readonly source: Prompt.Prompt;
  readonly through: number;
  readonly kind: "clear-tool-results" | "summarize" | "rollover";
  /** Present exactly when `kind` is `"summarize"`. */
  readonly summary?: string | undefined;
  /** Optional continuation state for a rollover; never a generated summary. */
  readonly handoff?: string | undefined;
  readonly tokensBeforeEstimate: number;
  readonly tokensAfterEstimate: number;
}

/** One completed model call's provider-reported usage, staged for the Turn's canonical commit. */
export interface RunTurnUsage {
  readonly turn: number;
  readonly usage: ModelCallUsage;
}

/**
 * Attempt-local accounting for provider invocations without retained usage.
 * Staging is infallible and does not itself persist records. Durable runtime
 * composition supplies the canonical Turn accumulator; ephemeral entry points
 * explicitly supply the no-op implementation.
 */
export class ModelUsageAccounting extends Context.Service<
  ModelUsageAccounting,
  { readonly noteIncompleteUsage: (turn: number) => Effect.Effect<void> }
>()("@effect-agent/engine/ModelUsageAccounting") {
  static readonly layerEphemeral = Layer.succeed(ModelUsageAccounting, {
    noteIncompleteUsage: () => Effect.void,
  });
}

/**
 * Dependency-neutral durability seam implemented by a durable coordinator.
 *
 * Invocation ordering inside one Tool-declaring Turn is normative:
 * `commitResponse` fires after the finish part's continuation validations and staged canonical
 * provider/Turn events have been emitted, but before approval preflight (making the response
 * canonical before any Tool work — the provably-safe resume window); `prepareToolCalls` fires after
 * every approval and host authorization resolved allowed and before any handler acquires a
 * scheduler permit, with all delegations and non-`readonly` ordinary calls (it is skipped
 * entirely when no call needs preparation); `step` persists Durable Step
 * results mid-flight. When the hook is absent the engine behaves exactly as
 * the ephemeral runtime always has.
 */
export interface RunDurabilityHook<Error = never, Requirements = never> {
  /** Stage the exact request declarations for the existing canonical response append. */
  readonly noteToolExposure?:
    | ((turn: number, snapshot: Snapshot) => Effect.Effect<void, Error, Requirements>)
    | undefined;
  /**
   * Reserve cumulative programmatic calls and grace finalization before external execution.
   * Calls are serialized across the Run. A committed reservation
   * is never refunded, even if ownership is lost before the Handler or model starts.
   * Coordinators must append fenced, schema-backed records before returning.
   */
  readonly reservePolicyUsage?:
    | ((
        usage: Pick<RunPolicyUsage, "programmaticToolCalls" | "finalizationUsed">,
      ) => Effect.Effect<void, Error, Requirements>)
    | undefined;
  /** After validated staged response events are emitted, before approval preflight. */
  readonly commitResponse: (
    commit: RunTurnResponseCommit,
  ) => Effect.Effect<void, Error, Requirements>;
  /** After every approval and host authorization resolved allowed, before any handler starts. */
  readonly prepareToolCalls: (
    calls: ReadonlyArray<RunToolCallDescriptor>,
  ) => Effect.Effect<void, Error, Requirements>;
  readonly step: RunStepHook<Error, Requirements>;
  /**
   * RUN-026: called at the pre-Turn seam BEFORE the engine applies a
   * compaction to its model-visible view or starts the model call whose
   * prompt reflects it, so a crash between the two resumes onto the compacted
   * projection. Required by the durability protocol: a coordinator that
   * silently dropped the record would let the engine use a compacted prompt
   * that recovery cannot reproduce. Reject unpersistable decisions in the typed
   * error channel; success means the same replacement and coverage are durable.
   */
  readonly commitCompaction: (
    commit: RunCompactionCommit,
  ) => Effect.Effect<void, Error, Requirements>;
  /**
   * RUN-023: stage one completed model call's usage for the Turn's canonical
   * commit (the response record carries it for resume re-seeding). Staging is
   * not itself a durable mutation, but the member is required by the
   * durability protocol: dropping it writes response records without the
   * usage a later Attempt needs, so ownership changes would silently reset
   * token budgets instead of failing closed.
   */
  readonly noteTurnUsage: (usage: RunTurnUsage) => Effect.Effect<void, Error, Requirements>;
}

/**
 * `DefinitionDigests`-shaped digests of one child Agent Binding in plain
 * string form. The durable coordinator's thread-owned digest Schema never
 * crosses inward: the coordinator resolves these digests from the exact
 * registered target and stores and verifies them
 * byte-for-byte (SUB-023 exact-digest binding resolution).
 */
export interface RunSubagentDigests {
  readonly agent: string;
  readonly model: string;
  readonly tools: string;
}

/**
 * Establishment request assembled by a delegation Tool handler for the
 * durable coordinator, expressed strictly
 * in core/engine vocabulary. The coordinator derives everything else
 * deterministically: reservation identity from `(parentRunId, toolCallId)`,
 * child Thread/Submission identity and the admission idempotency key
 * from the parent Run and Tool Call pair, the child principal from the parent
 * Submission, and digests of the encoded input/grant/allocation values (it
 * owns the canonical digest authority). Establishment is idempotent by
 * construction (SUB-016): replaying the identical request converges on the
 * one existing child.
 */
export interface RunSubagentEstablishRequest {
  /** Resolved child defaults and ceilings, fixed before admission and restored on recovery. */
  readonly policy?: AgentPolicy | undefined;
  readonly budget?: SubagentBudgetReservation | undefined;
  readonly toolCallId: ToolCallId;
  readonly delegationId: DelegationId;
  readonly targetAgentId: AgentId;
  /** The child Run's root-relative delegation depth (S2 fixes the ceiling at 1). */
  readonly depth: DelegationDepth;
  /** Exact target Definition from the capability; the host resolves its existing registration. */
  readonly target?: AnyDefinition | undefined;
  /** Explicit low-level binding override. If a target is supplied, this must match its registration. */
  readonly targetDigests?: RunSubagentDigests | undefined;
  /** The prepared child input in encoded (wire) form; it rides the canonical request record so recovery admission never needs a live handler. */
  readonly encodedChildInput: unknown;
  /** The delegation's authority ceiling in encoded form. */
  readonly encodedGrant: unknown;
  /** The per-invocation budget allocation in encoded form (opaque to the engine and to storage adapters). */
  readonly encodedAllocation: unknown;
  /** Tightening-only child Tool Call bound, clamped to the reservation and Definition by the caller. */
  readonly toolCallAllowance?: number | undefined;
}

/** Durable identity of one established attached child, in core vocabulary. */
export interface RunSubagentChildIdentity {
  readonly childThreadId: ThreadId;
  readonly childSubmissionId: SubmissionId;
  readonly childRunId: RunId;
  /** The child Receipt: establishment is never durable-visible before it exists (SUB-017). */
  readonly receiptId: ReceiptId;
}

/** The established child has not settled; the parent must suspend, never poll or respawn (SUB-018). */
export interface ChildEstablishWaiting extends RunSubagentChildIdentity {
  readonly _tag: "waiting";
}

/**
 * The established child already has a verified canonical Settlement. The
 * coordinator verified Parent Link, target, digests, and settlement identity
 * fail-closed before returning it; `encodedResult` is the Schema-encoded
 * child terminal output for `completed` and the coordinator's bounded
 * `{errorTag, message}` failure projection otherwise — never a raw Cause.
 */
export interface ChildEstablishSettled extends RunSubagentChildIdentity {
  readonly _tag: "settled";
  readonly outcome: "completed" | "failed" | "aborted";
  readonly encodedResult: unknown;
  /**
   * Present when the child's durable Settlement carries the honest
   * exhaustion marker (RUN-011/RUN-018): the child completed through the
   * final-answer resolution, so its output is a budget-truncated partial.
   */
  readonly finishReason?: "budget-exhausted" | undefined;
}

/**
 * Establishment was refused or failed verification fail-closed (typed, bounded;
 * never a raw Cause). No further establishment attempt is made for this call.
 */
export interface ChildEstablishDenied {
  readonly _tag: "denied";
  readonly errorTag: string;
  readonly message: string;
}

/** Result of one idempotent durable child establishment attempt. */
export type ChildEstablishStatus =
  | ChildEstablishWaiting
  | ChildEstablishSettled
  | ChildEstablishDenied;

/**
 * One settlement join handed back to the coordinator by the delegation
 * handler after it decoded the verified child output and applied its bounded
 * result/failure projection. The coordinator appends `SubagentJoined` and the
 * parent `ToolCallSettled` as ONE atomic canonical batch (SUB-019) and then
 * applies the accounting decision through the idempotent reservation-release
 * transitions.
 */
export interface RunSubagentJoinRequest {
  readonly toolCallId: ToolCallId;
  /** The encoded parent Tool result exactly as the Tool message will carry it. */
  readonly encodedResult: unknown;
  readonly isFailure: boolean;
  /** Final consumed/released accounting decision per budget dimension (opaque encoded policy math owned by the delegation capability). */
  readonly encodedAccounting: unknown;
}

/**
 * Dependency-neutral durable-Subagent seam implemented by a durable
 * coordinator (S2 plan §2 option c) and consumed by the delegation Tool
 * handler through the engine-provided per-batch `SubagentDurability` service.
 *
 * `establish` performs (or replays) child establishment
 * under the parent's ownership fence and reports where
 * the one child stands; `join` atomically commits the verified settlement
 * join. When the hook is absent the engine provides the explicit
 * ephemeral-mode service and the S1 in-process spawn semantics apply honestly
 * — absence means no durable claim is being made.
 */
export interface RunSubagentHook<Error = never, Requirements = never> {
  readonly establish: (
    request: RunSubagentEstablishRequest,
  ) => Effect.Effect<ChildEstablishStatus, Error, Requirements>;
  readonly join: (request: RunSubagentJoinRequest) => Effect.Effect<void, Error, Requirements>;
}

/** One declared Tool Call of a Turn being resumed, in canonical encoded form. */
export interface RunTurnResumeCall {
  readonly id: string;
  readonly name: string;
  /** Canonical encoded parameters; re-validated through the Tool's parameter Schema before anything executes. */
  readonly params: unknown;
  /** Provider calls must have a canonical settled result and are never dispatched locally. */
  readonly providerExecuted?: boolean;
}

/**
 * One already-settled Tool Call of a Turn being resumed; injected without execution.
 *
 * The engine decodes this Schema at the recovery boundary before the value can
 * enter official history. The result remains the exact canonical JSON value
 * carried by the Tool message.
 */
export const RunTurnResumeSettledCallSchema = Schema.Struct({
  toolSelection: Schema.optionalKey(Selection),
  id: Schema.NonEmptyString,
  result: Schema.Json,
  isFailure: Schema.Boolean,
  /** Engine-owned rejection evidence; never inferred from the encoded result. */
  budgetRejected: Schema.optionalKey(Schema.Literal(true)),
});

export type RunTurnResumeSettledCall = typeof RunTurnResumeSettledCallSchema.Type;

/**
 * Canonical cumulative usage and Stop Policy accounting restored from prior Attempts.
 * Turns and declared Tool calls include a pending resumed batch. The failure
 * streak excludes that entire batch, whose terminal outcomes the engine folds once.
 * Programmatic reservations include pending work and are never refunded.
 *
 * Counts and microdollars are non-negative safe integers. The most recent
 * call cannot exceed its cumulative total. Every committed Turn has a model
 * call, and a failure streak cannot exceed the declared Tool call count.
 */
export const RunResumeUsageSchema = Schema.Struct({
  ...RunPolicyUsage.fields,
  modelCalls: Schema.Natural,
  inputTokens: Schema.Natural,
  outputTokens: Schema.Natural,
  lastInputTokens: Schema.Natural,
  lastOutputTokens: Schema.Natural,
  costMicrousd: Schema.Natural,
}).check(
  Schema.makeFilter(
    (usage) =>
      usage.lastInputTokens <= usage.inputTokens && usage.lastOutputTokens <= usage.outputTokens,
    {
      expected: "last-call token usage no greater than cumulative token usage",
    },
  ),
  Schema.makeFilter(
    (usage) =>
      usage.modelCalls >= usage.committedTurns && usage.consecutiveToolFailures <= usage.toolCalls,
    {
      expected:
        "model calls covering committed Turns and a failure streak within declared Tool calls",
    },
  ),
);

export type RunResumeUsage = typeof RunResumeUsageSchema.Type;

/**
 * Resume one canonically declared Tool batch without re-invoking the model.
 *
 * When present, the engine's first Turn skips the model request entirely: the
 * declared calls are re-validated through their Tool parameter Schemas (a
 * decode failure executes nothing), approval preflight runs against recorded
 * decisions, host Tool authorization is re-evaluated, `prepareToolCalls` replays the full
 * prepared batch idempotently,
 * calls listed in `settled` are injected as final results without starting
 * their handlers, and only the remaining open calls execute. The Run then
 * proceeds through the normal continuation.
 */
export interface RunTurnResume {
  readonly toolExposure?: Snapshot | undefined;
  readonly turn: number;
  readonly turnId: TurnId;
  readonly calls: ReadonlyArray<RunTurnResumeCall>;
  readonly settled: ReadonlyArray<RunTurnResumeSettledCall>;
  /**
   * The pending Turn's committed LEADING messages — the messages the durable
   * coordinator committed inside the pending Turn's canonical response record
   * BEFORE the assistant tool-call message (Turn-1 evaluated instructions +
   * input, or steering drained at the prior seam). A resumed Attempt's
   * canonical prompt boundary excludes the pending Turn entirely, so without
   * this field those messages would be absent from the resumed Run's live
   * model context. When present the engine threads them into official history
   * between the re-evaluated initial prompt and the rebuilt assistant
   * tool-call message. Optional: absent keeps the prior behavior byte-for-byte.
   */
  readonly leadingMessages?: Prompt.Prompt | undefined;
  /**
   * The pending Turn's canonical assistant response, including text, reasoning and provider
   * options. Durable hosts pass the decoded response after its leading messages. Execution
   * still uses the independently validated `calls`; this exact response enters history instead
   * of reconstructing it from call descriptors that cannot preserve every provider field.
   */
  readonly responseMessages?: Prompt.Prompt | undefined;
}

/** Run-level scheduler override; it may only make the Agent's finite bound stricter. */
export const RunSchedulingOverride = Schema.Union([
  Schema.Struct({
    mode: Schema.Literal("bounded"),
    concurrency: Schema.Int.check(Schema.isGreaterThan(0)),
  }),
  Schema.Struct({ mode: Schema.Literal("sequential") }),
]);

export type RunSchedulingOverride = typeof RunSchedulingOverride.Type;

/** Dependency-neutral scheduling policy surrounding native Effect AI Tool handlers. */
export interface RunSchedulingHook {
  readonly runOverride?: RunSchedulingOverride | undefined;
  readonly toolRequiresSequential?: ((toolName: string) => boolean) | undefined;
}

/**
 * Host Tool scheduling, captured by durable runtimes across replacement Attempts.
 * The Agent's admitted concurrency remains the upper bound. A sequential Tool
 * forms a barrier around neighboring parallel batches, including on recovery.
 * Ephemeral Runs may override this reference with `RunOptions.scheduling`.
 */
export const RunToolScheduling = Context.Reference<RunSchedulingHook>(
  "@effect-agent/engine/RunToolScheduling",
  { defaultValue: () => ({}) },
);

/**
 * Tightening-only memory limits for one Run. The engine supplies finite ceilings for every field;
 * callers may lower them for a deployment or test but cannot widen the engine defaults.
 */
export interface RunBufferLimits {
  /** Maximum decoded response parts retained from one model call, including compaction calls. */
  readonly maxModelResponseParts?: number | undefined;
  /** Maximum conservative retained-byte estimate for one model response. */
  readonly maxModelResponseBytes?: number | undefined;
  /** Maximum semantic Run events, including the reserved terminal event. */
  readonly maxRunEvents?: number | undefined;
  /**
   * Maximum cumulative UTF-8 JSON bytes in published ToolProgress results, including provider
   * progress and detached replay. Defaults to 8 MiB. Invalid or oversized application progress
   * fails with ModelProtocolError; terminal Tool results use the Agent's toolResultBounds.
   */
  readonly maxToolProgressBytes?: number | undefined;
  /** Maximum Subagent lifecycle payloads queued by one Tool batch. */
  readonly maxSubagentEventsPerBatch?: number | undefined;
}

/**
 * Per-Run values and advanced integration hooks. Use ThreadHistory for successful-run
 * retention. Hook failures and requirements stay visible in the returned Stream / Effect
 * through the generic parameters.
 */
export interface RunOptions<HookError = never, HookRequirements = never> {
  /** Initial or canonically restored run-scoped native selection. */
  readonly toolSelection?: Selection | undefined;
  /**
   * Host preparation boundary before each new model Turn, including its context preparation
   * and compaction calls. The preceding Tool batch and history advance have finished. A resumed
   * canonical Tool batch bypasses this hook until it continues to a new Turn. This hook does not
   * reset the Run deadline or change prompt protection, and is not automatically inherited by spawned children.
   * Resources acquired here close with the current Turn, before the next Turn starts.
   */
  readonly beforeTurn?: (() => Effect.Effect<void, HookError, HookRequirements>) | undefined;
  /** Reuse a Thread identity, including retained history, instead of allocating one. */
  readonly threadId?: ThreadId | undefined;
  /**
   * Preallocated Run identity used instead of `IdGenerator` when supplied.
   * The S1 Subagent seam preallocates child Run identity through this option
   * so `SubagentRequested` can carry the intended child identity.
   */
  readonly runId?: RunId | undefined;
  /** Canonically reconstructed window identity for a resumed durable Run. */
  readonly initialContextWindowId?: string | undefined;
  /** Last unconsumed, settled singleton application Tool in this Run; the engine verifies its control annotation. */
  readonly pendingContextToolCallId?: string | undefined;
  /** Canonical instruction/input block for durable recovery; not re-evaluated Attempt input. */
  readonly protectedContext?: Prompt.Prompt | undefined;
  /**
   * Non-model-visible Parent Link for a delegated child Run (S1 seam). It
   * never enters the model prompt or the Run's event payloads directly; the
   * engine uses it only to fix the Run's delegation depth (`parentLink.depth`
   * for a child, `0` when absent) exposed through the locally provided
   * `AgentSpawner`, and future durable work persists it as child lineage.
   */
  readonly parentLink?: SubagentParentLink | undefined;
  /** Durable background provenance supplies depth independently of attached parent linkage. */
  readonly delegationDepth?: number | undefined;
  /** Immutable narrowed authority restored for every delegated Attempt. */
  readonly subagentGrant?: SubagentGrant | undefined;
  /** Reserved subtree frame; descendants may spend only the residual after this Run's own ceiling. */
  readonly subagentBudget?: SubagentBudgetReservation | undefined;
  /** Native host funding provenance; never inferred from absent allocation amounts. */
  readonly subagentBudgetScope?: WorkerBudgetScope | undefined;
  /**
   * Explicit initial Prompt data, not a retention policy. With ThreadHistory.layerTransient,
   * the engine preserves this exact prefix, then appends this Run's evaluated instructions and
   * rendered input. Context preparation never mutates this source. Retaining ThreadHistory
   * adapters load their own prefix and reject this option, even when the Prompt is empty.
   */
  readonly history?: Prompt.Prompt | undefined;
  readonly commandDrainPolicy?: CommandDrainPolicy | undefined;
  readonly input?: RunInputHook<HookError, HookRequirements> | undefined;
  readonly approval?: RunApprovalHook<HookError, HookRequirements> | undefined;
  /** Per-Run override of RunContextPreparation.hook, preserving application-specific E/R. */
  readonly context?: RunContextHook<HookError, HookRequirements> | undefined;
  /**
   * Per-Run override of RunContextPreparation.transientContext. Use the service
   * for host configuration; this generic hook preserves application-specific E/R.
   * Model-visible reference context is loaded for each Turn, including a grace
   * finalization Turn and a Turn reconstructed by durable recovery. The engine
   * validates and budgets the result but never adds it to official history or
   * compaction coverage. A same-Turn provider-overflow retry reuses the Turn's
   * loaded snapshot.
   */
  readonly transientContext?: RunTransientContextHook<HookError, HookRequirements> | undefined;
  readonly budget?: RunBudgetHook<HookError, HookRequirements> | undefined;
  /**
   * Host-owned action-time authorization for model-declared application Tool batches. The engine
   * uses this per-Run override when present, otherwise the provided RunToolAuthorization service.
   * It invokes the policy for every still-executable call after complete-batch validation and approval, but
   * before durable preparation or any Handler permit. A resumed durable batch invokes it again
   * with the same canonical Run/Turn/input authority and Tool Call identity. Programmatic
   * `ToolBroker` calls invoke it after schema/visibility checks and before budget reservation or
   * execution, with their parent identity in `programmatic`. Inner denials become catchable
   * outcomes; other independent calls may already have completed.
   */
  readonly toolAuthorization?: RunToolAuthorizationHook<HookError, HookRequirements> | undefined;
  /**
   * Actual wall-clock start of the logical Run, used for elapsed-time status.
   * Durable coordinators supply the canonical `RunStarted` record timestamp on
   * every replacement Attempt. It is independent from `durationDeadline`,
   * which may tighten the remaining allowance without changing how long the
   * Run has existed (RUN-024/RUN-030).
   */
  readonly runStartedAt?: DateTime.Utc | undefined;
  /**
   * Optional absolute deadline for the Run's `maxDuration` rail. The engine
   * uses the earlier of this value and the fresh policy deadline, so callers
   * may preserve or tighten an existing Run allowance but can never widen it.
   * Durable coordinators derive this value from the canonical `RunStarted`
   * record timestamp and stored duration so replacement Attempts share one
   * wall-clock allowance (RUN-030).
   */
  readonly durationDeadline?: DateTime.Utc | undefined;
  /**
   * Durable turn-commit seam (P5). When absent the engine behaves exactly as
   * the ephemeral runtime: no response/prepared commits, and `DurableStep`
   * executes pass-through.
   */
  readonly durability?: RunDurabilityHook<HookError, HookRequirements> | undefined;
  /**
   * Durable-Subagent establishment/join seam (S2). When present the engine's
   * per-batch `SubagentDurability` service runs in durable mode over this
   * hook; when absent the service is the explicit ephemeral-mode default and
   * delegation Tools keep their S1 in-process spawn semantics unchanged.
   */
  readonly subagent?: RunSubagentHook<HookError, HookRequirements> | undefined;
  /**
   * Resume a declared, canonically committed Tool batch without re-invoking
   * the model (durable batch-resume seam). Consumed by the Run's first Turn.
   * Requires `resumeUsage`; missing or contradictory accounting fails with
   * `ModelProtocolError` before input, model, or Tool execution.
   */
  readonly resume?: RunTurnResume | undefined;
  /**
   * Cumulative usage and Stop Policy accounting of the Run's prior Attempts,
   * projected from canonical records. A fresh continuation starts at
   * `committedTurns + 1`; a pending batch uses the already-counted declarations
   * and folds its terminal outcomes onto the prior failure streak once.
   * Omit only for fresh Runs. Incomplete or invalid seeds fail typed before execution.
   * For a pending batch, `committedTurns` must equal `resume.turn`, `toolCalls`
   * must include every pending declaration, and the failure streak cannot
   * exceed the declared calls before that batch.
   */
  readonly resumeUsage?: RunResumeUsage | undefined;
  /**
   * Per-Run Tool Call allowance (RUN-021): a TIGHTENING-ONLY bound below the
   * Agent Policy's `maxToolCalls` — the effective limit is
   * `min(policy.maxToolCalls, max(1, floor(toolCallAllowance)))`, so an
   * allowance can never widen the Definition's ceiling. The `onExhaustion`
   * resolution (RUN-018) keys off the effective limit, which is how an
   * orchestrator grants a delegated child a budget extension by re-invoking
   * with a larger allowance up to the child Definition's policy.
   */
  readonly toolCallAllowance?: number | undefined;
  /**
   * Per-Run Turn allowance (RUN-021): tightening-only below the Agent
   * Policy's `maxTurns`, with the same normalization and the same
   * `onExhaustion` resolution (RUN-019 grace) at the effective limit.
   */
  readonly turnAllowance?: number | undefined;
  /** Required when the core policy declares `costBudgetMicrousd`. */
  readonly estimateCostMicrousd?: RunCostEstimator<HookError, HookRequirements> | undefined;
  readonly scheduling?: RunSchedulingHook | undefined;
  /** Optional tightening-only overrides for the engine's finite in-memory buffer ceilings. */
  readonly bufferLimits?: RunBufferLimits | undefined;
  /**
   * Advanced incremental history integration, used with ThreadHistory.layerTransient.
   * Invoked inline with the full Prompt whenever official history advances, including initial
   * instructions/input before the first model call. It can write before the Run succeeds or its
   * resources close. Failure stops execution through HookError; defects and interruption propagate.
   * Earlier callback writes are caller-owned and are not rolled back if this or a later step fails.
   * Use ThreadHistory for successful-run retention. Retaining adapters reject this hook;
   * the durable coordinator uses it for live Prompt state while its journal owns durable commits.
   */
  readonly onHistory?:
    | ((history: Prompt.Prompt) => Effect.Effect<void, HookError, HookRequirements>)
    | undefined;
}

export type RunOptionsError<Options> =
  Options extends RunOptions<infer Error, infer _Requirements> ? Error : never;

export type RunOptionsRequirements<Options> =
  Options extends RunOptions<infer _Error, infer Requirements> ? Requirements : never;

import type * as Agent from "@effect-agent/core/Agent";
import type { AgentPolicy } from "@effect-agent/core/AgentPolicy";
import type { DelegationId, RunId, SettlementId, ThreadId } from "@effect-agent/core/Identifiers";
import { type IdempotencyKey, type JoinedToHost, type Receipt } from "@effect-agent/core/Receipt";
import type { SubagentBudgetReservation } from "@effect-agent/core/SubagentContract";
import {
  WorkerError,
  type WorkerHistoryEntry,
  type WorkerContext,
  type WorkerBudgetScope,
  type WorkerSource,
  type WorkerPage,
  type WorkerRef,
  type WorkerStarted,
  type WorkerSummary,
} from "@effect-agent/core/Worker";
import type { Effect, Option } from "effect";
import { Context, Schema, Stream } from "effect";

/** Prepared values cross this port only to be Schema-decoded before durable storage. */
export interface StartWorkerRequest {
  readonly delegationId: DelegationId;
  readonly target: Agent.AnyDefinition;
  readonly idempotencyKey: IdempotencyKey;
  readonly encodedInput: unknown;
  readonly encodedParameters: unknown;
  readonly policy: AgentPolicy;
  readonly budget: SubagentBudgetReservation;
  readonly encodedGrant: unknown;
  readonly toolCallAllowance?: number;
  /** Author-owned request; the durable host must separately authorize worker-run funding. */
  readonly budgetScope?: WorkerBudgetScope;
}

export interface FollowUpWorkerRequest {
  readonly worker: WorkerRef;
  readonly target: Agent.AnyDefinition;
  readonly idempotencyKey: IdempotencyKey;
  readonly encodedInput: unknown;
  readonly encodedParameters: unknown;
}

export interface WorkerReceiptRequest {
  readonly worker: WorkerRef;
  readonly target: Agent.AnyDefinition;
  readonly receipt: Receipt;
}

/**
 * Canonical terminal values remain encoded until the capability decodes the saved parameters
 * and target output and applies its declared result projection. Child E does not survive settlement.
 */
export type WorkerObservation =
  | { readonly _tag: "Pending"; readonly receipt: Receipt }
  | {
      readonly _tag: "Settled";
      readonly receipt: Receipt;
      /** Absent when an input failed or was cancelled before any Run started. */
      readonly runId?: RunId;
      readonly settlementId: SettlementId;
      readonly outcome: "completed" | "failed" | "aborted";
      readonly encodedParameters: unknown;
      readonly encodedResult: unknown;
      readonly budgetExhausted: boolean;
    };

/** One actual canonical Run, independent of how many input Receipts joined it. */
export interface WorkerRunReport {
  readonly worker: WorkerRef;
  readonly context: WorkerContext;
  readonly observation: Extract<WorkerObservation, { readonly _tag: "Settled" }> & {
    readonly runId: RunId;
  };
}

/** A bounded projection failure; raw application errors never enter durable report records. */
export class WorkerReportPreparationFailure extends Schema.TaggedError<WorkerReportPreparationFailure>()(
  "WorkerReportPreparationFailure",
  { stage: Schema.Literals(["projection", "input", "preparation"]) },
) {}

/**
 * Source-registration-owned conversion from a child's outcome to new source input.
 * The concrete descriptor retains its E/R; durable registration captures R and records
 * bounded preparation failure rather than serializing arbitrary application errors.
 */
export interface WorkerReporting<E = never, R = never> {
  readonly delegationId: DelegationId;
  readonly target: Agent.AnyDefinition;
  readonly input: Schema.Top;
  /** Required when the receiving coordinator is itself an established worker. */
  readonly destination?: {
    readonly delegationId: DelegationId;
    readonly target: Agent.AnyDefinition;
  };
  readonly prepare: (report: WorkerRunReport) => Effect.Effect<
    {
      readonly encodedInput: Schema.Json;
      readonly encodedParameters?: Schema.Json;
    },
    E | WorkerReportPreparationFailure,
    R
  >;
}

/**
 * Trusted, caller-bound host port. The interpreter supplies a fresh facet for each Tool Call;
 * programmatic callers acquire a separately authorized Thread facet. Request values cannot
 * choose the source identity, replace worker provenance or expand its authority and budgets.
 */
export class SubagentHost extends Context.Service<
  SubagentHost,
  {
    readonly context: Effect.Effect<WorkerContext, WorkerError>;
    /** Resolve prepared input through host authority; None retains legacy target inheritance. */
    readonly resolveTargetPolicy: (request: {
      readonly target: Agent.AnyDefinition;
      readonly encodedInput: unknown;
    }) => Effect.Effect<Option.Option<AgentPolicy>, WorkerError>;
    readonly start: (request: StartWorkerRequest) => Effect.Effect<WorkerStarted, WorkerError>;
    readonly followUp: (request: FollowUpWorkerRequest) => Effect.Effect<Receipt, WorkerError>;
    readonly inspect: (
      request: WorkerReceiptRequest,
    ) => Effect.Effect<WorkerObservation, WorkerError>;
    /** Inspect the continuing worker using the same summary contract as discovery. */
    readonly summary: (request: {
      readonly worker: WorkerRef;
      readonly target: Agent.AnyDefinition;
    }) => Effect.Effect<WorkerSummary, WorkerError>;
    /** A finite snapshot through the captured tail; resume with the last sequence as `after`. */
    readonly observe: (request: {
      readonly worker: WorkerRef;
      readonly target: Agent.AnyDefinition;
      readonly after?: number;
    }) => Stream.Stream<WorkerHistoryEntry, WorkerError>;
    /** Interrupting this wait never requests cancellation of accepted work. */
    readonly await: (
      request: WorkerReceiptRequest,
    ) => Effect.Effect<WorkerObservation, WorkerError>;
    readonly list: (request: {
      readonly delegationId: DelegationId;
      readonly target: Agent.AnyDefinition;
      readonly limit: number;
      readonly after?: ThreadId;
    }) => Effect.Effect<WorkerPage, WorkerError>;
    /** Cancel exactly this Receipt; preserve JoinedToHost without broadening its target. */
    readonly cancel: (
      request: WorkerReceiptRequest,
    ) => Effect.Effect<void, WorkerError | JoinedToHost>;
  }
>()("@effect-agent/engine/SubagentHost") {
  static readonly unavailable: SubagentHost["Service"] = {
    context: WorkerError.make({ operation: "context", reason: "unavailable" }),
    resolveTargetPolicy: () => WorkerError.make({ operation: "start", reason: "unavailable" }),
    start: () => WorkerError.make({ operation: "start", reason: "unavailable" }),
    followUp: () => WorkerError.make({ operation: "followUp", reason: "unavailable" }),
    inspect: () => WorkerError.make({ operation: "inspect", reason: "unavailable" }),
    summary: () => WorkerError.make({ operation: "inspect", reason: "unavailable" }),
    observe: () => Stream.fail(WorkerError.make({ operation: "observe", reason: "unavailable" })),
    await: () => WorkerError.make({ operation: "await", reason: "unavailable" }),
    list: () => WorkerError.make({ operation: "list", reason: "unavailable" }),
    cancel: () => WorkerError.make({ operation: "cancel", reason: "unavailable" }),
  };

  /** Runtime-owned per-call binding. Unconfigured Runs deny background operations. */
  static readonly forTool = Context.Reference<
    (source: Extract<WorkerSource, { readonly _tag: "tool" }>) => SubagentHost["Service"]
  >("@effect-agent/engine/SubagentHost/forTool", {
    defaultValue: () => () => SubagentHost.unavailable,
  });
}

import { ThreadId, type RunId } from "@effect-agent/core/Identifiers";
import { type RunCompleted } from "@effect-agent/core/RunEvent";
import { Context, Effect, Layer, Schema } from "effect";
import type { Prompt } from "effect/unstable/ai";

/** A history adapter rejected a read, staged value, or completed Run commit. */
export class ThreadHistoryError extends Schema.TaggedError<ThreadHistoryError>()(
  "ThreadHistoryError",
  {
    threadId: ThreadId,
    reason: Schema.Literals([
      "not-found",
      "conflict",
      "fenced",
      "incompatible",
      "limit",
      "encoding",
      "storage",
    ]),
    message: Schema.String,
    cause: Schema.optionalKey(Schema.Defect()),
  },
) {}

/**
 * One Run's private staging area. Staging never commits history. Before commit, the interpreter
 * finishes run-owned work and closes resources acquired for that Run, then validates the result
 * for run/start.await. Shared model, provider, and client services supplied by an enclosing
 * application Layer remain owned by that application's Scope and may outlive multiple Runs.
 * Commit must succeed before RunCompleted becomes observable. Schema-encoded input is opaque
 * here; the adapter owns its persistence boundary. A failed commit may have reached storage;
 * callers must inspect history before retrying external execution.
 */
export interface ThreadHistoryRun {
  readonly prompt: Prompt.Prompt;
  readonly stageInput: (input: unknown) => Effect.Effect<void, ThreadHistoryError>;
  readonly stageHistory: (history: Prompt.Prompt) => Effect.Effect<void, ThreadHistoryError>;
  readonly commit: (completed: RunCompleted) => Effect.Effect<void, ThreadHistoryError>;
}

/**
 * Standard public API for retaining successful Runs through AgentRuntime.run, start, and stream.
 * Provide PersistentHistory.layer from thread/history with a memory or SQLite ThreadStore
 * Layer. Adapters capture storage dependencies; every Run gets private staging and append ownership.
 * Retaining adapters cannot share ownership with explicit history/onHistory, input queues, or
 * durable recovery hooks. Use layerTransient for those advanced integrations.
 * No implementation may retry model or Tool execution or claim interrupted-work recovery.
 */
export class ThreadHistory extends Context.Service<
  ThreadHistory,
  {
    readonly open: (request: {
      readonly threadId: ThreadId;
      readonly runId: RunId;
    }) => Effect.Effect<ThreadHistoryRun | undefined, ThreadHistoryError>;
    readonly load: (threadId: ThreadId) => Effect.Effect<Prompt.Prompt, ThreadHistoryError>;
  }
>()("@effect-agent/engine/ThreadHistory") {
  /**
   * Retain no shared history. Undefined staging leaves explicit history/onHistory and durable
   * journal hooks under their caller's ownership. Use a memory store with PersistentHistory
   * when completed Runs should share history for the lifetime of a process Scope.
   */
  static readonly layerTransient = Layer.succeed(ThreadHistory, {
    open: () => Effect.succeed(undefined),
    load: (threadId) =>
      Effect.fail(
        ThreadHistoryError.make({
          threadId,
          reason: "not-found",
          message: "Transient execution does not retain Thread history",
        }),
      ),
  });
}

import type { Effect } from "effect";
import { Context, Schema } from "effect";
import type { Tool, Toolkit } from "effect/unstable/ai";

/**
 * Programmatic Tool invocation seam for Code Mode (runtime spec §12.1,
 * ADR-0017 decision 3). The interpreter provides `ToolBroker` locally in the
 * same pattern as `AgentSpawner` and `DurableStep`: a fail-closed Run-level
 * default shadowed by a live per-outer-Tool-Call service, excluded from
 * `AgentRuntimeRequirements`. The live service is bound to the outer Tool
 * Call's identity, the Run's policy context, and the already-held scheduling
 * permit; per-call input from generated code is data only, and the broker
 * allocates every sequence index from its own monotonic per-pass state.
 */

/** One programmatic invocation request. Data only: the broker owns identity. */
export interface ProgrammaticToolInput {
  /** The exact Effect AI Tool name resolved by the capability's namespace map. */
  readonly toolName: string;
  /** Schema-encoded (wire-form) parameters, exactly as they cross the sandbox. */
  readonly encodedArguments: unknown;
}

/** The handler ran and settled with an owned JSON snapshot of its encoded success value. */
export interface ProgrammaticCallSuccess {
  readonly _tag: "ProgrammaticCallSuccess";
  /** Broker-owned invocation index within the pass; rejected calls leave gaps. */
  readonly index: number;
  readonly encodedResult: unknown;
}

/**
 * The handler settled with the Tool's declared, Schema-encoded typed failure
 * (an Effect AI `failureMode: "return"` result). The program may catch and
 * branch on it.
 */
export interface ProgrammaticCallFailure {
  readonly _tag: "ProgrammaticCallFailure";
  readonly index: number;
  readonly encodedResult: unknown;
}

/**
 * The call never produced a settled handler result: a broker preflight
 * rejected it (authorization, budget, unknown Tool, approval-requiring Tool,
 * invalid parameters), the handler failed in its typed error channel, or the
 * result failed encoding or the broker-owned size bound. `errorTag` and
 * `message` are the same bounded projection the direct path uses for
 * `ToolCallFailed` events; `index` is present only when the handler was
 * actually started (preflight rejections consume no identity and no budget).
 */
export interface ProgrammaticCallError {
  readonly _tag: "ProgrammaticCallError";
  readonly index: number | undefined;
  readonly errorTag: string;
  readonly message: string;
}

/**
 * Total outcome of one programmatic invocation; defects stay defects. Trusted applications may
 * install `CurrentToolFailureObserver` to receive non-propagating failures before the outcome
 * returns, with the live Cause retained before projection. Neither Causes nor observation values
 * cross the broker boundary.
 */
export type ProgrammaticCallOutcome =
  | ProgrammaticCallSuccess
  | ProgrammaticCallFailure
  | ProgrammaticCallError;

/**
 * Ephemeral execution evidence, ordered by invocation rather than completion. No arguments or
 * results are copied into this diagnostic. A started call without a confirmed result is uncertain;
 * a failed call is a confirmed failure, not a promise that external effects were rolled back.
 */
export const ProgrammaticCallRecord = Schema.Struct({
  sequenceIndex: Schema.Natural,
  toolName: Schema.String,
  status: Schema.Literals(["not-started", "succeeded", "failed", "uncertain"]),
  errorTag: Schema.optionalKey(Schema.String),
});

export type ProgrammaticCallRecord = typeof ProgrammaticCallRecord.Type;

/** Broker-owned per-pass policy for results crossing back into the sandbox. */
export interface ToolBrokerPassOptions {
  /** Maximum active invocations in this pass, from one through 64. Defaults to four. */
  readonly concurrency?: number | undefined;
  /**
   * Maximum UTF-8 byte size of one encoded success result at the sandbox
   * boundary. The returned value is decoded from the exact JSON representation
   * admitted by this bound, after redaction. Later handler or redactor mutations
   * cannot change it. The executor enforces its own transport bound independently.
   */
  readonly maxResultBytes: number;
  /**
   * Optional broker-owned redaction pass applied to every encoded success
   * result before the size bound. It must be total; a defect stays a defect.
   */
  readonly redactResult?: ((encodedResult: unknown) => Effect.Effect<unknown>) | undefined;
}

/**
 * One open programmatic pass, bound to one outer Tool Call. A finite Effect Semaphore bounds
 * execution. The caller owns invocation fibers and must join or interrupt them before leaving
 * its Scope. Results return as soon as they settle, without waiting for unrelated earlier calls.
 */
export interface ToolBrokerPass {
  readonly invoke: (input: ProgrammaticToolInput) => Effect.Effect<ProgrammaticCallOutcome>;
  /** Owned snapshot in invocation order, including interrupted and rejected calls. Never replay it. */
  readonly snapshot: Effect.Effect<ReadonlyArray<ProgrammaticCallRecord>>;
}

/** The broker was used outside a live Tool batch; there is nothing to bind to. */
export class ToolBrokerUnavailableError extends Schema.TaggedError<ToolBrokerUnavailableError>()(
  "ToolBrokerUnavailableError",
  {
    message: Schema.String,
  },
) {}

/**
 * The pass options are invalid — for example a `maxResultBytes` that is not
 * a positive safe integer, which would make the size comparison fail open.
 */
export class ToolBrokerConfigurationError extends Schema.TaggedError<ToolBrokerConfigurationError>()(
  "ToolBrokerConfigurationError",
  {
    message: Schema.String,
  },
) {}

/**
 * The engine-owned broker service. `openPass` fixes the capability-supplied
 * Toolkit and per-pass result policy once for the whole pass and captures the
 * handler services present at the call site, so nothing inside business
 * execution — least of all generated code — can substitute handlers, policy,
 * or identity afterwards.
 */
export interface ToolBrokerService {
  readonly openPass: <Tools extends Record<string, Tool.Any>>(
    toolkit: Toolkit.WithHandler<Tools>,
    options: ToolBrokerPassOptions,
  ) => Effect.Effect<
    ToolBrokerPass,
    ToolBrokerUnavailableError | ToolBrokerConfigurationError,
    Tool.HandlerServices<Tools[keyof Tools]>
  >;
}

/**
 * Engine-provided programmatic Tool broker (RUN-016, RUN-017). Declare it
 * with `.addDependency(ToolBroker)` on a Tool that performs programmatic
 * invocation; the interpreter supplies it, and an application Layer must not.
 */
export class ToolBroker extends Context.Service<ToolBroker, ToolBrokerService>()(
  "@effect-agent/engine/ToolBroker",
) {}

